"""The console worker — cognition behind the human's queue (0014 · 0006 · 0018 · 0019 · 0020).

Watches every floor's request queue and carries the residents' duties, keys staying
here in cognition (the plane verifies, never signs):

  · gather X  — the librarian: finds a SERVING search source on the Farm, meters the
    call, admits the findings as signed memories (quarantined at 0.0000) under the
    service's DID. No serving source → an honest refusal, never a silent nothing.
  · recall    — the librarian's 0014 §4 walk: when a source is discredited at the
    gate, charlotte hands the recall to the queue and the librarian re-versions
    every entry from that source — and everything derived from those — to
    'recalled'. Annotate-never-rewrite; the poison visibly dead in the Window.
  · purge     — the split model (0026): "forget about me" tombstones what the
    withdrawal silenced through the plane's one door (the subject's consent IS
    the quorum for their own data); an operational purge (kind "purge") SEALS
    its refs at machine speed and HOLDS — quorum 1 of 2, bars absolute (0012 §5);
    destruction waits for humans, plural. And the door remembers the infection:
    gather refuses a source the universe has recalled.
  · objective — the ladder (0027 · 0030): Objective · Intention · Observation ·
    Thought. An objective lands and is CURATED into a plan that STAGES at the
    human's gate — origin plans always wait for their human (0030 §3). Approval
    fans intentions DOWN the request queue (one intent, a budget slice, refs —
    never the whole); floors' fingertips carry them (kind "intention"), review
    grades every return with a critic marker (0024), and the resolution of YOUR
    request is the completion confirmation. One intention asks the human mid-flow
    (kind "question" — silence is denial); a seat beyond the token gets an
    entitlement ask, never a silent skip. The portfolio monitor beats on — R8.
  · workspace — the resident's room (0028): verb "workspace" on the parlor queue
    returns typed panels (stat · bars · list · doc) composed from state the
    resident may read; the glass renders blind, medium+ markers wear amber (0024).
  · improvement — the engine (0028): one improver stands on the universe floor,
    reads the receipts (rollups, markers, parked intents), and proposes a sibling
    version of a behavioral asset; governance computes the kind by DIFF and grades
    the lane — a nudge adopts loud on medium, a rewrite waits for the human.
  · serials   — the desk's beat (0032): due subscriptions re-gather through
    charlotte's SERVING roster only, dedup against the shelf, admit the new
    quarantined with the subscription's lineage, and the delivery note lands —
    a quiet issue logs, news wears the medium marker. The difference is the
    news (§3): a subscribed ref re-speaking with changed content admits AND
    drops its old head to investigating (superseded-at-source, the pair named);
    a ref the sweep no longer carries is noted vanished — absence is a finding,
    never an action. The desk never decides. The charter coupling (§4): an
    acquisition-shaped plan offers "…and keep it fresh" at its gate — checked
    and approved, the SAME word fans the plan and opens the subscription; the
    domain package names its supply line.
  · mirror    — 0034 sp3, JB's seed: a standing assessor (its own self, no seat,
    no voice) reads the Human↔Resident audiences each beat and updates BOTH
    sides — profile observations (untrusted, evidenced) and friction onto
    grace's shelf — with the interop ledger as receipt. Assessor ≠ assessed
    (0005); safer-mode exchanges were never written, so consent bounds it too.
  · consent   — 0034 §4: granting a ROLE access to a person's memory (or
    resuming a recording) STAGES at the human's gate with its bundle readable;
    revocation acts NOW — safety never waits. Consent withdrawn drops the
    parlor's recorder to SAFER MODE: exchanges are answered, never written;
    what was recorded under consent stays readable under its own grant. becky
    keeps the ledger — the sealed never delegates.
  · upload    — multimodal admission (0029): a file enters as an ask (verb
    "upload" to the librarian, bars 256KB · txt/md/json/csv/pdf/png/jpg). The
    artifact lands signed (ingested-archive); text-bearing formats extract to
    quarantined knowledge; formats needing an eye are admitted dark and their
    extraction intent PARKS — the retry list for the day a vision mind saddles.
  · join      — becky's door, HARDENED (JB's lock 2026-07-07): an agent asks to
    join; becky challenges it to sign a nonce (key control proven, names bind to
    real keys), stages the join for the HUMAN gate (0012 — consequence waits), and
    mints the root-chained lease only after both. Approval without proof earns a
    fresh challenge, never a token.
  · service   — charlotte, the farm keeper (0018): verifies staged plantings (probe,
    fetch manifest, pin hash), attests on human approval, heartbeats the toolshed,
    ages leases out, guards the rug-pull door on rejoin, and writes every lifecycle
    event as a signed MemoryRecord — the service's worldline. Nothing self-attests:
    the tool never wrote "SOME PIG" about itself.
  · mind      — ada, the wrangler (0019): probes the catalog on a staged saddle and
    pins the DEAL (pricing/context bytes), attests on human approval, canaries rookie
    minds through the governed gateway (metered under her own DID — residents think
    on-meter too), syncs the market for price drift and announced expiries, and
    stages recommendations instead of letting a sunset become an outage.
  · ecosystem — the Shipyard (0009's provisioner, on the wire): "create ecosystem
    foo with fields bar, baz" in becky's parlor drafts a launch plan, stages it for
    the human (growing the universe is consequential — 0012), and on approval the
    dock crew launches REAL containers on the rig's network. A NAMED TEMPLATE
    (0034: "create continuity ecosystem …") dresses every profile in the plan —
    the floor is born wearing the dignity vector, the retention regime (0033 §5
    contracts), and the label canon; the worker plants its CHARTER on the record. New floors pull their
    parent's floors at boot and beat into the orrery by themselves; the ledger
    (~/.orreth/shipyard/) replants hulls the rig lost, and the worker tends every
    dynamic floor's queue like the composed three.
  · demo      — the reel, from the glass: a whitelisted name rolls scripts/demo.sh
    in a background thread (the round keeps turning — the story's own requests need
    tending) and the transcript lands as the request's result when it ends.
  · parlor    — the audience room (0020): humans never read the world, they ask it.
    A resident receives the caller, fetches with its OWN authority, answers grounded
    (voiced through one governed, metered thought when the floor is fueled), and
    signs the exchange onto the spacetime window. Unembodied organs receive too,
    and say honestly that they have no voice yet.

Residents persist their seeds under ~/.orreth/residents/ — a keypair is a self, and
a self survives the process (0002 §1). Charlotte's ledger (~/.orreth/farm/) replants
the toolshed after a daemon restart, ada's (~/.orreth/stable/) re-saddles the stable:
the ledger seeds, the daemon holds live state, the worldline in the record store is
the history that outlives both.

    uv run python console_worker.py [join_port]      (leave running while you use the Console)
"""
