ALLEN_DID = crypto.did_key_for(ALLEN.public)
VERA = _seed("vera")                         # vera, the astronomer (0043 §2)
BELL = _seed("bell")                         # the bell — the last mile (0044 §2)
VERA_DID = crypto.did_key_for(VERA.public)
