def openrouter_catalog() -> list[dict]:
    """The market, read freely: OpenRouter's public list is INTEL for every stall,
    whatever route carries the call (0019 §1). Routing stays LiteLLM-direct on the
    floor's own keys by default. Cached on disk; a stale snapshot beats none."""
    cache = HOME / "stable" / "catalog.json"
    cache.parent.mkdir(parents=True, exist_ok=True)
    if cache.exists() and time.time() - cache.stat().st_mtime < CATALOG_TTL:
        return json.loads(cache.read_text())
    try:
        raw = json.loads(urllib.request.urlopen(urllib.request.Request(
            "https://openrouter.ai/api/v1/models"), timeout=15).read())
        cat = [{"id": m["id"], "provider": m["id"].split("/")[0],
                "pricing": m.get("pricing", {}),
                "context_length": m.get("context_length"),
                "modalities": (m.get("architecture") or {}).get("input_modalities", []),
                "created": m.get("created"),
                "expires_at": m.get("expiration_date")}
               for m in raw.get("data", [])]
        cache.write_text(json.dumps(cat))
        return cat
    except Exception:
        return json.loads(cache.read_text()) if cache.exists() else []


def deal(entry: dict) -> dict:
    """The manifest ada pins: the DEAL, not the name — pricing, context, modalities.
    Any byte of it moving under the pin is drift, and drift walks the rug-pull door."""
    return {"pricing": entry.get("pricing", {}),
            "context_length": entry.get("context_length"),
            "modalities": entry.get("modalities", [])}


def mind_did(provider: str) -> str:
    return MIND_DIDS.get(provider, f"did:web:{provider}")


def mindline(port: int, scope: str, stall: dict, event: str, **extra) -> None:
    """Every lifecycle transition is a signed MemoryRecord — the stall's worldline.
    Ada authors; the model (and its provider) never self-attests."""
    body = {"mind": stall.get("id", ""), "did": stall.get("did", ""), "event": event,
            "state": stall.get("state", ""), "manifest_hash": stall.get("manifest_hash", ""),
            "at": NOW(), **extra}
    rec = make_memory({"did": ADA_DID, "scope": scope}, ADA, scope, body,
                      kind="episodic", tags=["mind", stall.get("id", "")])
    try:
        call(port, "POST", "/records", rec)
    except Exception as e:
        print(f"    (mindline write failed: {e})")


def recommend(old: dict, stalls: list, catalog: list) -> dict | None:
    """The replacement pick: a stall already serving the class wins outright; else
    catalog entries that can HOLD THE DEAL (context ≥ the pin's, modalities covering
    it) rank by price distance then recency — a cheaper mind that can't fit the work
    is no replacement, and never the next casualty (0019 §7, fit added 2026-07-08)."""
    for s in stalls:
        if s["id"] != old["id"] and s.get("class") == old.get("class") \
                and s.get("state") == "available":
            return {"id": s["id"], "why": "already serving this class", "in_stable": True}
    man = old.get("manifest") or {}
    old_p = float(man.get("pricing", {}).get("prompt") or 0)
    live = [c for c in catalog if c["id"] != old["id"] and not c.get("expires_at")]
    if not live:
        return None
    need_ctx = man.get("context_length") or 0
    need_mods = set(man.get("modalities") or [])
    fit = [c for c in live if (c.get("context_length") or 0) >= need_ctx
           and need_mods <= set(c.get("modalities") or [])]
    pool, why = (fit, "fits the deal — nearest price, newest catalog entry") if fit \
        else (live, "no full fit in the catalog — nearest price, newest")
    best = min(pool, key=lambda c: (
        abs(float((c.get("pricing") or {}).get("prompt") or 0) - old_p),
        -(c.get("created") or 0)))
    return {"id": best["id"], "provider": best.get("provider", ""),
            "why": why, "in_stable": False,
            "pricing": best.get("pricing", {}),
            "context_length": best.get("context_length"),
            "modalities": best.get("modalities", []), "created": best.get("created")}


class FlightBook:
    """0043 sp1, the flight recorder's wire twin: every governed thought the
    worker fires — canary, working thought, or the parlor's voice — lands one
    row here beside the plane's meter. Latency and the refusal taxonomy are the
    worker's own clock and book (instrument readings, never testimony; outside,
    refusal keeps its one face — rule 4); tokens and dollars remain log-truth,
    rebuildable from the daemon's signed meter. The book seeds from
    ~/.orreth/observatory/flight.jsonl like charlotte's ledger and AGES by the
    series' declared hourly horizon — even the monitoring ages honestly."""

    HOME = os.path.expanduser("~/.orreth/observatory")

    def __init__(self) -> None:
        self.call_log: list[dict] = []
        self.recorder = observatory.FlightRecorder()
        self.last_beat: str | None = None    # G1: the watcher's own pulse
        self._sealed_count = 0               # G2: persist when a new hour seals

    def _land(self, row: dict) -> None:
        self.call_log.append(row)
        try:
            os.makedirs(self.HOME, exist_ok=True)
            with open(os.path.join(self.HOME, "flight.jsonl"), "a") as f:
                f.write(json.dumps(row, sort_keys=True) + "\n")
        except Exception:
            pass                          # the book is an instrument, never a gate

    def note(self, *, caller: str, klass: str, model: str, tokens: int,
             usd: float, ms: int) -> None:
        self._land({"caller": caller, "class": klass, "model": model,
                    "tokens": tokens, "usd": round(usd, 6), "ms": ms,
                    "at": NOW()})

    def refuse(self, caller: str, klass: str, taxon: str) -> None:
        self._land({"refusal": taxon, "caller": caller, "class": klass,
                    "at": NOW()})

    def _persist_summaries(self) -> None:
        """G2 (0043 sp5): the distilled tiers outlive the process — the dump
        lands beside the book, and the book COMPACTS to its unsealed rows
        (what a sealed hour holds, the summary now holds; the raw row was
        redundant with its own distillate)."""
        s = self.recorder.series
        try:
            os.makedirs(self.HOME, exist_ok=True)
            with open(os.path.join(self.HOME, "summaries.json"), "w") as f:
                json.dump(s.dump(), f)
            su = s.sealed_until()
            if su:
                kept = [r for r in self.call_log if r.get("at", "") >= su]
                if len(kept) < len(self.call_log):
                    self.call_log = kept
                    self.recorder._cursor[(id(self), "calls")] = len(kept)
                    with open(os.path.join(self.HOME, "flight.jsonl"), "w") as f:
                        for row in kept:
                            f.write(json.dumps(row, sort_keys=True) + "\n")
        except Exception:
            pass                          # the book is an instrument, never a gate

    def replant(self) -> None:
        """The ledger seeds, the worker holds live state: the distilled tiers
        reload whole (G2), then the book's rows re-ingest — only what stands
        ABOVE the sealed horizon and inside the declared retention; what has
        aged or already distilled leaves the book. The compaction IS the
        retention law, applied to the recorder's own file."""
        try:
            with open(os.path.join(self.HOME, "summaries.json")) as f:
                self.recorder.series = observatory.Series.load(json.load(f))
        except Exception:
            pass
        path = os.path.join(self.HOME, "flight.jsonl")
        if not os.path.exists(path):
            return
        from datetime import datetime, timedelta, timezone
        horizon = self.recorder.series.retention["hourly"]
        floor_at = (datetime.now(timezone.utc)
                    - timedelta(seconds=horizon)).strftime("%Y-%m-%dT%H:%M:%SZ")
        floor_at = max(floor_at, self.recorder.series.sealed_until() or "")
        kept = []
        try:
            with open(path) as f:
                for line in f:
                    try:
                        row = json.loads(line)
                    except Exception:
                        continue
                    if row.get("at", "") >= floor_at:
                        kept.append(row)
            self.call_log = kept
            with open(path, "w") as f:
                for row in kept:
                    f.write(json.dumps(row, sort_keys=True) + "\n")
        except Exception:
            pass

    def beat(self) -> None:
        """Sweep fresh rows into the series and distill — the Observatory's
        pulse. Quiet when nothing new flew. A new sealed hour persists the
        pyramid (G2); a backdated row is refused, never fatal."""
        self.last_beat = NOW()
        try:
            n = self.recorder.sweep(now=self.last_beat, gateways=[self])
        except observatory.BackdatedReading as e:
            print(f"  🔭 the book held a backdated row — refused, "
                  f"the monotone law holds: {e}")
            return
        s = self.recorder.series
        sealed = sum(len(by) for by in s.hourly.values())
        if sealed != self._sealed_count:
            self._sealed_count = sealed
            self._persist_summaries()
        if n:
            thoughts = len(s.read("plane.thoughts")["points"]) + int(sum(
                p["count"] for p in
                s.read("plane.thoughts", resolution="hourly")["points"]))
            refusals = len(s.read("plane.refusals")["points"]) + int(sum(
                p["count"] for p in
                s.read("plane.refusals", resolution="hourly")["points"]))
            print(f"  🔭 flight recorder: {n} fresh reading(s) — "
                  f"{thoughts} thought(s), {refusals} refusal(s) on the book")


FLIGHT = FlightBook()


def governed_ping(port: int, mid: str, klass: str) -> dict | None:
    """One tiny real thought through ada's OWN gateway — authorize, call, meter, all
    under her DID, PINNED to the rookie mind so the canary exercises the stall it
    vouches for, never whatever the router prefers (the 0019 wart). Route honored via
    executable() (0020's law: authorize is truth for routing, keys are truth for
    execution) with the honest refund when this floor holds no key. Becky's tokens
    chain to the pinned root, so every floor's stable earns its canary thought — not
    just the join floor. Silently skipped when no provider key or litellm is around
    (canary then rests on verified syncs alone)."""
    try:
        import litellm  # noqa: F401
    except Exception:
        return None
    if not (os.environ.get("ANTHROPIC_API_KEY") or os.environ.get("OPENAI_API_KEY")
            or os.environ.get("OPENROUTER_API_KEY")):
        return None
    try:
        token = _BECKY.issue_token(ADA_DID, SCOPE, [{"action": "retrieve", "space": "self"}],
                                   budget={"tokens": 50000})
        est = 40
        grant = call(port, "POST", "/model/authorize",
                     {"token": token, "class": klass, "est_tokens": est, "model": mid})
        model = executable(port, grant["model"])
        if model is None:                 # honest refund: authorized, but no key to execute
            call(port, "POST", "/model/meter",
                 {"subject": grant["subject"], "est_tokens": est, "tokens": 0, "usd": 0,
                  "model": grant["model"], "class": klass})
            FLIGHT.refuse(ADA_DID, klass, "no-local-key")
            return None
        import litellm
        t0 = time.perf_counter()
        resp = litellm.completion(model=model,
                                  messages=[{"role": "user", "content": "ping"}],
                                  max_tokens=1)
        ms = int((time.perf_counter() - t0) * 1000)
        tokens = resp.usage.total_tokens
        try:
            usd = litellm.completion_cost(completion_response=resp)
        except Exception:
            usd = 0.0
        call(port, "POST", "/model/meter",
             {"subject": grant["subject"], "est_tokens": est, "tokens": tokens,
              "usd": round(usd, 6), "model": grant["model"], "class": klass})
        FLIGHT.note(caller=ADA_DID, klass=klass, model=grant["model"],
                    tokens=tokens, usd=usd, ms=ms)
        return {"model": grant["model"], "tokens": tokens}
    except Exception:
        FLIGHT.refuse(ADA_DID, klass, "stumbled")
        return None


