def craft_render(text: str, **slots) -> str:
    for k, v in slots.items():
        text = text.replace("⟦" + k + "⟧", str(v))
    return text


_CANON_SEEDED = False
_CRAFT_CACHE: dict = {"at": 0.0, "rows": {}}


def canon_seed(port: int) -> None:
    """Idempotent, once per life: any firmware name without a record on the
    shelf lands its genesis seed — signed by becky, tagged canon."""
    global _CANON_SEEDED
    if _CANON_SEEDED:
        return
    _CANON_SEEDED = True
    try:
        have = set()
        for _, b, _, _ in wire_assets(port, "firmware"):
            f = (b or {}).get("firmware") or {}
            if f.get("name"):
                have.add(f["name"])
        import re as _re2
        for name, text in FIRMWARE.items():
            if name in have:
                continue
            body = {"firmware": {
                "name": name, "text": text,
                "slots": sorted(set(_re2.findall(r"⟦(\w+)⟧", text))),
                "extracted_from": "console_worker.py — the Canon extraction "
                                  "(0045 sp1); the literal is genesis only"}}
            rec = node.make_memory({"did": _BECKY.did, "scope": UNIVERSE_SCOPE},
                                   _BECKY.kp, UNIVERSE_SCOPE, body,
                                   kind="semantic",
                                   tags=["canon", "firmware", "prompt",
                                         f"fw-{name}"])
            call(port, "POST", "/records", rec)
            print(f"  📜 canon: firmware “{name}” extracted to the shelf "
                  f"({rec['id'][:18]}…)")
    except Exception as e:
        _CANON_SEEDED = False                 # the next beat may retry
        print(f"    (canon seed stumbled: {e})")


def craft(port: int, name: str) -> str:
    """The worker reads its own firmware from the Canon — the record's head
    is the truth; the literal serves only when the shelf cannot answer."""
    if time.time() - _CRAFT_CACHE["at"] > 60:
        rows: dict = {}
        try:
            for _, b, _, _ in wire_assets(port, "firmware"):
                f = (b or {}).get("firmware") or {}
                if f.get("name"):
                    rows[f["name"]] = f["text"]   # oldest-first: head wins
            _CRAFT_CACHE.update(at=time.time(), rows=rows)
        except Exception:
            _CRAFT_CACHE["at"] = time.time()
    return _CRAFT_CACHE["rows"].get(name) or FIRMWARE[name]


def governed_thought(port: int, mid: str, klass: str, prompt: str, *,
                     max_tokens: int = 400, as_did: str | None = None) -> dict | None:
    """A REAL governed thought (wire-honesty sp3, 2026-07-25): governed_ping's
    exact law — authorize → execute PINNED to the named mind → meter under the
    plane — with a working prompt instead of a ping. Returns
    {text, tokens, usd, model} or None when the ground is missing (no litellm,
    no key, no stall) so callers fall back HONESTLY, never silently.
    as_did (0043 sp2): whose meter the thought rides — vera's commissions are
    metered under HER did (her own cost is her first exhibit); ada's canary
    lineage remains the default."""
    try:
        import litellm  # noqa: F401
    except Exception:
        return None
    if not (os.environ.get("ANTHROPIC_API_KEY") or os.environ.get("OPENAI_API_KEY")
            or os.environ.get("OPENROUTER_API_KEY")):
        return None
    did = as_did or ADA_DID
    try:
        token = _BECKY.issue_token(did, SCOPE,
                                   [{"action": "retrieve", "space": "self"}],
                                   budget={"tokens": 50000})
        est = max_tokens + len(prompt) // 3
        grant = call(port, "POST", "/model/authorize",
                     {"token": token, "class": klass, "est_tokens": est,
                      "model": mid})
        model = executable(port, grant["model"])
        if model is None:                 # honest refund — authorized, no key here
            call(port, "POST", "/model/meter",
                 {"subject": grant["subject"], "est_tokens": est, "tokens": 0,
                  "usd": 0, "model": grant["model"], "class": klass})
            FLIGHT.refuse(did, klass, "no-local-key")
            return None
        import litellm
        t0 = time.perf_counter()
        resp = litellm.completion(model=model,
                                  messages=[{"role": "user", "content": prompt}],
                                  max_tokens=max_tokens)
        ms = int((time.perf_counter() - t0) * 1000)
        text = (resp.choices[0].message.content or "").strip()
        tokens = resp.usage.total_tokens
        try:
            usd = litellm.completion_cost(completion_response=resp)
        except Exception:
            usd = 0.0
        call(port, "POST", "/model/meter",
             {"subject": grant["subject"], "est_tokens": est, "tokens": tokens,
              "usd": round(usd, 6), "model": grant["model"], "class": klass})
        FLIGHT.note(caller=did, klass=klass, model=grant["model"],
                    tokens=tokens, usd=usd, ms=ms)
        return {"text": text, "tokens": tokens, "usd": usd,
                "model": grant["model"]}
    except Exception as e:
        print(f"    (governed thought stumbled: {e})")
        FLIGHT.refuse(did, klass, "stumbled")
        return None


class Wrangler:
    """Ada's round: probe staged saddles, attest approvals, canary rookie minds,
    sync the market for drift and expiries, stage recommendations, re-saddle after
    restarts. The plane refuses illegal moves; ada only ever proposes legal ones."""

    def __init__(self) -> None:
        self.pinged: set[tuple] = set()       # one governed canary thought per (floor, mind)

    def _local(self, port: int, scope: str) -> list[dict]:
        return [s for s in call(port, "GET", "/stable")["stalls"]
                if s.get("floor") == scope]

    # ---- the queue: saddle · reapprove · retire · swap ---------------------------------
    def on_mind_request(self, port: int, scope: str, r: dict) -> bool:
        """Returns True when the request reached a resting state (done/denied)."""
        action, status, mid = r.get("action", "saddle"), r.get("status"), r.get("mind", "")
        if status == "pending" and action in ("reapprove", "retire", "swap"):
            # nothing to probe — consequence waits for the human (0012)
            call(port, "POST", "/requests/resolve", {"id": r["id"], "status": "staged"})
            return False
        if status == "pending" and action == "saddle":
            entry = next((c for c in openrouter_catalog() if c["id"] == mid), None)
            manifest = deal(entry) if entry else (r.get("manifest") or {})
            provider = r.get("provider") or mid.split("/")[0]
            stall = call(port, "POST", "/stable/saddle", {
                "id": mid, "provider": provider,
                "route": r.get("route", "litellm-direct"),
                "did": mind_did(provider), "class": r.get("class", "medium"),
                "manifest": manifest,
                "expires_at": (entry or {}).get("expires_at") or r.get("expires_at")})
            mindline(port, scope, stall, "saddled",
                     in_catalog=bool(entry),
                     pricing=manifest.get("pricing", {}))
            call(port, "POST", "/requests/resolve",
                 {"id": r["id"], "status": "staged",
                  "result": {"manifest_hash": stall["manifest_hash"],
                             "in_catalog": bool(entry),
                             "expires_at": stall.get("expires_at"),
                             "pricing": manifest.get("pricing", {})}})
            print(f"  ↳ staged saddle {mid}: catalog={bool(entry)}, "
                  f"pinned {stall['manifest_hash'][:18]}…")
            return False
        if status == "approved":
            if action == "saddle":
                stall = next((s for s in self._local(port, scope) if s["id"] == mid), {})
                out = call(port, "POST", "/stable/state",
                           {"id": mid, "op": "attest",
                            "manifest": stall.get("manifest", {}),
                            "expires_at": stall.get("expires_at")})
                mindline(port, scope, out, "attested")
                led = stable_ledger_load(scope)
                led[mid] = {k: out.get(k) for k in ("id", "provider", "route", "class",
                                                    "did", "manifest", "manifest_hash",
                                                    "expires_at")}
                stable_ledger_save(scope, led)
                print(f"  ↳ attested {mid} — canary begins (governed beats earn available)")
            elif action == "reapprove":
                out = call(port, "POST", "/stable/state", {"id": mid, "op": "reapprove"})
                mindline(port, scope, out, "re-approved", pinned=out.get("manifest_hash"))
                led = stable_ledger_load(scope)
                if mid in led:
                    led[mid]["manifest"] = out.get("manifest")
                    led[mid]["manifest_hash"] = out.get("manifest_hash")
                    stable_ledger_save(scope, led)
                print(f"  ↳ re-approved {mid} — the new deal is the pin now")
            elif action == "swap":
                rep = r.get("replacement") or {}
                rep_id = rep.get("id", "")
                if rep_id and not rep.get("in_stable"):
                    provider = rep.get("provider") or rep_id.split("/")[0]
                    new = call(port, "POST", "/stable/saddle", {
                        "id": rep_id, "provider": provider,
                        "route": r.get("route", "litellm-direct"),
                        "did": mind_did(provider),
                        "class": r.get("class") or "medium",
                        "manifest": deal(rep), "expires_at": rep.get("expires_at")})
                    mindline(port, scope, new, "saddled", reason=f"succeeds {mid}")
                    out = call(port, "POST", "/stable/state",
                               {"id": rep_id, "op": "attest", "manifest": deal(rep)})
                    mindline(port, scope, out, "attested")
                    led = stable_ledger_load(scope)
                    led[rep_id] = {k: out.get(k) for k in ("id", "provider", "route",
                                                           "class", "did", "manifest",
                                                           "manifest_hash", "expires_at")}
                    stable_ledger_save(scope, led)
                old = call(port, "POST", "/stable/state",
                           {"id": mid, "op": "retire",
                            "reason": f"superseded by {rep_id or 'its class'}"})
                mindline(port, scope, old, "retired", superseded_by=rep_id)
                led = stable_ledger_load(scope)
                led.pop(mid, None)
                stable_ledger_save(scope, led)
                print(f"  ↳ swapped {mid} → {rep_id or '(existing stall)'} — no outage, by appointment")
            elif action == "retire":
                out = call(port, "POST", "/stable/state",
                           {"id": mid, "op": "retire", "reason": r.get("reason", "")})
                mindline(port, scope, out, "retired", reason=r.get("reason", ""))
                led = stable_ledger_load(scope)
                led.pop(mid, None)
                stable_ledger_save(scope, led)
                print(f"  ↳ retired {mid} — sunset; never served again")
            call(port, "POST", "/requests/resolve", {"id": r["id"], "status": "done"})
            return True
        if status == "denied":
            try:
                out = call(port, "POST", "/stable/state",
                           {"id": mid, "op": "retire", "reason": "denied at the gate"})
                mindline(port, scope, out, "denied")
            except Exception:
                pass
            led = stable_ledger_load(scope)
            led.pop(mid, None)
            stable_ledger_save(scope, led)
            call(port, "POST", "/requests/resolve", {"id": r["id"], "status": "done"})
            print(f"  ↳ denied {mid} — never served")
            return True
        return False

    # ---- the round: canary beats, market sync, EOL scan, re-saddles ---------------------
    def sync(self, port: int, scope: str) -> None:
        try:
            stalls = self._local(port, scope)
        except Exception:
            return
        led = stable_ledger_load(scope)
        if not stalls and not led:
            return                            # a floor with no stable stays quiet
        self.restable(port, scope, {s["id"] for s in stalls})
        cat = openrouter_catalog()
        by_id = {c["id"]: c for c in cat}
        from datetime import date, timedelta
        edge = (date.fromisoformat(NOW()[:10]) + timedelta(days=EOL_HORIZON_DAYS)).isoformat()
        for s in stalls:
            mid, state = s["id"], s["state"]
            if state == "canaried":
                beat = call(port, "POST", "/stable/hello", {"id": mid})
                if beat.get("transition", {}).get("to") == "available":
                    mindline(port, scope, beat, "available",
                             earned_after=beat.get("canary_beats"))
                    print(f"  ↳ {mid} earned its place — available")
                if (port, mid) not in self.pinged:
                    ping = governed_ping(port, mid, s.get("class", "medium"))
                    if ping:
                        self.pinged.add((port, mid))
                        mindline(port, scope, s, "canary-thought", **ping)
                state = beat.get("state", state)
            if state in ("canaried", "available") and mid in by_id:
                c = by_id[mid]
                out = call(port, "POST", "/stable/state",
                           {"id": mid, "op": "sync", "manifest": deal(c),
                            "expires_at": c.get("expires_at")})
                if out.get("transition", {}).get("to") == "deprecated":
                    mindline(port, scope, out, "manifest-drift",
                             pinned=out.get("manifest_hash"),
                             seen=out.get("proposed_hash"))
                    if not open_ask(port, {"kind": "mind", "action": "reapprove",
                                           "mind": mid}):
                        call(port, "POST", "/requests",
                             {"kind": "mind", "action": "reapprove", "mind": mid,
                              "proposed_hash": out.get("proposed_hash"),
                              "text": f"{mid}'s deal moved under its pin — re-approve the new terms?"})
                    print(f"  ↳ {mid} drifted — the deal changed; held for your decision")
                    continue
                s = out                        # freshest expires_at for the EOL check
                state = s.get("state", state)
            exp = s.get("expires_at")
            if exp and state in ("canaried", "available") and str(exp)[:10] <= edge:
                out = call(port, "POST", "/stable/state",
                           {"id": mid, "op": "eol", "expires_at": exp})
                rec = recommend(s, stalls, cat)
                mindline(port, scope, out, "expiring", expires_at=exp,
                         recommends=(rec or {}).get("id"))
                text = f"{mid} expires {str(exp)[:10]}"
                text += f" — ada recommends {rec['id']} ({rec['why']})" if rec \
                    else " — no replacement found yet"
                call(port, "POST", "/requests",
                     {"kind": "mind", "action": "swap", "mind": mid,
                      "class": s.get("class"), "replacement": rec, "text": text})
                print(f"  ↳ {mid} is expiring — recommendation staged")

    def restable(self, port: int, scope: str, present: set) -> None:
        """The daemon may die; the stable doesn't. The ledger re-saddles live state."""
        for mid, stall in stable_ledger_load(scope).items():
            if mid in present:
                continue
            try:
                call(port, "POST", "/stable/saddle", stall)
                call(port, "POST", "/stable/state",
                     {"id": mid, "op": "attest", "manifest": stall.get("manifest", {}),
                      "expires_at": stall.get("expires_at")})
                mindline(port, scope, stall, "re-saddled",
                         note="daemon restarted; approval is durable in the ledger")
                print(f"  ↳ re-saddled {mid} after a daemon restart")
            except Exception as e:
                print(f"    (re-saddle {mid} failed: {e})")


WRANGLER = Wrangler()


# ---------------------------------------------------------------- the librarian (0014)

def farm_search_source(port: int) -> dict | None:
    """The Farm's serving search source, if any — gather consumes governed resources."""
    try:
        for s in call(port, "GET", "/farm")["services"]:
            if s["state"] == "serving" and any(
                    "search" in t.get("name", "") for t in s.get("manifest", [])):
                return s
    except Exception:
        pass
    return None


def tavily(q: str, n: int = 3) -> list:
    # ORRETH_SEARCH_OFF: the dev thrift dial (JB's word, 2026-08-09, after a
    # 1,000-credit August — three stale 0032 demo subscriptions swept real
    # searches every ~17 min for weeks). Set it in .env and restart: every
    # caller gets the honestly-labeled placeholder; no live spend anywhere.
    if os.environ.get("ORRETH_SEARCH_OFF"):
        return [{"title": f"(search dark — ORRETH_SEARCH_OFF) placeholder finding on {q}",
                 "content": "the live web is off by the human's dial; unset the env to spend again",
                 "url": "local://demo"}]
    # 0054 sp2 (JB's lock L-A) — the DECLARED daily ceiling, enforced at the
    # one place every caller passes (G5's shape, vera's assay budget): a
    # durable line per live search, counted since UTC midnight; past the
    # ceiling the placeholder speaks honestly and nothing is spent.
    if _search_spent_today() >= SEARCH_DAILY:
        return [{"title": f"(search ceiling — {SEARCH_DAILY}/day reached) placeholder finding on {q}",
                 "content": "the declared daily search spend is used up; it resets at UTC "
                            "midnight — a standing spend is ceilinged, never an accident (0054 L-A)",
                 "url": "local://ceiling"}]
    if not os.environ.get("TAVILY_API_KEY"):
        return [{"title": f"(no TAVILY_API_KEY) placeholder finding on {q}",
                 "content": "set the key to gather real sourced knowledge", "url": "local://demo"}]
    req = urllib.request.Request("https://api.tavily.com/search", method="POST",
        data=json.dumps({"api_key": os.environ["TAVILY_API_KEY"], "query": q,
                         "max_results": n}).encode(), headers={"Content-Type": "application/json"})
    results = json.loads(urllib.request.urlopen(req).read())["results"]
    _search_ledger_mark(q)
    return results


SEARCH_DAILY = int(os.environ.get("ORRETH_SEARCH_DAILY", "6"))
_SEARCH_LEDGER = HOME / "farm" / "searches.jsonl"


def _search_spent_today() -> int:
    """Live searches since UTC midnight, from the durable ledger."""
    if not _SEARCH_LEDGER.exists():
        return 0
    today = NOW()[:10]
    n = 0
    for ln in _SEARCH_LEDGER.read_text().splitlines():
        try:
            if json.loads(ln).get("at", "")[:10] == today:
                n += 1
        except Exception:
            continue
    return n


def _search_ledger_mark(q: str) -> None:
    _SEARCH_LEDGER.parent.mkdir(parents=True, exist_ok=True)
    with _SEARCH_LEDGER.open("a") as f:
        f.write(json.dumps({"at": NOW(), "q": q[:80]}) + "\n")


def floor_knowledge(port: int, scope: str):
    """The librarian's harvest of her OWN floor (0014 §4 · 0026): every
    knowledge-tagged record with its body in hand — her seat, her token; humans
    never read. Returns (entries, bodies, tags_of), keyed by ref."""
    from datetime import datetime, timedelta, timezone
    _, seat_did = lib_seat(scope)             # her seat at THIS floor (0023 §1)
    token = _ROOT.issue_token(seat_did, "u:demo", [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc) - timedelta(days=365)).strftime("%Y-%m-%dT%H:%M:%SZ")
    r = call(port, "POST", "/retrieve", {
        "query": {"requester": seat_did, "subject": {"cohort": {"scope": scope}},
                  "space": "self", "time": {"from": frm}, "intent": "recall",
                  "budget": {"cost": 8}, "auth": "biscuit-sim"},
        "token": token, "requester_scope": scope})
    entries, bodies, tags_of = [], {}, {}
    for h in r.get("hits", []):
        tags = h.get("tags") or []
        if "knowledge" not in tags:
            continue
        try:
            body = call(port, "GET", f"/records/{urllib.parse.quote(h['ref'], safe='')}/body")
        except Exception:
            continue
        if not isinstance(body, dict):
            continue
        entries.append({"ref": h["ref"],
                        "source_did": (body.get("source") or {}).get("did", ""),
                        "derived_from": h.get("derived_from") or []})
        bodies[h["ref"]] = body
        tags_of[h["ref"]] = tags
    return entries, bodies, tags_of


def recall_walk(port: int, scope: str, source_did: str, reason: str) -> str:
    """The librarian's 0014 §4 duty, on the wire: fetch the floor's knowledge under
    her OWN authority (humans never read; organs do), walk source + derived_from
    lineage, and version every tainted entry to 'recalled' — annotate-never-rewrite,
    the poison visibly dead in the Window."""
    from orreth_sim.librarian import tainted_refs

    if not source_did:
        return "nothing to recall — the discredited service carried no source DID"
    seat_kp, seat_did = lib_seat(scope)       # her seat at THIS floor (0023 §1)
    entries, bodies, tags_of = floor_knowledge(port, scope)
    # refs already annotated by a prior recall version stay annotated — idempotent
    already = {d for e in entries if bodies[e["ref"]].get("state") == "recalled"
               for d in e["derived_from"]}
    recalled, recall_ids = 0, []
    for ref in tainted_refs(entries, source_did):
        if ref in already or bodies[ref].get("state") == "recalled":
            continue
        new_body = {**bodies[ref], "state": "recalled", "recall_reason": reason,
                    "recalled_source": source_did, "at": NOW()}
        tags = sorted({*tags_of.get(ref, []), "knowledge", "recalled"} - {"gathered"})
        rec = make_memory({"did": seat_did, "scope": scope}, seat_kp, scope, new_body,
                          kind="semantic", tags=list(tags))
        rec["derived_from"] = [ref]
        call(port, "POST", "/records", rec)
        recall_ids.append(rec["id"])
        recalled += 1
    if recall_ids:
        # 0024 §2: the resident that did the duty grades it — a recall is a HIGH
        # change (the human already held this gate at the discredit approval)
        mk = markers.make_marker({"did": seat_did, "scope": scope}, seat_kp, scope,
                                 recall_ids, reason=f"recall: {reason}",
                                 change_severity="high")
        try:
            call(port, "POST", "/records", mk)
        except Exception as e:
            print(f"    (recall marker write failed: {e})")
    return (f"recalled {recalled} entr(ies) traced to {source_did} — "
            "annotated, never rewritten; the lineage is intact")


def wire_subscriptions(port: int, scope: str) -> list[dict]:
    """The serials desk's ledger from the wire (0032 §1): current head per topic,
    read under the librarian's seat — cancelled shown with its posture."""
    from datetime import datetime, timedelta, timezone
    _, seat_did = lib_seat(scope)
    token = _ROOT.issue_token(seat_did, "u:demo",
                              [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc) - timedelta(days=365)).strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        r = call(port, "POST", "/retrieve", {
            "query": {"requester": seat_did, "subject": {"cohort": {"scope": scope}},
                      "space": "self", "time": {"from": frm}, "intent": "recall",
                      "budget": {"cost": 8}, "auth": "biscuit-sim"},
            "token": token, "requester_scope": scope})
    except Exception:
        return []
    rows, superseded = [], set()
    for h in r.get("hits", []):
        if "subscription" not in (h.get("tags") or []):
            continue
        try:
            body = call(port, "GET",
                        f"/records/{urllib.parse.quote(h['ref'], safe='')}/body")
        except Exception:
            continue
        if isinstance(body, dict) and "subscription" in body:
            rows.append((h["ref"], body["subscription"],
                         h.get("derived_from") or [], h.get("occurred_at", "")))
            superseded.update(h.get("derived_from") or [])
    rows.sort(key=lambda x: x[3])
    return [{"id": ref, **sub} for ref, sub, _, _ in rows if ref not in superseded]


def wire_deliveries(port: int, scope: str, want_slug: str | None = None) -> list[dict]:
    """The desk's sweep history from the wire (0032 §2): every delivery note,
    oldest first, read under the librarian's seat — the worldline sweep by sweep."""
    from datetime import datetime, timedelta, timezone
    _, seat_did = lib_seat(scope)
    token = _ROOT.issue_token(seat_did, "u:demo",
                              [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc) - timedelta(days=365)).strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        r = call(port, "POST", "/retrieve", {
            "query": {"requester": seat_did, "subject": {"cohort": {"scope": scope}},
                      "space": "self", "time": {"from": frm}, "intent": "recall",
                      "budget": {"cost": 8}, "auth": "biscuit-sim"},
            "token": token, "requester_scope": scope})
    except Exception:
        return []
    rows = []
    for h in r.get("hits", []):
        tags = h.get("tags") or []
        if "delivery" not in tags or (want_slug and want_slug not in tags):
            continue
        try:
            body = call(port, "GET",
                        f"/records/{urllib.parse.quote(h['ref'], safe='')}/body")
        except Exception:
            continue
        if isinstance(body, dict) and "delivery" in body:
            rows.append((h.get("occurred_at", ""), h["ref"], body["delivery"]))
    rows.sort(key=lambda x: x[0])
    return [{"id": ref, **d} for _, ref, d in rows]


def wire_unsubscribe(port: int, scope: str, topic: str) -> str:
    """Retired on the record (0032 §1): a cancelled sibling derives from the head.
    Stopping a spend needs no gate — starting one did."""
    want = serials.slug(topic)
    head = next((s for s in wire_subscriptions(port, scope)
                 if serials.slug(s.get("topic", "")) == want), None)
    if head is None:
        return f"nothing on the desk under “{topic}” — say “show the desk” for what stands"
    seat_kp, seat_did = lib_seat(scope)
    body = {"subscription": {**{k: v for k, v in head.items() if k != "id"},
                             "posture": "cancelled",
                             "reason": "the human closed it"}}
    rec = make_memory({"did": seat_did, "scope": scope}, seat_kp, scope, body,
                      kind="semantic",
                      tags=["subscription", serials.slug(head.get("topic", ""))])
    rec["derived_from"] = [head["id"]]
    try:
        call(port, "POST", "/records", rec)
    except Exception as e:
        return f"the cancellation stumbled: {e}"
    print(f"  ↳ subscription to “{head.get('topic')}” cancelled — on the worldline")
    return (f"the subscription to “{head.get('topic')}” is cancelled — a new "
            "version on its worldline, never an absence")


def on_subscription(port: int, scope: str, r: dict, *, approved: bool = False,
                    declined: bool = False) -> None:
    """0032 §1: a standing spend is a consequence — the ask STAGES with its terms
    readable, and only the human's word mints the subscription record. The
    cadence is a dial on the record (§8): the ask may carry the human's own."""
    topic = str(r.get("topic") or r.get("text") or "").strip()
    cadence = int(r.get("cadence") or 100)
    seat_kp, seat_did = lib_seat(scope)
    if declined:
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"declined": True,
                         "reply": f"the subscription to “{topic}” was declined — "
                                  "nothing opens, and the record keeps that you chose"}})
        print(f"  ↳ subscription to “{topic}” declined at the gate")
        return
    if approved:                              # the human's word opens the desk
        rec = serials.make_subscription({"did": seat_did, "scope": scope},
                                        seat_kp, scope, topic=topic,
                                        cadence_beats=cadence,
                                        approved_ref=str(r.get("id") or ""))
        call(port, "POST", "/records", rec)
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"subscription": rec["id"], "topic": topic,
                         "terms": f"every {cadence} beats · 4 call(s) per delivery",
                         "lane": "opened on the human's word"}})
        print(f"  ↳ subscription OPENED: “{topic}” every {cadence} beats — "
              f"{rec['id'][:18]}…")
        return
    call(port, "POST", "/requests/resolve",
         {"id": r["id"], "status": "staged",
          "result": {"held": "a standing spend waits for you (0032 §1) — open "
                             "or decline at the gate",
                     "topic": topic,
                     "terms": f"every {cadence} beats · 4 call(s) per delivery · "
                              "serving sources only · admits quarantined"}})
    print(f"  ↳ subscription to “{topic}” staged — the gate waits")


# the desk's live memory (0032 §2): beats waited and last issue per (port, slug).
# The notes on the record are the durable history; a restarted worker re-seeds
# from the wire — a subscription with notes waits a fresh cadence, one with none
# gets its first issue on the next sweep (the desk starts you on the current issue).
_DESK: dict[tuple[int, str], dict] = {}


def serials_beat(port: int, scope: str) -> None:
    """The desk's standing duty (0032 §2), riding the worker's beat like the
    improver's — zero new residents, the librarian's seat does the sweeping. Due
    subscriptions re-gather through charlotte's SERVING roster only (a recalled
    source is refused at the door, 0026 §5), dedup against the shelf, admit only
    the new — quarantined at 0.0000, the subscription named in the lineage — and
    write one signed delivery note. Quiet = log; news wears the medium marker.
    The desk delivers; it never decides."""
    if scope in _LEGACY_FLOORS:
        return                                # a legacy universe never spends (0035 §6)
    try:
        subs = wire_subscriptions(port, scope)
    except Exception:
        return
    for s in subs:
        topic = str(s.get("topic", ""))
        key = (port, serials.slug(topic))
        if s.get("posture") != "deliver":
            _DESK.pop(key, None)              # paused/cancelled: never due (0009)
            continue
        st = _DESK.get(key)
        if st is None:
            notes = wire_deliveries(port, scope, key[1])
            st = _DESK[key] = {"waited": 0, "delivered": bool(notes),
                               "issue": int(notes[-1].get("issue", len(notes))
                                            if notes else 0)}
        else:
            st["waited"] += 1
        if not serials.is_due(s, st["waited"], st["delivered"]):
            continue
        src = farm_search_source(port)
        if src is None:
            continue                          # no serving voice — the sub keeps waiting
        seat_kp, seat_did = lib_seat(scope)
        entries, bodies, _t = floor_knowledge(port, scope)
        if src.get("did") in purge.discredited_dids(bodies):
            # the door remembers the infection (0026 §5) — refused, on the record
            note = make_memory({"did": seat_did, "scope": scope}, seat_kp, scope,
                               {"immune": {"refused_source": src["did"],
                                           "service": src["name"],
                                           "intent": f"delivery: {topic}"}},
                               kind="semantic", tags=["librarian", "immune-refusal"])
            try:
                call(port, "POST", "/records", note)
            except Exception as e:
                print(f"    (immune-refusal write failed: {e})")
            st["waited"] = 0                  # the refusal was this sweep's outcome
            print(f"  ↳ the desk refused at the door — “{topic}” from a recalled source")
            continue
        t0 = time.time()
        results = tavily(topic)               # one call — under the 4-call ceiling
        try:
            call(port, "POST", "/farm/meter", {"name": src["name"], "caller": seat_did,
                                               "ms": int((time.time() - t0) * 1000)})
        except Exception as e:
            print(f"    (delivery meter failed: {e})")
        findings = [{"claim": f"{x['title']} — {x['content'][:120]}",
                     "ref": x.get("url", ""), "source_did": src["did"]}
                    for x in results]
        superseded = {d for e in entries for d in e["derived_from"]}
        held = [{"id": e["ref"],
                 "claim": str(bodies[e["ref"]].get("knowledge", "")),
                 "ref": str((bodies[e["ref"]].get("source") or {}).get("ref", "")),
                 "source_did": str((bodies[e["ref"]].get("source") or {}).get("did", ""))}
                for e in entries
                if e["ref"] not in superseded
                and bodies[e["ref"]].get("intent") == topic
                and bodies[e["ref"]].get("state") != "recalled"]
        parts = serials.dedup(findings, held, source_did=src["did"])

        def admit(f: dict) -> str | None:
            body = {"knowledge": f["claim"],
                    "source": {"did": f["source_did"], "ref": f["ref"]},
                    "state": "untrusted", "intent": topic,
                    "subscription": s["id"]}
            rec = make_memory({"did": seat_did, "scope": scope}, seat_kp, scope,
                              body, kind="semantic",
                              tags=["knowledge", "delivered", key[1]],
                              provenance_class="ingested-archive")
            rec["derived_from"] = [s["id"]]
            try:
                call(port, "POST", "/records", rec)
            except urllib.error.HTTPError:
                # content-addressed: this exact utterance already stands (a dead
                # lineage's original, say) — a repeat, never a re-write
                return None
            return rec["id"]

        admitted, fresh = [], []
        for f in parts["new"]:
            rid = admit(f)
            (fresh.append(f), admitted.append(rid)) if rid \
                else parts["repeat"].append(f)
        parts["new"] = fresh
        # §3: change at the source is doubt at the shelf — the new claim admits
        # (its own record, its own state), the OLD head drops to investigating
        # via the revalidation walk's shape, superseded-at-source, pair named.
        # Nothing auto-supersedes; the doubt is idempotent.
        changed, dropped = [], 0
        for f in parts["changed"]:
            rid = admit(f)
            if rid is None:
                parts["repeat"].append(f)
                continue
            admitted.append(rid)
            changed.append(f)
            for old in f.get("supersedes") or []:
                ob = bodies.get(old) or {}
                if ob.get("state") in ("recalled", "investigating"):
                    continue
                nb = {**ob, "state": "investigating",
                      "revalidation": {"trigger": "superseded-at-source",
                                       "reason": f"“{topic}” changed at its source "
                                                 f"({f['ref']}) — superseded by {rid}",
                                       "at": NOW()}}
                sib = make_memory({"did": seat_did, "scope": scope}, seat_kp,
                                  scope, nb, kind="semantic",
                                  tags=sorted({*_t.get(old, []), "knowledge"}))
                sib["derived_from"] = [old]
                try:
                    call(port, "POST", "/records", sib)
                    dropped += 1
                except Exception as e:
                    print(f"    (supersede drop failed: {e})")
        parts["changed"] = changed
        st["issue"] += 1
        note = serials.make_delivery_note({"did": seat_did, "scope": scope},
                                          seat_kp, scope, s, issue=st["issue"],
                                          parts=parts, calls=1)
        try:
            call(port, "POST", "/records", note)
        except Exception as e:
            print(f"    (delivery note write failed: {e})")
        delivery = {"changed": parts["changed"], "vanished": parts["vanished"]}
        if serials.news(delivery):
            mk = markers.make_marker(
                {"did": seat_did, "scope": scope}, seat_kp, scope, [note["id"]],
                reason=f"the desk delivered news on “{topic}”: "
                       f"{len(parts['changed'])} changed at source · "
                       f"{len(parts['vanished'])} vanished",
                change_severity="medium")
            try:
                call(port, "POST", "/records", mk)
            except Exception as e:
                print(f"    (delivery marker write failed: {e})")
        st["waited"], st["delivered"] = 0, True
        print(f"  ↳ the desk delivers issue {st['issue']} on “{topic}”: "
              f"{len(parts['new'])} new · {len(parts['repeat'])} repeated"
              + (f" · {len(parts['changed'])} changed ({dropped} head(s) to "
                 f"investigating)" if parts["changed"] else "")
              + (f" · {len(parts['vanished'])} vanished" if parts["vanished"] else "")
              + f" — {'NEWS on the medium lane' if serials.news(delivery) else 'a quiet issue, logged'}")


def coordinate_citations(port: int, scope: str, goal: str) -> int:
    """0033 §4 on the wire: how many records at this floor cite the objective's
    coordinate — a tag lookup over an index the floors already serve (0022 GIN),
    never a lineage recursion. Read under the librarian's seat, as ever."""
    from datetime import datetime, timedelta, timezone
    _, seat_did = lib_seat(scope)
    token = _ROOT.issue_token(seat_did, "u:demo",
                              [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc) - timedelta(days=365)).strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        r = call(port, "POST", "/retrieve", {
            "query": {"requester": seat_did, "subject": {"cohort": {"scope": scope}},
                      "space": "self", "time": {"from": frm}, "intent": "recall",
                      "budget": {"cost": 8}, "auth": "biscuit-sim"},
            "token": token, "requester_scope": scope})
    except Exception:
        return 0
    tag = f"of:{goal}"
    return sum(1 for h in r.get("hits", []) if tag in (h.get("tags") or []))


def revalidate_walk(port: int, scope: str, source_did: str, trigger: str,
                    reason: str) -> str:
    """A freshness trigger fired (0031 §5): the librarian DOUBTS the source — she
    does not damn it. Current heads traced to it drop to 'investigating' with the
    trigger named; the medium lane (0024) makes it visible, never blocking.
    Idempotent: doubt never stacks, and the dead stay dead."""
    from orreth_sim.librarian import tainted_refs
    if not source_did:
        return "nothing to revalidate — no source DID"
    seat_kp, seat_did = lib_seat(scope)
    entries, bodies, tags_of = floor_knowledge(port, scope)
    superseded = {d for e in entries for d in e["derived_from"]}
    new_ids = []
    for ref in tainted_refs(entries, source_did):
        if ref in superseded:
            continue                          # heads only — history is not re-reviewed
        b = bodies.get(ref) or {}
        if b.get("state") in ("recalled", "investigating"):
            continue
        new_body = {**b, "state": "investigating",
                    "revalidation": {"trigger": trigger, "reason": reason,
                                     "at": NOW()}}
        rec = make_memory({"did": seat_did, "scope": scope}, seat_kp, scope,
                          new_body, kind="semantic",
                          tags=sorted({*tags_of.get(ref, []), "knowledge"}))
        rec["derived_from"] = [ref]
        call(port, "POST", "/records", rec)
        new_ids.append(rec["id"])
    if new_ids:
        mk = markers.make_marker({"did": seat_did, "scope": scope}, seat_kp, scope,
                                 new_ids,
                                 reason=f"revalidation ({trigger}): {reason}",
                                 change_severity="medium")
        try:
            call(port, "POST", "/records", mk)
        except Exception as e:
            print(f"    (revalidation marker write failed: {e})")
    return (f"{len(new_ids)} entr(ies) dropped to investigating — {trigger}; "
            "promotion is earned again, never assumed")


def challenge_walk(port: int, scope: str, topic: str) -> str:
    """The human's doubt is a trigger too (0031 §5): current claims matching the
    topic drop to 'investigating', quoting the challenge — verbatim discipline."""
    t = (topic or "").strip().lower()
    if not t:
        return "a challenge names a topic — say: challenge <topic>"
    seat_kp, seat_did = lib_seat(scope)
    entries, bodies, tags_of = floor_knowledge(port, scope)
    superseded = {d for e in entries for d in e["derived_from"]}
    new_ids = []
    for e in entries:
        ref = e["ref"]
        if ref in superseded:
            continue
        b = bodies.get(ref) or {}
        claim = str(b.get("claim") or b.get("knowledge") or "")
        if t not in claim.lower() or b.get("state") in ("recalled", "investigating"):
            continue
        new_body = {**b, "state": "investigating",
                    "revalidation": {"trigger": "human-challenge",
                                     "reason": f"the human challenged: “{topic}”",
                                     "at": NOW()}}
        rec = make_memory({"did": seat_did, "scope": scope}, seat_kp, scope,
                          new_body, kind="semantic",
                          tags=sorted({*tags_of.get(ref, []), "knowledge"}))
        rec["derived_from"] = [ref]
        call(port, "POST", "/records", rec)
        new_ids.append(rec["id"])
    if new_ids:
        mk = markers.make_marker({"did": seat_did, "scope": scope}, seat_kp, scope,
                                 new_ids,
                                 reason=f"human challenge: “{topic}”",
                                 change_severity="medium")
        try:
            call(port, "POST", "/records", mk)
        except Exception as e:
            print(f"    (challenge marker write failed: {e})")
        print(f"  ↳ challenge on “{topic}”: {len(new_ids)} claim(s) to investigating")
    return (f"{len(new_ids)} claim(s) matching “{topic}” dropped to investigating — "
            "doubted, not damned; corroboration earns them back"
            if new_ids else
            f"no current claims match “{topic}” — nothing to doubt")


def domain_packages(port: int, scope: str, topic: str = "") -> list[dict]:
    """The domain package as a VIEW over records that already exist (0031 §5 ·
    0030 SP2's law): per intent — every claim wearing its state, every source
    named, nothing stored twice. The package names its subscription (0032 §4) —
    the package and its supply line, one picture."""
    subs = wire_subscriptions(port, scope)
    entries, bodies, _ = floor_knowledge(port, scope)
    superseded = {d for e in entries for d in e["derived_from"]}
    domains: dict[str, dict] = {}
    for e in entries:
        ref = e["ref"]
        b = bodies.get(ref) or {}
        key = str(b.get("intent") or b.get("category") or "uncategorized")
        d = domains.setdefault(key, {"topic": key, "states": {}, "sources": set(),
                                     "versions": 0, "current": 0})
        d["versions"] += 1
        if (b.get("source") or {}).get("did"):
            d["sources"].add(b["source"]["did"])
        if ref not in superseded:
            d["current"] += 1
            st = str(b.get("state") or "?")
            d["states"][st] = d["states"].get(st, 0) + 1
    rows = []
    for d in sorted(domains.values(), key=lambda x: x["topic"]):
        if topic and topic.lower() not in d["topic"].lower():
            continue
        states = " · ".join(f"{k} {v}" for k, v in sorted(d["states"].items()))
        rows.append({"topic": d["topic"][:60],
                     "meta": f"{d['current']} current of {d['versions']} version(s) · "
                             f"{states or 'no states'} · {len(d['sources'])} source(s)"
                             + serials.named_supply(subs, d["topic"]),
                     "doubted": bool(d["states"].get("investigating")
                                     or d["states"].get("recalled"))})
    return rows


def tool_invoke(payload: dict) -> dict:
    """0054 sp2 — the Farm's ONE invoke door (0018 finally callable): resolve
    the SERVING service on the named floor, refuse the discredited at the
    threshold (0026 §5), METER FIRST — the plane's refusal of a non-serving
    service is the authorization, not telemetry — then execute against the
    service's own endpoint (POST {endpoint}/call, the local-stall protocol)
    and return the result. Bulk results never become records here (the
    pointer law, 0039): the caller's own stage observations carry the digest
    and the provenance. Every refusal wears the one face (rule 4)."""
    REFUSED = {"error": "request cannot be served under this capability"}
    service = str(payload.get("service") or "")
    tool = str(payload.get("tool") or "")
    args = payload.get("args") or {}
    did = str(payload.get("did") or "anonymous-consumer")
    port = int(payload.get("port") or 4520)
    scope = FLOOR_SCOPES.get(port) or ""
    try:
        roster = (call(port, "GET", "/farm") or {}).get("services", [])
    except Exception:
        return REFUSED
    svc = next((s for s in roster if s.get("name") == service
                and s.get("state") == "serving"), None)
    if not svc or not isinstance(svc.get("endpoint"), str):
        return REFUSED
    if tool not in {t.get("name") for t in (svc.get("manifest") or [])}:
        return REFUSED                       # off the pinned manifest = not a tool
    try:
        _, bodies, _ = floor_knowledge(port, scope)
        if svc.get("did") in purge.discredited_dids(bodies):
            return REFUSED
    except Exception:
        pass
    t0 = time.time()
    try:                                     # the gate: a non-serving service 403s here
        call(port, "POST", "/farm/meter",
             {"name": service, "caller": did, "ms": 0})
    except Exception:
        return REFUSED
    try:
        req = urllib.request.Request(
            svc["endpoint"].rstrip("/") + "/call", method="POST",
            data=json.dumps({"tool": tool, "args": args}).encode(),
            headers={"Content-Type": "application/json"})
        out = json.loads(urllib.request.urlopen(req, timeout=45).read())
    except Exception as e:
        return {"error": f"the stall did not answer: {str(e)[:100]}"}
    if isinstance(out, dict):
        out["_served"] = {"service": service, "by": svc.get("did"),
                          "ms": int((time.time() - t0) * 1000)}
    return out


def gather(port: int, scope: str, text: str, want_results: bool = False):
    """want_results (0054 sp3): the queue path returns TYPED findings beside
    the admission note — the desk's analysts read content, not counts; the
    parlor path keeps its prose. The records stay quarantined either way."""
    src = farm_search_source(port)
    if src is None:
        note = ("nothing gathered — the Farm has no serving search source. "
                "Plant one in the Farm tab (Tavily preset).")
        return {"note": note, "findings": []} if want_results else note
    # the door remembers the infection (0026 §5): a source the universe recalled
    # does not re-enter the record — refused at admission, loudly, on the record
    _, bodies, _ = floor_knowledge(port, scope)
    if src.get("did") in purge.discredited_dids(bodies):
        seat_kp, seat_did = lib_seat(scope)
        note = make_memory({"did": seat_did, "scope": scope}, seat_kp, scope,
                           {"immune": {"refused_source": src["did"],
                                       "service": src["name"], "intent": text}},
                           kind="semantic", tags=["librarian", "immune-refusal"])
        try:
            call(port, "POST", "/records", note)
        except Exception as e:
            print(f"    (immune-refusal write failed: {e})")
        note = (f"refused at the door — {src['name']} was recalled on this floor; "
                "a discredited source does not re-enter the record (0026 §5). "
                "the refusal itself is on the record.")
        return {"note": note, "findings": []} if want_results else note
    t0 = time.time()
    results = tavily(text)
    seat_kp, seat_did = lib_seat(scope)       # her seat at THIS floor (0023 §1)
    call(port, "POST", "/farm/meter", {"name": src["name"], "caller": seat_did,
                                       "ms": int((time.time() - t0) * 1000)})
    agent = {"did": seat_did, "scope": scope}
    for r in results:
        body = {"knowledge": f"{r['title']} — {r['content'][:120]}",
                "source": {"did": src["did"], "ref": r.get("url", "")},
                "state": "untrusted", "intent": text}
        rec = make_memory(agent, seat_kp, scope, body, kind="semantic",
                          tags=["knowledge", "gathered"],
                          provenance_class="ingested-archive")
        call(port, "POST", "/records", rec)
    note = f"admitted to the Window — {len(results)} finding(s) via {src['name']}, quarantined at 0.0000"
    if want_results:
        return {"note": note, "findings": [
            {"title": str(f.get("title", ""))[:200],
             "content": str(f.get("content", ""))[:700],
             "url": str(f.get("url", ""))} for f in results]}
    return note


def on_purge(port: int, scope: str, r: dict) -> None:
    """The operational path (0026 §2): destruction STAGES AND HOLDS. Bars are
    absolute (0012 §5) — below two control-entitled humans nothing executes; a
    solo universe can contain forever but destroy only when quorum exists. The
    seal lands first (0026 §3): the named refs stop answering the moment the
    purge stages, however long the humans take."""
    from orreth_sim.librarian import tainted_refs
    seat_kp, seat_did = lib_seat(scope)
    refs = [x for x in (r.get("refs") or []) if x]
    if not refs and r.get("source_did"):      # a purge may name a source instead —
        entries, _, _ = floor_knowledge(port, scope)
        refs = tainted_refs(entries, r["source_did"])  # its whole lineage seals
    if not refs:
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "denied",
              "result": "nothing to seal — a purge names refs or a source"})
        return
    reason = str(r.get("reason") or r.get("text") or "operational purge staged")
    seal = purge.make_seal({"did": seat_did, "scope": scope}, seat_kp, scope,
                           refs, reason=reason, request_id=str(r.get("id") or ""))
    try:
        call(port, "POST", "/records", seal)
    except Exception as e:
        print(f"    (seal write failed: {e})")
    msg = purge.held_message(1)
    call(port, "POST", "/requests/resolve",
         {"id": r["id"], "status": "staged",
          "result": {"held": msg, "sealed": len(refs), "seal": seal["id"]}})
    print(f"  ↳ purge {r['id']}: {len(refs)} ref(s) sealed — {msg}")


# ---------------------------------------------------------------- the fingertip (0027)

ORCH = _seed("orchestrator")                 # the orchestration seat — one self, persisted
ORCH_DID = crypto.did_key_for(ORCH.public)
MON = _seed("monitor")                       # the standing portfolio monitor (JB lock)
MON_DID = crypto.did_key_for(MON.public)
_OBJECTIVES: dict = {}                       # objective req id → flow state
_MONITOR_LAST = 0.0
MONITOR_EVERY = 600                          # the monitor's own cadence, not the beat's


def finger_seat(scope: str):
    """The floor's fingertip and its scribe — two selves that survive the process
    (0002 §1). The scribe authors the RunRecords: nothing grades its own yardstick."""
    fkp = _seed("fingertip-" + scope.replace("/", "~"))
    skp = _seed("fingertip-scribe-" + scope.replace("/", "~"))
    return fkp, crypto.did_key_for(fkp.public), skp, crypto.did_key_for(skp.public)


def _req(port: int, req_id: str) -> dict | None:
    try:
        rows = call(port, "GET", "/requests").get("requests", [])
    except Exception:
        return None
    return next((x for x in rows if x.get("id") == req_id), None)


_PLANS: dict = {}                            # objective req id → the curated plan


def curate_plan(port: int, scope: str, r: dict) -> dict:
    """0030 §3: the orchestration seat curates the objective into a PLAN — the
    intentions, their seats and budget slices, and the question the flow will ask —
    BEFORE anything moves. The plan is what stages for the human."""
    text = str(r.get("text") or "").strip() or "an unnamed objective"
    goal = crypto.content_hash({"objective": text, "req": r["id"]})
    targets = [x for x in (r.get("seats") or []) if x] or \
        [s for p, s in sorted(FLOOR_SCOPES.items())
         if s != scope and is_within(s, scope)]
    share = max(int(r.get("budget") or 2400) // max(len(targets) + 1, 1), 60)
    intentions, dark = [], []
    for target in targets:
        if next((p for p, s in FLOOR_SCOPES.items() if s == target), None) is None:
            dark.append({"seat": target, "why": "no such floor on the wire"})
            continue
        entry = {"seat": target, "budget": {"tokens": share},
                 "intent": f"carry this intention of the objective at your seat: {text}"}
        if not fingertip.dispatch_allowed(scope, target):
            entry["beyond_token"] = True     # honest in the plan: it will ask leave
        intentions.append(entry)
    return {"objective": text, "goal": goal, "intentions": intentions, "dark": dark,
            "question": "Before this work runs, one thing needs your answer: where should the results of “" + text[:140] + "” be delivered? Answer below — if no one answers in time, the plan treats silence as a no and moves on without it.",
            "share": share}


def on_objective(port: int, scope: str, r: dict) -> None:
    """The plan gate (0030 §3, JB canon 2026-07-12): the objective is curated and
    STAGED — the plan lands as a signed record, the request holds at the human's
    gate, and NOTHING fans. Origin plans always wait for their human."""
    plan = curate_plan(port, scope, r)
    me = {"did": ORCH_DID, "scope": scope}
    rec = make_memory(me, ORCH, scope, {"plan": plan}, kind="semantic",
                      tags=["plan", *fingertip.coordinate_tags(plan["goal"])])
    rec["coordinate"] = fingertip.coordinate(objective=plan["goal"])  # hard (the gate)
    try:
        call(port, "POST", "/records", rec)
    except Exception as e:
        print(f"    (plan record write failed: {e})")
    _PLANS[r["id"]] = plan
    if r.get("rubric"):                # G6: the objective's declared yardstick —
        rubric_note(plan["goal"], str(r["rubric"]))  # the assay judges by IT
    beyond = sum(1 for i in plan["intentions"] if i.get("beyond_token"))
    summary = (f"{len(plan['intentions'])} intention(s) → "
               + ", ".join(i["seat"].split("/")[-1] for i in plan["intentions"][:6])
               + " · asks you 1 question"
               + (f" · {beyond} beyond this token (will ask leave)" if beyond else ""))
    # the charter coupling (0032 §4): an acquisition-shaped objective offers
    # "…and keep it fresh" on its plan — plainly worded, unchecked by default;
    # one approval moment, both consequences legible
    offer = serials.keep_fresh_offer(plan["objective"])
    # 0047 sp3 — the studio reads: an understand leg rides the queue (0027 §2:
    # dispatch is a governed request) and the plan card carries the reading —
    # or, honestly, its absence. The gate never WAITS on the studio: the card
    # stages now, the reading arrives when the mind answers (studio_tend).
    leg = None
    try:
        leg = call(port, "POST", "/requests", {
            "kind": "understand", "of": r["id"],
            "objective": plan["objective"], "rubric": str(r.get("rubric") or ""),
            "text": f"the studio reads: {plan['objective'][:64]}"})["id"]
    except Exception as e:
        print(f"    (understand leg failed to post: {e})")
    call(port, "POST", "/requests/resolve",
         {"id": r["id"], "status": "staged",
          "result": {"plan_summary": summary, "plan": plan, "plan_record": rec["id"],
                     # the plan made visible (0031 §6): composed here, rendered blind
                     "graph": fingertip.choreography(plan),
                     **({"keep_fresh_offer": offer} if offer else {}),
                     "understanding": ({"state": "asked", "leg": leg,
                                        "asked_at": NOW()} if leg else
                                       {"state": "dark",
                                        "note": "the studio could not be "
                                                "asked — staged without a "
                                                "reading"}),
                     # 0047 sp4: every card DECLARES who planned it — the
                     # arithmetic fallback wears its label until (unless) the
                     # studio's plan survives the save gate and takes over
                     "planned_by": {"state": "fallback",
                                    "label": sentence(port, "plan-fallback-label")},
                     "held": "the plan waits for you — approve to fan (0030 §3)"}})
    print(f"  ↳ objective {r['id']}: plan staged — {summary}"
          + (f" · offers to keep “{offer['topic'][:40]}” fresh" if offer else ""))


def on_objective_approved(port: int, scope: str, r: dict) -> None:
    """The human's word arrived (0030 §3): the approved plan fans — intentions
    ride the queue down, the question stages, the tending begins. Entitlement is
    the token (JB lock 2026-07-11): a seat beyond it gets an ask, never a skip.
    The charter coupling (0032 §4): when the human checked "…and keep it fresh",
    the SAME word opens the subscription — one approval moment, both
    consequences; the record still mints on its own worldline, deriving from
    this very approval."""
    res = r.get("result") or {}
    offer = res.get("keep_fresh_offer")
    if res.get("keep_fresh") and offer:
        want = serials.slug(offer["topic"])
        standing = any(s.get("posture") == "deliver"
                       and serials.slug(s.get("topic", "")) == want
                       for s in wire_subscriptions(port, scope))
        if standing:
            print(f"  ↳ the desk already keeps “{offer['topic'][:40]}” fresh — "
                  "one subscription, never two")
        else:
            seat_kp, seat_did = lib_seat(scope)
            rec = serials.make_subscription({"did": seat_did, "scope": scope},
                                            seat_kp, scope, topic=offer["topic"],
                                            approved_ref=str(r.get("id") or ""))
            try:
                call(port, "POST", "/records", rec)
                print(f"  ↳ the plan fans AND the desk opens — “{offer['topic'][:40]}” "
                      f"kept fresh on the same word ({rec['id'][:18]}…)")
            except Exception as e:
                print(f"    (charter-coupled subscription failed: {e})")
    # 0047 sp4 — the CARD is the truth the human approved (rule 7, one
    # picture): the fan uses the plan the card showed, mind-authored or
    # fallback; re-curating is the last resort of a cardless resurrection
    plan = ((r.get("result") or {}).get("plan")
            or _PLANS.get(r["id"]) or curate_plan(port, scope, r))
    _PLANS.pop(r["id"], None)
    # 0047 sp5 — the human's word grows the hands: the checked gap offer
    # fires one commission per named lack (0045 law 6's whole loop — gather,
    # draft, stage; the newborn craft still WAITS at the human's gate)
    _res = r.get("result") or {}
    _goffer = _res.get("gap_offer")
    if _res.get("grow_craft") and _goffer:
        for _g in _goffer.get("gaps", []):
            try:
                _cr = call(port, "POST", "/requests", {
                    "kind": "commission", "craft_kind": "skill",
                    "born_of": r["id"],
                    "text": f"grow the craft this objective lacked "
                            f"(born of {r['id']}): {_g}"})
                print(f"  🌱 gap → commission {_cr['id']}: “{_g[:64]}”")
            except Exception as e:
                print(f"    (gap commission failed to post: {e})")
    legs, dark = {}, list(plan["dark"])
    for entry in plan["intentions"]:
        target = entry["seat"]
        t_port = next((p for p, s in FLOOR_SCOPES.items() if s == target), None)
        if t_port is None:
            dark.append({"seat": target, "why": "floor went dark since staging"})
            continue
        if entry.get("beyond_token"):
            try:                              # refuse AND ask — the flow degrades honestly
                ask = call(t_port, "POST", "/requests",
                           {"kind": "entitlement", "of": plan["goal"],
                            "text": f"orchestration at {scope} asks leave to dispatch "
                                    f"an intention of “{plan['objective'][:60]}”"})
                dark.append({"seat": target, "ask": ask.get("id")})
            except Exception:
                dark.append({"seat": target, "why": "unreachable"})
            continue
        work = fingertip.make_intention(plan["goal"], entry["intent"],
                                        entry["budget"]["tokens"])
        # the aperture (0031 §2, the gate): the dispatching seat signs the whole
        # opening — the wire's law is the human-approved plan record; behavior
        # pins are the shelf's active version (the shelf speaks at dispatch)
        _, fdid, _, _ = finger_seat(target)
        actives = wire_assets(universe_port(port), "asset", name=ASSET_NAME)
        ap = fingertip.make_aperture(
            {"did": ORCH_DID, "scope": scope}, ORCH, scope,
            of=work["id"], for_agent=fdid,
            law=str((r.get("result") or {}).get("plan_record") or plan["goal"]),
            task={"intent": work["intent"], "budget": dict(work["budget"])},
            behavior={"profile": actives[-1][0] if actives else "genesis"},
            knowledge=list(work.get("refs") or []),
            objective=plan["goal"])
        try:
            call(port, "POST", "/records", ap)
        except Exception as e:
            print(f"    (aperture write failed: {e})")
        leg = call(t_port, "POST", "/requests",
                   {"kind": "intention", "of": plan["goal"], "intention": work,
                    "aperture": ap["id"], "text": work["intent"][:120]})
        legs[t_port] = {"id": leg["id"], "seat": target, "iid": work["id"]}
    q = call(port, "POST", "/requests",
             {"kind": "question", "of": plan["goal"], "text": plan["question"]})
    _OBJECTIVES[r["id"]] = {"home": port, "scope": scope, "goal": plan["goal"],
                            "text": plan["objective"], "legs": legs, "dark": dark,
                            "question": q["id"], "iac": None, "share": plan["share"],
                            "plan": plan,        # the walk shows what rode down (0031 §6)
                            "deadline": time.time() + 180}
    print(f"  ↳ objective {r['id']} approved: {len(legs)} intention(s) fanned, "
          f"{len(dark)} dark, one question waits for you")


def on_intention(port: int, scope: str, r: dict) -> None:
    """The bottom of the graph (0027 §3 · 0030): the floor's fingertip carries its
    intention — the deterministic keyless floor for now; models join via the stable
    when the floor is fueled. Scratch evaporates (R7): what lands is the
    scribe-signed RunRecord (author ≠ agent, 0005) and the outcome that rides up."""
    work = r.get("intention") or r.get("sliver") or {}   # old rows keep their word
    intent = str(work.get("intent") or r.get("text") or "").strip()
    started, t0 = NOW(), time.perf_counter()  # the wire flow's stopwatch (0043 sp5)
    fkp, fdid, skp, sdid = finger_seat(scope)
    answer = f"intention carried at {scope}: {intent[:140]}"
    run = {
        "id": crypto.content_hash({"i": intent, "c": 1, "at": NOW(), "a": fdid}),
        "agent": fdid, "scope": scope,
        "goal_hash": str(work.get("of") or crypto.content_hash({"intent": intent})),
        "occurred_at": NOW(), "outcome": "success",
        "scores": [{"objective": "objective-met", "score": 1.0}],
        "cost": {"tokens": 0, "model_calls": 0},
        # the run pins the whole opening when one was cut (the gate, 0031 §2)
        **({"context_hash": str(r["aperture"])} if r.get("aperture") else {}),
        "author": sdid,
    }
    run["sig"] = skp.sign(sdid, {k: run[k] for k in
                                 ("id", "agent", "scope", "goal_hash", "occurred_at")})
    try:
        call(port, "POST", "/runs", run)
    except Exception as e:
        print(f"    (run record refused: {e})")
    outcome = make_memory({"did": fdid, "scope": scope}, fkp, scope,
                          {"outcome": {"intention": r.get("id"), "of": work.get("of"),
                                       "status": "done", "answer": answer,
                                       "cycles": 1,
                                       # the span rides the SIGNED record —
                                       # log-truth by construction (0043 sp5)
                                       "span": {"started": started, "ended": NOW(),
                                                "ms": int((time.perf_counter()
                                                           - t0) * 1000)}}},
                          kind="semantic",
                          tags=["intention-outcome",
                                *fingertip.coordinate_tags(work.get("of"),
                                                           work.get("id"))])
    outcome["coordinate"] = fingertip.coordinate(objective=work.get("of"),
                                                 intention=work.get("id"))
    try:
        call(port, "POST", "/records", outcome)
    except Exception as e:
        print(f"    (outcome write failed: {e})")
    call(port, "POST", "/requests/resolve",
         {"id": r["id"], "status": "done",
          "result": {"answer": answer, "outcome": outcome["id"], "cycles": 1,
                     "status": "done"}})
    print(f"  ↳ intention at {scope}: done — outcome {outcome['id'][:18]}…")


def tend_objectives() -> None:
    """Compose and resolve every objective whose branches are terminal — or whose
    horizon closed. Review rides altitude (0027 §6): the orchestration seat grades
    each return with a critic marker BEFORE it enters the assembly, and the
    resolution of the human's request is the only completion confirmation."""
    for rid, st in list(_OBJECTIVES.items()):
        try:
            _tend_objective(rid, st)
        except Exception as e:
            print(f"    (objective {rid} tending hiccup: {e})")


def _tend_objective(rid: str, st: dict) -> None:
    home, scope = st["home"], st["scope"]
    if st["iac"] is None:
        q = _req(home, st["question"])
        if q is not None and q.get("status") == "done":
            res = q.get("result")
            word = str((res or {}).get("answer") if isinstance(res, dict) else res or "")
            st["answer_word"] = word          # the human's word rides into the report
            work = fingertip.make_intention(
                st["goal"], f"provision infrastructure for “{st['text'][:60]}” — "
                            f"the human answered: {word[:80]}", st["share"])
            leg = call(home, "POST", "/requests",
                       {"kind": "intention", "of": st["goal"], "intention": work,
                        "text": work["intent"][:120]})
            st["iac"] = {"id": leg["id"], "seat": scope, "iid": work["id"]}
        elif q is not None and q.get("status") in ("denied", "expired"):
            st["iac"] = {"denied": True}      # silence never approves (0012)
    pending_question = st["iac"] is None
    watch = list(st["legs"].items())
    if st["iac"] and "id" in st["iac"]:
        watch.append((home, st["iac"]))
    branches, open_legs = [], 0
    for port, leg in watch:
        req = _req(port, leg["id"])
        if req is None or req.get("status") == "pending":
            open_legs += 1
            continue
        res = req.get("result") if isinstance(req.get("result"), dict) else {}
        branches.append({"intention": leg["id"], "seat": leg["seat"],
                         "iid": leg.get("iid"),
                         "status": res.get("status", "done"),
                         "answer": res.get("answer", ""),
                         "cycles": res.get("cycles"),
                         "outcome": res.get("outcome", "")})
    if (open_legs or pending_question) and time.time() < st["deadline"]:
        return                                # branches still riding; the queue is patient
    me = {"did": ORCH_DID, "scope": scope}
    for b in branches:                        # the dispatching seat grades every return
        if not b["outcome"] or "severity" in b:
            continue
        b["severity"] = fingertip.review_severity(b["status"], b.get("cycles"))
        mk = markers.make_marker(me, ORCH, scope, [b["outcome"]],
                                 reason=f"review of intention at {b['seat']}: "
                                        f"{b['status']}",
                                 change_severity=b["severity"],
                                 extra_tags=fingertip.coordinate_tags(
                                     st["goal"], b.get("iid")))
        try:
            call(home, "POST", "/records", mk)
            b["marker"] = mk["id"]
        except Exception as e:
            print(f"    (review marker write failed: {e})")
    if pending_question:
        waiting = ["the deployment question expired unanswered — treated as a no"]
    elif st["iac"] and st["iac"].get("denied"):
        waiting = ["the deployment question — you answered no"]
    elif st["iac"] and not any(b["intention"] == st["iac"]["id"] for b in branches):
        waiting = ["the deployment answer is still being carried out"]
    else:
        waiting = []
    done = bool(branches) and all(b["status"] == "done" for b in branches) \
        and not waiting and not st["dark"]
    assembly = {"objective": st["text"], "goal_hash": st["goal"],
                "branches": branches,
                "verification": "complete" if done else "partial",
                **({"question_answer": st["answer_word"]}
                   if st.get("answer_word") else {}),
                **({"dark": st["dark"]} if st["dark"] else {}),
                **({"waiting": waiting} if waiting else {})}
    rec = make_memory(me, ORCH, scope, {"objective_outcome": assembly},
                      kind="semantic",
                      tags=["objective-outcome",
                            *fingertip.coordinate_tags(st["goal"])])
    try:
        call(home, "POST", "/records", rec)
    except Exception as e:
        print(f"    (objective outcome write failed: {e})")
    # 0033 §4, the index made visible: how many records across the floors cite
    # this objective's coordinate — a tag lookup, not a lineage recursion
    assembly["coordinate_citations"] = sum(
        coordinate_citations(p, s, st["goal"])
        for p, s in sorted(FLOOR_SCOPES.items()))
    call(home, "POST", "/requests/resolve",
         {"id": rid, "status": "done",
          "result": {"assembly": assembly, "record": rec["id"],
                     # the same picture, lit by what ran (0031 §6) — one world
                     "plan": st.get("plan"),
                     "graph": fingertip.choreography(
                         st.get("plan") or {"objective": st["text"]}, branches,
                         question_answer=st.get("answer_word"))}})
    del _OBJECTIVES[rid]
    print(f"  ↳ objective {rid} assembled: {assembly['verification']} — "
          f"{len(branches)} branch(es), your request is the confirmation")


def monitor_beat(port: int) -> None:
    """The standing portfolio monitor (0027, JB lock 2026-07-11): an immortal job
    beating like an organ (R8) — no completion condition exists. Aggregates only,
    the sibling-benchmark law (0005). Its factory-RL duty waits for spoonful 7."""
    global _MONITOR_LAST
    if time.time() - _MONITOR_LAST < MONITOR_EVERY:
        return
    try:
        ru = call(port, "GET", "/rollup")
        topo = call(port, "GET", "/topology")
    except Exception:
        return
    obs = {"portfolio": {"floors": len(topo.get("children") or []),
                         "memories": ru.get("memories", 0),
                         "runs": ru.get("runs", 0),
                         "success_rate": ru.get("success_rate", 0),
                         "usd": ru.get("usd", 0)}}
    rec = make_memory({"did": MON_DID, "scope": "u:demo"}, MON, "u:demo", obs,
                      kind="episodic", tags=["portfolio-observation", "standing"])
    try:
        call(port, "POST", "/records", rec)
        _MONITOR_LAST = time.time()
        print(f"  ↳ the monitor beats: {obs['portfolio']['floors']} branch(es), "
              f"{obs['portfolio']['memories']} memories, "
              f"{obs['portfolio']['success_rate']}% success")
    except Exception as e:
        print(f"    (monitor observation refused: {e})")


# ---------------------------------------------------------------- the improver (0028)

IMP = _seed("improver")                      # the improvement engine — one, universe floor
IMP_DID = crypto.did_key_for(IMP.public)
GOV = _seed("governance")                    # governance's first duty: the grade
GOV_DID = crypto.did_key_for(GOV.public)
ASSET_NAME = "fingertip-default"
_SENTENCES_PLANTED = False                   # 0050 sp1 — once per process
_IMPROVER_LAST = 0.0
IMPROVER_EVERY = int(os.environ.get("ORRETH_IMPROVER_EVERY", "600"))
SUCCESS_FLOOR = 90                           # below this, the receipts earn a nudge


# 0050 sp1 — the machine's speech served from the shelf: ONE voice for every
# floor (the universe shelf), cached a beat's breath; the genesis literal in
# orreth_sim.speech is the honest fallback — an edited sentence that refuses
# its slots never breaks a card, it just lets genesis speak and says so.
_SENTENCE_CACHE: dict[str, tuple[float, str | None]] = {}
SENTENCE_TTL = 60.0


def _sentence_active(u_port: int, name: str) -> str | None:
    """The shelf's current head for a sentence asset — newest non-superseded
    row's template (the craft-edit door's sibling semantics, read-side)."""
    now = time.time()
    hit = _SENTENCE_CACHE.get(name)
    if hit and now - hit[0] < SENTENCE_TTL:
        return hit[1]
    tmpl = None
    try:
        rows = wire_assets(u_port, "asset", name=name)
        superseded = {d for _, _, dl, _ in rows for d in dl}
        for rid, body, _, _t in reversed(rows):
            if rid in superseded:
                continue
            tmpl = ((body.get("asset") or {}).get("profile") or {}).get("template")
            break
    except Exception:
        tmpl = None                           # a dark wire never mutes a card
    _SENTENCE_CACHE[name] = (now, tmpl)
    return tmpl


def sentence(port: int, name: str, **slots) -> str:
    """Render the machine's sentence «name» with its facts: the shelf's head
    if it stands and fills, else genesis — loudly, never silently."""
    genesis = speech.SENTENCES[name]
    tmpl = _sentence_active(universe_port(port), name) or genesis
    try:
        return speech.render(tmpl, **slots)
    except ValueError as e:
        if tmpl != genesis:
            print(f"  🗣 sentence «{name}» head refused ({e}) — genesis speaks")
            return speech.render(genesis, **slots)
        raise


def wire_assets(port: int, tag: str, name: str | None = None, *,
                scope: str = "u:demo") -> list[tuple[str, dict, list, list]]:
    """The asset ledger as the improver may read it — its own token, bodies in
    hand, oldest first. Returns (ref, body, derived_from, tags) rows; name=None
    reads the whole shelf (0031 §4), a name narrows to one asset's chain.
    scope (0043 sp4): a floor beyond the universe — the assay and the
    experiment read where the work actually lives."""
    from datetime import datetime, timedelta, timezone
    token = _ROOT.issue_token(IMP_DID, "u:demo", [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc) - timedelta(days=365)).strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        r = call(port, "POST", "/retrieve", {
            "query": {"requester": IMP_DID, "subject": {"cohort": {"scope": scope}},
                      "space": "self", "time": {"from": frm}, "intent": "recall",
                      "budget": {"cost": 8}, "auth": "biscuit-sim"},
            "token": token, "requester_scope": scope})
    except Exception:
        return []
    rows = []
    for h in r.get("hits", []):
        tags = h.get("tags") or []
        if tag not in tags or (name is not None and name not in tags):
            continue
        try:
            body = call(port, "GET",
                        f"/records/{urllib.parse.quote(h['ref'], safe='')}/body")
        except Exception:
            continue
        if isinstance(body, dict):
            rows.append((h["ref"], body, h.get("derived_from") or [], tags,
                         h.get("occurred_at", "")))
    rows.sort(key=lambda x: x[4])
    return [(ref, body, dl, tags) for ref, body, dl, tags, _ in rows]


def improver_beat(port: int) -> None:
    """One improver on the universe floor (0028, JB lock 2026-07-11): a standing
    incarnation reading the risen evidence. It PROPOSES; governance grades; the
    lanes route. One open proposal per asset — the lane holds until it resolves."""
    global _IMPROVER_LAST
    if time.time() - _IMPROVER_LAST < IMPROVER_EVERY:
        return
    _IMPROVER_LAST = time.time()             # set early — a failing beat never hot-loops
    scope = UNIVERSE_SCOPE
    me = {"did": IMP_DID, "scope": scope}
    actives = wire_assets(port, "asset", name=ASSET_NAME)
    if not actives:
        genesis = improver.make_asset(me, IMP, scope, name=ASSET_NAME,
                                      profile={"max_cycles": 2, "max_obs": 3})
        try:
            call(port, "POST", "/records", genesis)
            print(f"  ↳ the smith plants the genesis asset — {genesis['id'][:18]}…")
        except Exception as e:
            print(f"    (genesis asset write failed: {e})")
        return
    # the prompt shelf plants beside it (0031 §4): the chassis constants become
    # version one — from here a prompt change is a rewrite the human gates
    from orreth_sim.chassis import _CRITIC, _PLAN
    for pname, text in (("prompt-plan", _PLAN), ("prompt-critic", _CRITIC)):
        if not wire_assets(port, "asset", name=pname):
            g = improver.make_asset(me, IMP, scope, name=pname,
                                    profile={"template": text})
            try:
                call(port, "POST", "/records", g)
                print(f"  ↳ the smith shelves {pname} v1 — the prompt leaves the code")
            except Exception as e:
                print(f"    ({pname} genesis failed: {e})")
    # 0050 sp1 — the machine's SPEECH plants beside the prompts: every wave-1
    # sentence becomes an asset on the shelf, editable at the gates like any
    # craft; the code literal is genesis and fallback, never the living word.
    global _SENTENCES_PLANTED
    if not _SENTENCES_PLANTED:
        allthere = True
        for sname, stext in {**speech.SENTENCES, **speech.PERSONAS,
                             **_CAP_PLANT,
                             "the-memory-yardstick": YARDSTICK_V1}.items():
            if wire_assets(port, "asset", name=sname):
                continue
            g = improver.make_asset(me, IMP, scope, name=sname,
                                    profile=(stext if isinstance(stext, dict)
                                             else {"template": stext}))
            try:
                call(port, "POST", "/records", g)
                print(f"  🗣 the shelf takes «{sname}» v1 — the sentence "
                      "leaves the code")
            except Exception as e:
                allthere = False
                print(f"    ({sname} genesis failed: {e})")
        _SENTENCES_PLANTED = allthere
    closed = {d for _, _, dl, _ in actives for d in dl}
    closed |= {d for _, _, dl, _ in wire_assets(port, "asset-decline",
                                                name=ASSET_NAME) for d in dl}
    if any(rid not in closed
           for rid, _, _, _ in wire_assets(port, "asset-proposal", name=ASSET_NAME)):
        return                               # a proposal already waits — no storms
    try:
        ru = call(port, "GET", "/rollup")
    except Exception:
        return
    rate = int(ru.get("success_rate", 100))
    if rate >= SUCCESS_FLOOR:
        return                               # healthy assets are left alone
    rid, body, _, _ = actives[-1]
    base = dict((body.get("asset") or {}).get("profile") or {})
    prof = dict(base)
    prof["max_cycles"] = min(int(prof.get("max_cycles", 2)) + 1, 5)
    if prof == base:
        return                               # the dial is at its stop — nothing to propose
    # the human's words ride as evidence (0031 §4): feedback is never an
    # auto-trigger, but a proposal MUST carry what the human said
    fb_refs = [ref for ref, _, _, _ in
               wire_assets(port, "asset-feedback", name=ASSET_NAME)][-5:]
    proposal = improver.make_asset(me, IMP, scope, name=ASSET_NAME, profile=prof,
                                   derived_from=[rid, *fb_refs], tag="asset-proposal")
    try:
        call(port, "POST", "/records", proposal)
        call(port, "POST", "/requests",
             {"kind": "improvement", "proposal": proposal["id"],
              "text": f"the smith proposes a new {ASSET_NAME}: success "
                      f"{rate}% < {SUCCESS_FLOOR}% — a bounded nudge, receipts attached"})
        print(f"  ↳ the smith proposes: {ASSET_NAME} at {rate}% — "
              f"{proposal['id'][:18]}…")
    except Exception as e:
        print(f"    (improvement proposal failed: {e})")


def wire_receipts(port: int, refs: list) -> list[dict]:
    """Receipts resolved to readable lines (0031 §4) — the wire's mirror of the
    sim's approval_package walk: the human reads receipts, never raw refs."""
    out = []
    for ref in refs[:8]:
        try:
            body = call(port, "GET",
                        f"/records/{urllib.parse.quote(ref, safe='')}/body")
        except Exception:
            out.append({"ref": ref, "what": "a record beyond this floor"})
            continue
        if not isinstance(body, dict):
            out.append({"ref": ref, "what": "cited evidence"})
        elif "asset" in body:
            out.append({"ref": ref, "what": "the version this proposal succeeds"})
        elif "feedback" in body:
            fb = body.get("feedback") or {}
            quoted = str(fb.get("quoted") or "")[:80]
            who = "the mirror's finding" if fb.get("by") == "mirror" \
                else "the human's words"
            out.append({"ref": ref, "what": f"{who}: “{quoted}”"})
        elif "marker" in body:
            why = str((body.get("marker") or {}).get("reason") or "")[:80]
            out.append({"ref": ref, "what": f"a graded review — {why}"})
        elif "parked_intent" in body:
            out.append({"ref": ref, "what": "a parked intent — the breaker fired"})
        else:
            out.append({"ref": ref, "what": "cited evidence"})
    return out


def wire_package(port: int, pid: str) -> dict | None:
    """The approval package from the wire's records (0031 §4): the computed
    diff, the receipts, the rollback that never left. `_profile` rides inside
    for adoption and is stripped before the package travels."""
    props = {ref: (body, dl, tags) for ref, body, dl, tags
             in wire_assets(port, "asset-proposal")}
    if pid not in props:
        return None
    body, dl, tags = props[pid]
    name = str((body.get("asset") or {}).get("name") or
               next((t for t in tags if t != "asset-proposal"), ASSET_NAME))
    new_prof = (body.get("asset") or {}).get("profile") or {}
    actives = wire_assets(port, "asset", name=name)
    old_prof = (actives[-1][1].get("asset") or {}).get("profile") or {} \
        if actives else {}
    changed = sorted(k for k in set(old_prof) | set(new_prof)
                     if old_prof.get(k) != new_prof.get(k))
    kind = improver.classify_change(old_prof, new_prof) if changed else "no-op"
    return {"asset": name, "kind": kind,
            "lane": improver.LANES.get(kind, "refused"),
            "changed": {k: {"from": old_prof.get(k), "to": new_prof.get(k)}
                        for k in changed},
            "receipts": wire_receipts(port, dl),
            "rollback": actives[-1][0] if actives else None,
            "checks": {"no_op": not changed,
                       "cites_active": bool(actives and actives[-1][0] in dl)},
            "_profile": new_prof}


def on_improvement(port: int, scope: str, r: dict, *, approved: bool = False,
                   declined: bool = False) -> None:
    """Governance's duty (0028 · 0031 §4): the change kind is COMPUTED by diffing
    versions, never declared; the grade is a marker on the record; the lanes
    route — medium adopts with a loud record, high waits for the human. Approved
    is the human's word: adopt, citing the proposal. Denied is a word too: the
    decline derives from the proposal and the lane opens again — a refusal never
    dams the river."""
    pid = str(r.get("proposal") or "")
    pkg = wire_package(port, pid)
    gov = {"did": GOV_DID, "scope": scope}
    if pkg is None:
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"refused": "no such proposal on the shelf"}})
        return
    name, new_prof = pkg["asset"], pkg.pop("_profile")

    def close_lane(reason: str) -> str:
        dec = make_memory(gov, GOV, scope,
                          {"decline": {"asset": name, "proposal": pid,
                                       "reason": reason}},
                          kind="semantic", tags=["asset-decline", name])
        dec["derived_from"] = [pid]
        call(port, "POST", "/records", dec)
        return dec["id"]

    if declined:                             # the human's no is a record too (0031 §4)
        did_ = close_lane("declined by the human")
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"declined": did_, "asset": name,
                         "lane": "the human declined — the lane opens"}})
        print(f"  ↳ improvement declined by the human — {name}'s lane opens")
        return
    if approved:                             # the human opened the high lane
        adopted = improver.make_asset(gov, GOV, scope, name=name,
                                      profile=new_prof, adopted_from=pid,
                                      derived_from=[pid])
        call(port, "POST", "/records", adopted)
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"adopted": adopted["id"], "asset": name,
                         "lane": "high — the human approved",
                         "resolved_at": NOW()}})
        print(f"  ↳ improvement adopted on the human's word — {adopted['id'][:18]}…")
        return
    if pkg["checks"]["no_op"]:               # a no-op is refused AND its lane closed
        did_ = close_lane("no-op — the proposal changes nothing")
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"refused": "the proposal changes nothing — no lane to ride",
                         "declined": did_}})
        return
    kind, sev = pkg["kind"], improver.LANES[pkg["kind"]]
    mk = markers.make_marker(gov, GOV, scope, [pid],
                             reason=f"improvement proposal for {name}: {kind}",
                             change_severity=sev)
    try:
        call(port, "POST", "/records", mk)
    except Exception as e:
        print(f"    (grade marker write failed: {e})")
    if sev == "high":
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "staged",
              "result": {"held": "a rewrite waits for the human (R6) — adopt or "
                                 "decline at the gate",
                         "kind": kind, "marker": mk["id"], "package": pkg,
                         "package_text": parlor.package_text(pkg)}})
        print(f"  ↳ improvement held on the high lane: {kind} — the gate waits")
        return
    adopted = improver.make_asset(gov, GOV, scope, name=name,
                                  profile=new_prof, adopted_from=pid,
                                  derived_from=[pid, mk["id"]])
    call(port, "POST", "/records", adopted)
    call(port, "POST", "/requests/resolve",
         {"id": r["id"], "status": "done",
          "result": {"adopted": adopted["id"], "kind": kind, "marker": mk["id"],
                     "lane": "medium — co-review + notify",
                     "resolved_at": NOW()}})
    print(f"  ↳ improvement adopted on the medium lane ({kind}) — "
          f"{adopted['id'][:18]}… · co-review rides behind (R6)")


def wire_shelf(port: int) -> list[dict]:
    """The one shelf from the wire (0031 §4): every behavioral asset by name —
    versions, the active head, open proposals, the human's feedback count."""
    rows: dict[str, dict] = {}
    closed: dict[str, set] = {}

    def row(name: str) -> dict:
        return rows.setdefault(name, {"name": name, "versions": 0, "proposals": 0,
                                      "feedback": 0, "active": None, "open": None})

    for tag, key in (("asset", "versions"), ("asset-proposal", "proposals"),
                     ("asset-feedback", "feedback"), ("asset-decline", None)):
        for ref, body, dl, tags in wire_assets(port, tag):
            name = next((t for t in tags if t != tag), None) or \
                str((body.get("asset") or {}).get("name") or "?")
            rw = row(name)
            if key:
                rw[key] += 1
            if tag == "asset":
                rw["active"] = ref            # oldest-first: the last write wins
            if tag in ("asset", "asset-decline"):
                closed.setdefault(name, set()).update(dl)
    for ref, _body, _dl, tags in wire_assets(port, "asset-proposal"):
        name = next((t for t in tags if t != "asset-proposal"), "?")
        if ref not in closed.get(name, set()):
            row(name)["open"] = ref
    return sorted(rows.values(), key=lambda x: x["name"])


def wire_walk_reply(port: int, name: str) -> str:
    """The version walk, composed for the parlor (0031 §4): oldest → active, the
    keys each version changed, and whether a proposal carried it in."""
    rows = wire_assets(port, "asset", name=name)
    if not rows:
        return (f"nothing on the shelf under “{name}” — say “show the shelf” for "
                "what stands.")
    lines, prev = [], {}
    for i, (ref, body, _dl, _tags) in enumerate(rows, 1):
        a = body.get("asset") or {}
        prof = a.get("profile") or {}
        changed = sorted(k for k in set(prev) | set(prof)
                         if prev.get(k) != prof.get(k))
        lines.append(f"v{i} [{ref[:14]}…] "
                     + ("genesis" if i == 1 else "changed " + (", ".join(changed)
                                                               or "nothing"))
                     + (" · adopted from a proposal" if a.get("adopted_from") else ""))
        prev = prof
    return (f"{name}, {len(rows)} version(s), oldest to active: " + "; ".join(lines)
            + ". every version a sibling — the old ones never die.")


def wire_feedback(port: int, scope: str, name: str, words: str) -> None:
    """The feedback door on the wire (0031 §4): grace signs the human's words
    VERBATIM, derived from the asset's active version — evidence her next beat
    must carry. Evidence, never an auto-trigger (v0)."""
    me = {"did": IMP_DID, "scope": scope}
    rec = make_memory(me, IMP, scope,
                      {"feedback": {"asset": name, "quoted": (words or "")[:400]}},
                      kind="semantic", tags=["asset-feedback", name])
    actives = wire_assets(port, "asset", name=name)
    if actives:
        rec["derived_from"] = [actives[-1][0]]
    try:
        call(port, "POST", "/records", rec)
        print(f"  ↳ feedback on {name} shelved verbatim — {rec['id'][:18]}…")
    except Exception as e:
        print(f"    (feedback write failed: {e})")


def universe_port(fallback: int) -> int:
    """One workshop, the universe floor (0028 lock · 0031 §4): grace's shelf
    lives at the apex, whichever floor received the ask."""
    return next((p for p, s in FLOOR_SCOPES.items() if s == UNIVERSE_SCOPE),
                fallback)


# ---------------------------------------------------------------- the estate (0037)

_CHARTER_PLANTED = False


def wire_estate(port: int) -> dict:
    """The architect reads his estate with his OWN authority (the parlor law):
    the charter's recalled answers, the open questions against the prod rung,
    and the acceptance gate's honest state. Plants the genesis charter asset on
    the first look — from then on the questions are data on the shelf."""
    global _CHARTER_PLANTED
    from datetime import datetime, timedelta, timezone

    from orreth_sim import estate, improver
    me = {"did": ALLEN_DID, "scope": UNIVERSE_SCOPE}
    token = _ROOT.issue_token(ALLEN_DID, "u:demo",
                              [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc) - timedelta(days=365)).strftime("%Y-%m-%dT%H:%M:%SZ")
    answers: dict = {}
    adopted = 0
    charter_rows = 0
    tmpl_hits: list = []
    try:
        r = call(port, "POST", "/retrieve", {
            "query": {"requester": ALLEN_DID,
                      "subject": {"cohort": {"scope": UNIVERSE_SCOPE}},
                      "space": "self", "time": {"from": frm}, "intent": "recall",
                      "budget": {"cost": 8}, "auth": "biscuit-sim"},
            "token": token, "requester_scope": UNIVERSE_SCOPE})
        hits = sorted(r.get("hits", []), key=lambda h: h.get("occurred_at", ""))
        for h in hits:
            tags = h.get("tags") or []
            if "estate-adopted" in tags:
                adopted += 1
            if estate.CHARTER_NAME in tags:
                charter_rows += 1
            if any(str(t).startswith("template-") for t in tags):
                tmpl_hits.append(h)
            if "estate-charter" not in tags:
                continue
            try:
                body = call(port, "GET",
                            f"/records/{urllib.parse.quote(h['ref'], safe='')}/body")
            except Exception:
                continue
            b = (body or {}).get("charter_answer") or {}
            # subject-less bodies predate the subject model (the 2026-07-22
            # rework) — skipped, never reinterpreted as estate policy; the
            # record stays whole in the window, as ever
            if b.get("key") and "subject" in b:
                answers[(b["key"], b.get("subject", ""))] = {
                    "answer": b.get("answer", ""), "by": b.get("by", ""),
                    "subject": b.get("subject", "")}
    except Exception:
        pass
    if not charter_rows and not _CHARTER_PLANTED:
        _CHARTER_PLANTED = True              # once per boot — the read lags a beat
        genesis = improver.make_asset(me, ALLEN, UNIVERSE_SCOPE,
                                      name=estate.CHARTER_NAME,
                                      profile=estate.CHARTER_GENESIS)
        try:
            call(port, "POST", "/records", genesis)
            print(f"  ↳ allen plants the charter — {genesis['id'][:18]}… "
                  "(a versioned asset; grace may propose revisions)")
        except Exception as e:
            print(f"    (charter genesis write failed: {e})")
    policy = {k: v for (k, s), v in answers.items() if s == ""}
    workloads: dict = {}
    for (k, s), v in answers.items():
        if s:
            workloads.setdefault(s, {})[k] = v
    plan: dict = {}
    deployed_stacks: list = []
    newest_planned: dict = {}
    for h in sorted(tmpl_hits, key=lambda h: h.get("occurred_at", ""))[-6:]:
        try:
            body = call(port, "GET",
                        f"/records/{urllib.parse.quote(h['ref'], safe='')}/body")
        except Exception:
            continue
        prof = ((body or {}).get("asset") or {}).get("profile") or {}
        if not prof.get("resources"):
            continue
        if prof.get("deployed"):
            deployed_stacks.append(prof)
        else:
            newest_planned = prof
    if deployed_stacks:                       # THE ESTATE — what the universe sees
        seen: dict = {}
        for p in deployed_stacks:             # newest template per stack wins
            seen[p.get("stack", p.get("subject", "?"))] = p
        adopted = len(seen)                   # stacks under governance, not receipts
        plan = {"subject": "the estate", "deployed": True,
                "yaml": list(seen.values())[-1].get("yaml", ""),
                "dag": estate.estate_dag(list(seen.values()), "deployed")}
    elif newest_planned:                      # the newest blueprint stands alone
        plan = {"subject": newest_planned.get("subject", "?"),
                "yaml": newest_planned.get("yaml", ""),
                "dag": estate._dag_for(newest_planned.get("subject", "?"),
                                       newest_planned["resources"], "planned")}
    return {"adopted": adopted, "gate_open": bool(adopted),
            "policy": policy, "workloads": workloads, "answers": answers,
            "plan": plan}


def wire_charter_answer(port: int, key: str, answer: str,
                        subject: str) -> str | None:
    """The human seat answers a question FOR a subject (0037 §3): a workload's
    name, or "" for deliberate estate policy. Lands allen-signed with the
    question, the subject, and who spoke — v0 honesty: the caller is the human
    seat, unsigned until 0012's registry."""
    from orreth_sim import estate
    qs = estate.CHARTER_GENESIS["questions"]
    if key not in qs:
        return ("that is not a charter question — the charter asks: "
                + " · ".join(qs))
    me = {"did": ALLEN_DID, "scope": UNIVERSE_SCOPE}
    rec = make_memory(me, ALLEN, UNIVERSE_SCOPE,
                      {"charter_answer": {"key": key, "question": qs[key],
                                          "answer": (answer or "")[:400],
                                          "subject": (subject or "")[:120],
                                          "by": "the human seat (v0 — unsigned "
                                                "until 0012's registry)"}},
                      kind="semantic", tags=["estate", "estate-charter", key])
    try:
        call(port, "POST", "/records", rec)
        print(f"  ↳ charter answer lands — {key} for "
              f"«{subject or 'the estate'}»: “{answer[:40]}” [{rec['id'][:18]}…]")
    except Exception as e:
        print(f"    (charter answer write failed: {e})")
        return "the answer stumbled at the record — try again"
    return None


def _wire_gaps(est: dict, subject: str) -> tuple[dict, dict]:
    """Per-subject charter resolution over wire answers (0037 §3): the
    workload's own word wins, estate policy underlies, history is offered in
    the question — never silently inherited."""
    from orreth_sim import estate
    have = est.get("answers") or {}
    gaps: dict = {}
    pinned: dict = {}
    for k, q in estate.CHARTER_GENESIS["questions"].items():
        own = have.get((k, subject))
        policy = have.get((k, ""))
        if own:
            pinned[k] = {**own, "scope": "workload"}
        elif policy:
            pinned[k] = {**policy, "scope": "estate-policy"}
        else:
            prior = [v for (kk, s), v in have.items() if kk == k and s]
            offer = (f' (last time: “{prior[-1]["answer"]}” for '
                     f'«{prior[-1]["subject"]}» — reuse?)') if prior else ""
            gaps[k] = q + offer
    return gaps, pinned


def _interrogation(subject: str, gaps: dict) -> str:
    qtext = " · ".join(f"{k} — {q}" for k, q in gaps.items())
    return (f"the charter interrogates «{subject}» before a prod plan "
            f"compiles (0037 §3) — {len(gaps)} question(s): {qtext}. "
            f"answer with “answer <question> for {subject}: <words>” — or "
            "“… for the estate: …” to set policy for everything.")


def wire_estate_create(port: int, ask: str) -> str:
    """A deployment ask — the CONSEQUENCE path: interrogated, and a clean
    charter stages the plan toward the gate (0012)."""
    from orreth_sim import estate
    est = wire_estate(port)
    subject = estate._slug(ask)
    gaps, pinned = _wire_gaps(est, subject)
    if gaps:
        return _interrogation(subject, gaps)
    call(port, "POST", "/requests",
         {"kind": "estate-plan",
          "text": f"the estate plans: “{ask}” — charter satisfied "
                  f"({sum(1 for v in pinned.values() if v['scope'] == 'estate-policy')} "
                  "from estate policy); the planned DAG and apply wait for a "
                  "human (0012)"})
    return (f"the charter is satisfied for «{subject}» — the plan stages with "
            "its answers pinned, and consequence waits for you at the gate "
            "(0012).")


def wire_estate_preview(port: int, ask: str) -> str:
    """PLAN IS FREE (§8.4): no gate, no consequence — the charter still
    interrogates (never a wrong picture). A clean preview compiles resources,
    yaml, and the planned DAG; the template lands as a recallable asset under
    allen's signature, and the room holds the picture."""
    from orreth_sim import estate, improver
    est = wire_estate(port)
    subject = estate._slug(ask)
    gaps, pinned = _wire_gaps(est, subject)
    if gaps:
        return _interrogation(subject, gaps)
    resources = estate._resources_for(ask, pinned)
    stack = f"orreth-{subject}"
    yaml = estate._yaml_for(stack, resources, pinned, subject)
    me = {"did": ALLEN_DID, "scope": UNIVERSE_SCOPE}
    asset = improver.make_asset(me, ALLEN, UNIVERSE_SCOPE,
                                name=f"template-{subject}",
                                profile={"yaml": yaml, "stack": stack,
                                         "subject": subject,
                                         "resources": resources})
    try:
        call(port, "POST", "/records", asset)
        print(f"  ↳ allen drafts {stack} — template asset {asset['id'][:18]}…")
    except Exception as e:
        print(f"    (template asset write failed: {e})")
    kinds = ", ".join(r["type"].split("::")[-1] for r in resources)
    return (f"planned, free of consequence (§8.4): {stack} — {len(resources)} "
            f"resource(s) ({kinds}), every property traced to the charter "
            f"({sum(1 for v in pinned.values() if v['scope'] == 'estate-policy')} "
            "answer(s) from estate policy). the picture and the yaml stand in "
            "my room; the template is on the record forever. applying it is "
            "another conversation — at the gate.")


ADOPT_STACKS = ("OrrethDemoStack", "JsbarthPipelineStack")


def _aws_cli(args: list, *, raw: bool = False):
    """The toolroom's one hand (0037 §5, v0): the aws CLI, invoked read-only
    under the jb_support profile with ambient AWS keys STRIPPED — custody is
    the profile's, never the process environment's. Full farm residency for
    local binaries (probe = version, pin = binary hash) is Farm-dive work."""
    import subprocess
    env = {k: v for k, v in os.environ.items() if not k.startswith("AWS_")}
    env["AWS_PROFILE"] = "jb_support"
    cmd = ["aws", *args] + ([] if raw else ["--output", "json"])
    try:
        p = subprocess.run(cmd, capture_output=True, text=True, timeout=90,
                           env=env)
    except Exception as e:
        return None, str(e)[:200]
    if p.returncode != 0:
        return None, (p.stderr or p.stdout or "cli error")[:200]
    if raw:
        return (p.stdout or "").strip(), None
    try:
        return json.loads(p.stdout or "null"), None
    except Exception:
        return (p.stdout or "").strip(), None


def on_estate_adopt(port: int, scope: str, r: dict, *, approved: bool = False,
                    declined: bool = False) -> None:
    """The brownfield walk (0037 §7, the acceptance gate's key): READ-ONLY —
    describe, fetch templates, attest; never mutate. It stages first (the
    first touch of the real estate is a consequence of trust); the human's
    word runs it; the receipts open the gate."""
    from orreth_sim import estate, improver
    if declined:
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"declined": True,
                         "reply": "the adoption was declined — the gate stands, "
                                  "and the record keeps that you chose"}})
        print("  ↳ estate adoption declined at the gate")
        return
    if not approved:
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "staged",
              "result": {"held": "the first touch of the real estate waits for "
                                 "you (0037 §7) — READ-ONLY: describe stacks, "
                                 "fetch templates, attest. never mutate.",
                         "stacks": list(ADOPT_STACKS)}})
        print("  ↳ estate adoption staged — the gate waits")
        return
    ver, verr = _aws_cli(["--version"], raw=True)
    me = {"did": ALLEN_DID, "scope": UNIVERSE_SCOPE}
    walked: list = []
    failed: list = []
    for stack in ADOPT_STACKS:
        tpl, err = _aws_cli(["cloudformation", "get-template", "--stack-name",
                             stack, "--query", "TemplateBody"])
        if err or not isinstance(tpl, dict):
            failed.append(f"{stack}: {err or 'no template body'}")
            continue
        resources = estate.parse_template_resources(tpl)
        phys, _ = _aws_cli(["cloudformation", "describe-stack-resources",
                            "--stack-name", stack,
                            "--query", "StackResources[].[LogicalResourceId,"
                                       "PhysicalResourceId]"])
        pmap = {row[0]: row[1] for row in (phys or []) if len(row) == 2}
        for res in resources:
            if pmap.get(res["id"]):
                res["properties"]["physical"] = str(pmap[res["id"]])[:48]
        subject = estate._slug(stack)
        asset = improver.make_asset(
            me, ALLEN, UNIVERSE_SCOPE, name=f"template-{subject}",
            profile={"yaml": json.dumps(tpl, indent=1)[:32000], "stack": stack,
                     "subject": subject, "resources": resources,
                     "deployed": True, "tool": ver or "aws-cli"})
        try:
            call(port, "POST", "/records", asset)
            walked.append({"stack": stack, "n": len(resources)})
            print(f"  ↳ allen adopts {stack} — {len(resources)} resource(s), "
                  f"template {asset['id'][:18]}…")
        except Exception as e:
            failed.append(f"{stack}: record write — {e}")
    if walked:
        adoption = make_memory(
            me, ALLEN, UNIVERSE_SCOPE,
            {"estate_adoption": {"stacks": [w["stack"] for w in walked],
                                 "posture": "read-only",
                                 "tool": ver or "aws-cli",
                                 "resources": sum(w["n"] for w in walked)}},
            kind="semantic", tags=["estate", "estate-adopted"])
        call(port, "POST", "/records", adoption)
    reply = (("the estate is adopted — "
              + ", ".join(f"{w['stack']} ({w['n']} resource(s))" for w in walked)
              + f", read-only, attested under {ver or 'the cli'}. THE "
                "ACCEPTANCE GATE OPENS: create may now stage, through the "
                "charter, at the gate (0037 §7).")
             if walked else "the walk could not see the estate — nothing "
                            "adopted, the gate stands.")
    if failed:
        reply += " honest misses: " + "; ".join(failed)
    call(port, "POST", "/requests/resolve",
         {"id": r["id"], "status": "done", "result": {"reply": reply,
          "walked": walked, "failed": failed,
          **({"resolved_at": NOW()} if walked else {})}})
    print(f"  ↳ estate adoption complete — {len(walked)} stack(s), "
          f"{len(failed)} miss(es)")


def _recalls_path(scope: str) -> Path:
    nest = HOME / "stacks" / scope.replace("/", "~")
    nest.mkdir(parents=True, exist_ok=True)
    return nest / "recalls.json"


def recalls_load(scope: str) -> dict:
    """THE PERSISTENT USAGE TAP (wire-honesty sp1, 2026-07-25): 0039 locked
    'usage is evidence' — but a per-request projection forgot its warmth with
    every request. The tap now survives the process the way the meter does:
    the nest holds it, every node wakes with it, the metabolism hears it."""
    p = _recalls_path(scope)
    try:
        return json.loads(p.read_text()) if p.exists() else {}
    except Exception:
        return {}


def recalls_save(scope: str, node) -> None:
    rec = getattr(node, "recalls", None)
    if rec:
        try:
            _recalls_path(scope).write_text(json.dumps(rec))
        except Exception:
            pass


def _stacks_node(port: int, scope: str):
    """The log's face on the wire: stacks documents AND the routing standard,
    read with the seat's own authority; writes POST back to the floor."""
    from datetime import datetime, timedelta, timezone

    seat_kp, seat_did = lib_seat(scope)

    class _N:
        def __init__(self):
            self.records, self.scope = {}, scope

        def write(self, rec):
            call(port, "POST", "/records", rec)
            self.records[rec["id"]] = dict(rec, received_at=rec["occurred_at"])
            return rec["id"]

        def _distill(self, ids, push=False):
            """The metabolism's hand on the wire (wire-honesty sp2): one
            distillation record, derived_from committed, POSTed home — the
            summarizer is the honest v0 scaffold; the schedule, dials, tap,
            and measured loss are the real machinery."""
            body = {"summary": f"distilled {len(ids)} records at {self.scope}",
                    "count": len(ids), "exchange": "hold",
                    "method": {"model": "deterministic-sim",
                               "rubric": "wire-metabolism-v0"}}
            rec = make_memory(self._me, self._kp, self.scope, body,
                              kind="distillation",
                              tags=["distillation", "metabolism"])
            rec["derived_from"] = list(ids)   # rides unsigned beside tags (0033)
            self.write(rec)
            return {"id": rec["id"]}
    n = _N()
    n.recalls = recalls_load(scope)   # the tap survives the process (sp1)
    token = _ROOT.issue_token(seat_did, "u:demo",
                              [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc) - timedelta(days=365)).strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        r = call(port, "POST", "/retrieve", {
            "query": {"requester": seat_did, "subject": {"cohort": {"scope": scope}},
                      "space": "self", "time": {"from": frm}, "intent": "recall",
                      "budget": {"cost": 8}, "auth": "biscuit-sim"},
            "token": token, "requester_scope": scope})
    except Exception:
        return None, seat_kp, seat_did
    def _keep(src_port, hits, want, home=None):
        for h in hits:
            tags = h.get("tags") or []
            if not want(tags):
                continue
            try:
                body = call(src_port, "GET",
                            f"/records/{urllib.parse.quote(h['ref'], safe='')}/body")
            except Exception:
                continue
            if isinstance(body, dict):
                # the echo guard (0039 sp2): the stacks' own machinery-talk —
                # dispatch choices, asks-about-asking — never answers a world
                # question; real conversations (allen, becky, the markers) do
                asked = str((body.get("parlor") and body.get("asked")) or "")
                if asked.lower().startswith(("ask the stacks", "run the tournament",
                                             "how do you route", "show the",
                                             "the tournament", "what does the "
                                             "universe know")):
                    continue
                n.records[h["ref"]] = {"tags": tags,
                                       "received_at": h.get("occurred_at", ""),
                                       # the true clock rides too — the
                                       # metabolism ages by occurred_at (sp2)
                                       "occurred_at": h.get("occurred_at", ""),
                                       "derived_from": h.get("derived_from") or [],
                                       # provenance rides with the record
                                       # (0053 sp3): whose word, whose floor
                                       "author": h.get("author", ""),
                                       "home": home or scope,
                                       "body": crypto._b64e(crypto.canonical(body))}
    _keep(port, r.get("hits", []),
          lambda t: ("stacks" in t and ("document" in t or "tournament" in t))
          or "routing-standard" in t or "dispatch" in t or "knowledge" in t
          or "distillation" in t or "distillation-dials" in t
          or "metabolism-report" in t)   # the metabolism reads its own past (sp2)
    # THE ROWS MEET THE REAL MEMORY (JB-locked 2026-07-22): the librarian's
    # GATHERED knowledge lives on the universe's floors — a second read brings
    # it into the projection, trust and lineage riding with it
    u_port = universe_port(port)
    if u_port != port:
        try:
            r2 = call(u_port, "POST", "/retrieve", {
                "query": {"requester": seat_did,
                          "subject": {"cohort": {"scope": UNIVERSE_SCOPE}},
                          "space": "self", "time": {"from": frm},
                          "intent": "recall", "budget": {"cost": 8},
                          "auth": "biscuit-sim"},
                "token": token, "requester_scope": UNIVERSE_SCOPE})
            from orreth_sim import canon as _canon
            cand = [h for h in r2.get("hits", [])
                    if "knowledge" in (h.get("tags") or [])
                    or (_canon.class_of({"tags": h.get("tags") or []})
                        .startswith("chronicle-")
                        and "asset" not in (h.get("tags") or [])
                        and "dispatch" not in (h.get("tags") or []))]
            # stratified cap: conversations, markers, and objectives board
            # FIRST — the run-record flood never drowns the human's voice
            pri = lambda h: 0 if any(t in ("parlor", "marker", "objective")
                                     for t in (h.get("tags") or [])) else 1
            cand.sort(key=lambda h: (pri(h), h.get("occurred_at", "")),
                      reverse=False)
            cand.sort(key=lambda h: h.get("occurred_at", ""), reverse=True)
            cand.sort(key=pri)
            _keep(u_port, cand[:120], lambda t: True,
                  home=UNIVERSE_SCOPE)                  # newest 120 — the cap
            # is honest: a standing projection with a rebuild beat is sp3+
        except Exception:
            pass
    # THE DESKS JOIN THE LIBRARY (0053 sp3, JB's strategic law 2026-08-14:
    # "the Librarian is obtainer of knowledge for universe") - every
    # DISCOVERED world's own chronicle flows into the projection unless its
    # manifest opts out (isolate: the risky-experiment door; its memories
    # stay off the universe's shelves by the human's own design). Reports
    # and reflections ride FIRST; the stage flood never drowns them.
    try:
        for _wkey, _wman in CAP_GENESIS.items():
            if _wman.get("isolate"):
                continue                  # opted out - isolation honored
            _wp, _ws = _wman.get("port"), _wman.get("floor")
            if not _wp or not _ws or _wp == port:
                continue
            try:
                _wr = call(_wp, "POST", "/retrieve", {
                    "query": {"requester": seat_did,
                              "subject": {"cohort": {"scope": _ws}},
                              "space": "self", "time": {"from": frm},
                              "intent": "recall", "budget": {"cost": 8},
                              "auth": "biscuit-sim"},
                    "token": token, "requester_scope": _ws})
            except Exception:
                continue                  # a dark or shut-down world skips
            from orreth_sim import canon as _cnd
            _wc = [h for h in _wr.get("hits", [])
                   if _cnd.class_of({"tags": h.get("tags") or []})
                       .startswith("chronicle-")
                   and "asset" not in (h.get("tags") or [])]
            _wpri = lambda h: (0 if any(t in ("report", "reflection")
                                        for t in (h.get("tags") or [])) else 1)
            _wc.sort(key=lambda h: h.get("occurred_at", ""), reverse=True)
            _wc.sort(key=_wpri)
            _keep(_wp, _wc[:60], lambda t: True, home=_ws)  # per-world cap, honest
    except Exception:
        pass
    # the metabolism's ground (wire-honesty sp2): the projection carries what
    # canon.metabolism_beat needs — ONE law, both grounds. undistilled = dialed
    # classes not yet inside any distillation's lineage; the beat metabolizes
    # what the projection can see (the caps above are its honest horizon)
    n._me, n._kp = {"did": seat_did, "scope": scope}, seat_kp
    from orreth_sim import canon as _cnm
    _away: set = set()
    for _r in n.records.values():
        if "distillation" in (_r.get("tags") or []):
            _away.update(_r.get("derived_from") or [])
    _dialed = set((_cnm.dials(n).get("classes") or {}).keys())
    n.undistilled = [rid for rid, _r in n.records.items()
                     if rid not in _away
                     and "distillation" not in (_r.get("tags") or [])
                     and "metabolism-report" not in (_r.get("tags") or [])
                     and _cnm.class_of(_r) in _dialed]
    return n, seat_kp, seat_did


def _leaves(body) -> str:
    """Every string leaf of a record body, joined WHOLE — the self-knowledge
    step reads entire reports (the 2000-char meaning-axis cap blinded the
    quote scan to a stop-loss sentence that lived past it, run 5)."""
    out: list = []

    def walk(v):
        if isinstance(v, str):
            out.append(v)
        elif isinstance(v, dict):
            for x in v.values():
                walk(x)
        elif isinstance(v, list):
            for x in v:
                walk(x)
    walk(body)
    return " ".join(out)


def _ask_self_knowledge(n, q: str) -> tuple[str, str, bool]:
    """THE SELF-KNOWLEDGE STEP (0053 sp3 — the yardstick's find): some parts
    of a question are the MACHINE'S OWN STATE, not corpus text, and some
    references are indirect — both resolve from the machine's own record
    BEFORE retrieval, so the lane never guesses at what it already knows.
    Returns (the query to retrieve with, the truth to speak first, and
    SETTLED — whether the record itself answered, so a weak retrieval must
    stay silent rather than retract a true answer: vera's run-4 find, an
    assert-then-confess reply reads as untrustworthy and IS). All of it is
    discovery data — no world, resident, or symbol is ever baked."""
    import re as _re
    low = (q or "").lower()
    pre, q2, settled = "", q, False
    # (a) the isolation roster — manifest truth, never a retrieval
    if _re.search(r"\bopt(?:ed|s)?[-\s]?out\b|\bisolat(?:ed|ion|e)\b", low):
        iso = [m.get("name", k) for k, m in CAP_GENESIS.items()
               if m.get("isolate")]
        pre += (("the isolation roster, from the manifests themselves: "
                 + ", ".join(iso) + " keep their memories off the universe's "
                 "shelves — their contents are unreadable here by the "
                 "human's own design. ") if iso else
                "no ecosystem currently opts out of sharing; when one does, "
                "its memories stay off the universe's shelves by design, and "
                "this lane will name it without claiming to see inside. ")
        settled = True
    # (b) the ticker ledger — reports carry their symbol; an indirect
    # reference ("the most-walked symbol") resolves by counting the record
    walks: dict = {}
    newest_report = None
    for rid, r in n.records.items():
        tags = r.get("tags") or []
        if "report" not in tags:
            continue
        try:
            body = json.loads(crypto._b64d(r["body"]).decode())
        except Exception:
            continue
        sym = str(body.get("ticker") or "").upper()
        when = r.get("occurred_at", "")
        if sym:
            e = walks.setdefault(sym, {"n": 0, "last": ""})
            e["n"] += 1
            e["last"] = max(e["last"], when)
        if newest_report is None or when > newest_report[1]:
            newest_report = (rid, when, r, sym)
    from orreth_sim import dispatcher as _dsp
    sym = None
    if walks and "comparative" not in _dsp.classify(q) and _re.search(
            r"\bmost[-\s]?(?:walked|recent(?:ly)?(?:\s+walked)?)"
            r"\b[^.?]{0,40}\bsymbol\b|\bmost[-\s]walked\b", low):
        # a comparative ask spans SUBJECTS — resolving it to one symbol
        # poisoned the per-desk question (vera's note, run 3); the
        # resolver stands aside and lets the decomposing row work
        top = sorted(walks.items(), key=lambda x: (-x[1]["n"], x[1]["last"]))[0]
        latest = sorted(walks.items(), key=lambda x: x[1]["last"])[-1]
        sym = (latest if "recent" in low else top)[0]
        cnt = walks[sym]["n"]
        pre += (f"that reference resolves on the record to {sym} "
                f"({cnt} report{'s' if cnt != 1 else ''} on the shelves) — "
                "what follows is what the shelves hold on it. ")
        q2 = f"{q} {sym}"          # the literal joins the ask — lexical
        #                            retrieval bites on the resolved name
    # (b2) the locality sweep — "outside the desk floors" is an attribution
    # question the projection itself answers: whose memory, on whose floor
    if sym and _re.search(r"\b(?:outside|beyond)\b[^.?]{0,30}\bdesk", low):
        desk_floors = {m.get("floor") for m in CAP_GENESIS.values()}
        _machinery = {"dispatch", "memory-standing", "distillation", "asset",
                      "witness", "metabolism-report"}
        found = []
        for rid, r in n.records.items():
            home = r.get("home", "")
            if home in desk_floors:
                continue
            if _machinery & set(r.get("tags") or []):
                continue    # the echo guard reaches the sweep (0039 sp2's
                #             law): the ask machinery's own diary — dispatch
                #             choices, prior standings — never counts as a
                #             MEMORY mentioning the symbol
            try:
                text = _leaves(json.loads(crypto._b64d(r["body"]).decode()))
            except Exception:
                continue
            i = text.upper().find(sym)
            if i >= 0:
                # evidence with TEXTURE — a naked hash reads as invented to
                # a judge who cannot verify it (vera's run-5 suspicion); the
                # matched words themselves ride along
                found.append((rid, home,
                              text[max(0, i - 25):i + 45].strip()))
        if found:
            named = " · ".join(f"“…{exc}…” [{rid[:18]}…] at {home}"
                               for rid, home, exc in found[:3])
            pre += (f"yes — {len(found)} memor"
                    f"{'y' if len(found) == 1 else 'ies'} beyond the desk "
                    f"floors mention {sym}: {named}. ")
        else:
            pre += (f"no memory outside the desk floors mentions {sym} — "
                    "locality holds; the desks' work stays on their own "
                    "ground. ")
        settled = True
    # (b3) the precise fact — a technical term plus a resolved symbol means
    # the fact lives in a KNOWN report: quote its own sentence across walks,
    # never a neighboring paragraph (Q1's ability: precision, not vicinity)
    if sym:
        want_terms = [t for t in _re.findall(r"[a-z]+(?:[-\s][a-z]+)?", low)
                      if "-" in t] + \
            [t for t in _re.findall(r"[a-z]{6,}", low)
             if t not in ("symbol", "walked", "recently", "between",
                          "reports", "records", "current", "mention",
                          "memory", "shelves")]
        quotes = []
        newest_sym = None
        for rid, r in sorted(n.records.items(),
                             key=lambda x: x[1].get("occurred_at", ""),
                             reverse=True):
            if "report" not in (r.get("tags") or []):
                continue
            try:
                body = json.loads(crypto._b64d(r["body"]).decode())
            except Exception:
                continue
            if str(body.get("ticker") or "").upper() != sym:
                continue
            if newest_sym is None:
                newest_sym = (rid, r.get("occurred_at", "")[:10], body)
            text = _leaves(body)             # the WHOLE report, never a cap
            best = None
            # hyphen and space are one breath ("stop-loss" asks, "Stop
            # Loss: 208" answers — run 7's whole stubbornness), and a bold
            # line is a sentence wearing markdown, not scaffolding
            norm = lambda s: _re.sub(r"[-\s]+", " ", s.lower())
            hyph = [norm(t) for t in want_terms if "-" in t]
            plain = [norm(t) for t in want_terms]
            for s in _re.split(r"(?<=[.;])\s+|\n+", text):
                s = s.strip().lstrip("*•# ").strip()
                if len(s) < 12 or s.startswith(("---", "|")):
                    continue                 # true scaffolding only
                ns = norm(s)
                if hyph and any(t in ns for t in hyph):
                    best = s                 # the technical term wins outright
                    break
                if best is None and any(t in ns for t in plain):
                    best = s
            if best:
                quotes.append((r.get("occurred_at", "")[:10],
                               best[:180], rid))
        if quotes:
            pre += ("from the reports themselves: " + " · ".join(
                f"walk {when}: “{s}” [{rid[:18]}…]"
                for when, s, rid in quotes[:2]) + ". ")
            settled = True
        elif newest_sym is not None:
            # no sentence carried the ask's terms — the report's own
            # STRUCTURED stance answers rather than another symbol's
            # nearest-noise (vera's run-5 find: EBAY resolved, PYPL served)
            rid, when, body = newest_sym
            stance = " — ".join(
                str(body.get(k))[:170] for k in
                ("rating", "executive_summary", "investment_thesis")
                if body.get(k))
            if stance:
                pre += (f"the newest {sym} report ({when}) holds: "
                        f"{stance} [{rid[:18]}…]. ")
                settled = True
    # (c) provenance — the newest report's own metadata, read, not retrieved
    if newest_report and _re.search(
            r"\bwho\s+(?:wrote|authored)\b|\bon which floor\b|"
            r"\bwhen was\b[^.?]{0,40}\bwritten\b", low):
        rid, when, r, sym = newest_report
        home = r.get("home", "?")
        resident = next((m.get("resident", "") for m in CAP_GENESIS.values()
                         if m.get("floor") == home), "")
        who = resident or (r.get("author", "")[:24] + "…")
        pre += (f"the most recent desk report{f' ({sym})' if sym else ''} was "
                f"written by {who} on {home} at {when} [{rid[:18]}…]. ")
        settled = True
    return q2, pre, settled


def wire_stacks_ask(port: int, scope: str, q: str, *, origin: str = "") -> str:
    """The ask path, whole (0038 sp1+sp2): the DISPATCHER routes first — its
    choice a signed record, an unbuilt row falling to the baseline loudly —
    then the chosen row's projection regrows from the log and answers with
    citations. Since 0053 sp3: the self-knowledge step resolves machine-state
    and indirect references BEFORE retrieval, and the reply speaks ANSWER
    FIRST — the routing note rides at the tail, because a human asked a
    question, not for the machinery's diary."""
    from orreth_sim import dispatcher, stacks, tournament
    n, seat_kp, seat_did = _stacks_node(port, scope)
    if n is None:
        return "the stacks are unreachable — try again on the next beat"
    me = {"did": seat_did, "scope": scope}
    dispatcher.plant_standard(n, me, seat_kp)     # genesis once; shelf from then on
    from orreth_sim import canon as _cn
    _cn.plant_registry(n, me, seat_kp)            # the two books stand (0039 sp1)
    _cn.plant_dials(n, me, seat_kp)               # the metabolism's dials (sp3)
    # ALL SEVEN rows stand on the wire — v2's word ("built grows to all seven")
    # finally honored here; caught live 2026-07-25 when the freshly-promoted
    # «router» default met a four-row door
    # THE EXPERIMENT (0043 sp4): one running split may stand on this floor —
    # the unit's hash picks the arm, the arm's variant stands as the
    # PROJECTION's head for this ask alone (the shelf untouched), and the
    # answer wears the arm's tag for the standings' log join
    arm = None
    exp = running_experiment(scope)
    if exp:
        from orreth_sim import experiment as exp_lib
        ename, e = exp
        label = exp_lib.assign({"share": e["share"]}, q)
        av = e["arms"][label]
        vrec = n.records.get(av["variant"])
        if vrec is not None:
            n.records["synthetic:arm-head"] = dict(
                vrec, tags=["asset", "routing-standard"],
                received_at="9999-12-31T00:00:00Z")   # in-memory only — never written
            arm = {"label": label, "machine": av["machine"],
                   "tag": f"arm:{av['machine'].split(':', 1)[-1][:12]}",
                   "of": e["record"]}
    q2, pre, settled = _ask_self_knowledge(n, q)  # state resolves before retrieval
    d = dispatcher.dispatch(n, me, seat_kp, q2, origin=origin,
                            built=list(tournament.ALL_RETRIEVERS))
    n.records.pop(d["record"], None)   # an ask never cites its OWN routing —
    # the choice persists on the wire; it just doesn't answer itself
    a = tournament.answer_as(n, d["flavor"], q2)
    recalls_save(scope, n)             # what this ask warmed, kept (sp1)
    attest_note(port, scope, n)        # what this ask LOADED, noted (0041 sp2)
    if arm:                            # the work wears its arm (0043 sp4, law 4)
        wk = make_memory(me, seat_kp, scope,
                         {"outcome": {"intention": "stacks-ask",
                                      "of": arm["of"], "status": "done",
                                      "answer": a["answer"][:400],
                                      "cycles": 1}},
                         kind="episodic",
                         tags=["intention-outcome", "stacks-answer",
                               arm["tag"]])
        try:
            call(port, "POST", "/records", wk)
        except Exception:
            pass
    cites = " · ".join(f"{c['doc']} [{c['ref'][:18]}…] {c['score']}"
                       for c in a["citations"][:3])
    ans_txt = a["answer"]
    if settled and a.get("confessed"):
        # the record itself answered; a weak retrieval must not RETRACT a
        # true answer (vera's run-4 find: assert-then-confess reads as
        # untrustworthy and is) — the shelves simply say they add nothing
        ans_txt = "the shelves add nothing stronger — the record itself answered above"
        cites = ""
    # ANSWER FIRST (0053 sp3 — vera dinged replies that led with the
    # machinery's diary): what the machine knows of itself, then the
    # retrieved answer with citations, then the routing note at the tail —
    # and a SETTLED reply carries no routing note at all: "no shape matched"
    # under a true provenance line read as a retraction (vera, run 5); the
    # dispatch record still stands on the wire for the walkers
    return (pre + ans_txt
            + (f" — citations: {cites}" if cites else "")
            + ("" if settled else
               " · " + sentence(port, "note-dispatcher", flavor=d["flavor"],
                                why=d["why"], choice=d["record"][:18]))
            + (f" · 🧪 arm «{arm['label']}» "
               f"[{arm['machine'].split(':', 1)[-1][:12]}] served" if arm else ""))


def wire_stacks_tournament(port: int, scope: str, q: str = "") -> str:
    """THE TOURNAMENT on the wire (0038 sp4 — and the demo JB asked for):
    one question through all seven rows, graded, ranked, the result landed as
    a signed record — and the first PROMOTION staged at the human's gate as a
    proper improvement, never enacted by the machine."""
    from orreth_sim import tournament
    n, seat_kp, seat_did = _stacks_node(port, scope)
    if n is None:
        return "the stacks are unreachable — try again on the next beat"
    questions = [q] if q else [
        "how are rammed earth walls connected to the seasons?",
        "what exactly protects walls from rain?",
        "compare rammed earth and lime plaster"]
    r = tournament.run(n, questions)
    recalls_save(scope, n)             # seven rows' worth of warmth, kept (sp1)
    me = {"did": seat_did, "scope": scope}
    ev = make_memory(me, seat_kp, scope,
                     {"stacks_tournament": {"standings": r["standings"],
                                            "champion": r["champion"],
                                            "rounds": len(r["rounds"])}},
                     kind="episodic", tags=["stacks", "tournament"])
    n.write(ev)
    p = tournament.promotion_proposal(r)
    try:
        board_txt = "\n".join(f"  {s['flavor']}: {s['mean']:.2f} over {s['n']}"
                              + (f" · ⚑ {'; '.join(s['floors'])}" if s["floors"]
                                 else "") for s in r["standings"])
        call(universe_port(port), "POST", "/requests",
             {"kind": "improvement", "standard_v2": dict(p, version="2"),
              # the card carries its evidence — the adoption names it, so a
              # promoted standard is never an orphan on the shelf
              "proposal_ref": ev["id"],
              "text": f"THE FIRST PROMOTION — routing-standard v2 from the "
                      f"tournament: default → «{p['default']}», all seven rows "
                      "built. the tournament argues, you sign (0012)",
              "package": f"STANDINGS ({len(r['rounds'])} round(s)):\n{board_txt}"
                         f"\nCHANGE: default naive → {p['default']}; built "
                         f"grows to all seven.\nROLLBACK: v1 stands behind it, "
                         "versioned as ever."})
    except Exception:
        pass
    board = " · ".join(
        f"{s['flavor']} {s['mean']:.2f}"
        + (f" ⚑{len(s['floors'])}" if s["floors"] else "")
        for s in r["standings"])
    win = "; ".join(f"“{rd['question'][:40]}…” → {rd['winner']}"
                    for rd in r["rounds"])
    return (f"🏁 THE TOURNAMENT — {len(r['rounds'])} round(s), seven rows each: "
            f"{board}. round winners: {win}. champion: «{r['champion']}». "
            "the standings are on the record; the first PROMOTION (standard v2, "
            "default → champion) waits at your gate — the tournament argues, "
            "you sign (0012).")


def on_standard_promotion(port: int, scope: str, r: dict, *,
                          approved: bool = False, declined: bool = False) -> None:
    """The first promotion's gate (0038 sp4 — repaired after JB's approval had
    nowhere to land): staged with the standings readable; the human's word
    ADOPTS routing-standard v2 as a real versioned asset at the rag seat —
    v1 standing behind it, never erased. Declined waits for fatter evidence."""
    from orreth_sim import improver
    if declined:
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"declined": True,
                         "reply": "the promotion waits for fatter evidence — "
                                  "shelve more, run more tournaments; the "
                                  "record keeps that you chose"}})
        print("  ↳ standard v2 declined — the tournament argues again later")
        return
    if not approved:
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "staged",
              "result": {"package_text": r.get("package", ""),
                         "note": "the first promotion waits for you (0012)"}})
        print("  ↳ standard v2 staged — the gate waits")
        return
    rag_port, rag_scope = next(
        ((p, s) for p, s in FLOOR_SCOPES.items()
         if s.endswith("/e:rag/f:naive")), (None, None))
    if rag_port is None:
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"reply": "the rag floor is dark — v2 cannot land; "
                                  "regrow the floor and run the tournament again"}})
        return
    seat_kp, seat_did = lib_seat(rag_scope)
    v2 = dict(r.get("standard_v2") or {})
    v2.pop("evidence", None)
    # lineage: the adoption names the tournament's standings record (legacy
    # cards without a ref plant as before — old resolved words stay honest)
    pref = str(r.get("proposal_ref") or "") or None
    asset = improver.make_asset({"did": seat_did, "scope": rag_scope}, seat_kp,
                                rag_scope, name="routing-standard", profile=v2,
                                adopted_from=pref,
                                derived_from=[pref] if pref else None)
    try:
        call(rag_port, "POST", "/records", asset)
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"reply": f"routing-standard v2 ADOPTED on your word — "
                                  f"default «{v2.get('default')}», all seven "
                                  "rows built; v1 stands behind it, versioned "
                                  f"as ever [{asset['id'][:18]}…]",
                         "resolved_at": NOW()}})
        print(f"  ↳ STANDARD v2 ADOPTED — default «{v2.get('default')}» "
              f"[{asset['id'][:18]}…]")
    except Exception as e:
        print(f"    (v2 adoption failed: {e})")


MENTEE_MIND = "anthropic/claude-haiku-4-5-20251001"  # low · the universe's stable
JUDGE_MIND = "anthropic/claude-sonnet-5"             # medium · f:prod's stable


def _live_graduation(n2, u_port: int, k: int = 3):
    """THE LIVE JUDGE (wire-honesty sp3; deals locked by JB 2026-07-25): the
    MENTEE (haiku, low class, the universe's stable) executes the craft on the
    floor's REAL records; the JUDGE (sonnet-5, medium class, f:prod's stable —
    another floor's mind, judge ≠ mentee, genuine independence) scores each run
    against the rubric, strict JSON. Every token authorized and metered under
    the plane. Returns (scores, judge_notes, usd_total, label); None when the
    ground is missing so the caller falls back to the honestly-labeled sim
    judge. A partial run returns partial — the refusal path stays real."""
    import re as _re
    from orreth_sim import stacks as _st
    prod_port = next((p for p, s in FLOOR_SCOPES.items()
                      if s.endswith("/e:cloud/f:prod")), None)
    if prod_port is None:
        return None
    try:
        chunks = (_st.project(n2) or {}).get("chunks") or []
    except Exception:
        chunks = []
    lines = []
    for c in chunks:
        t = str(c.get("text", ""))[:200].strip().replace("\n", " ")
        if t:
            lines.append(f"· [{c.get('doc', '?')}] {t}")
        if len(lines) >= 12:
            break
    if len(lines) < 3:
        return None                    # too little ground for an honest canary
    corpus = "\n".join(lines)
    label = (f"LIVE — mentee {MENTEE_MIND.split('/')[-1]} · "
             f"judge {JUDGE_MIND.split('/')[-1]}, another floor's mind")
    scores, notes, usd = [], [], 0.0
    for i in range(k):
        m = governed_thought(
            u_port, MENTEE_MIND, "low",
            craft_render(craft(u_port, "graduation-mentee"),
                         skill="summarize a floor's week",
                         steps="gather the week's records · distill by score · cite",
                         corpus=corpus), max_tokens=300)
        if m is None:
            break
        usd += m["usd"]
        j = governed_thought(
            prod_port, JUDGE_MIND, "medium",
            craft_render(craft(u_port, "graduation-judge"),
                         skill="summarize a floor's week",
                         corpus=corpus, summary=m["text"]), max_tokens=200)
        if j is None:
            break
        usd += j["usd"]
        sc = None
        try:
            got = json.loads(_re.search(r"\{.*\}", j["text"], _re.S).group(0))
            sc = max(0.0, min(1.0, float(got.get("score", 0.0))))
            why = str(got.get("why", ""))[:120]
        except Exception:
            # a truncated reply may still carry its number — read it first
            m2 = _re.search(r'"score"\s*:\s*([0-9.]+)', j["text"])
            if m2:
                sc = max(0.0, min(1.0, float(m2.group(1))))
                why = "the judge's sentence was cut short; the score survived"
        if sc is None:
            # JUDGE-FAILURE IS NOT MENTEE-FAILURE (JB's ceremony caught it,
            # 2026-07-25): an unjudgeable run is VOIDED — named, never scored.
            # The rubric still demands n JUDGED runs, so voids cost the
            # ceremony honestly without slandering the mentee.
            notes.append(f"run {i + 1}: the judge's verdict was lost — "
                         "voided, not scored")
            print(f"  ↳ live canary {i + 1}/{k}: the mentee spoke "
                  f"({m['tokens']} tok) — the judge's verdict was LOST; voided")
            continue
        scores.append(sc)
        notes.append(f"“{why}” ({sc:.2f})")
        print(f"  ↳ live canary {i + 1}/{k}: the mentee spoke "
              f"({m['tokens']} tok), the judge scored {sc:.2f}")
    if not scores:
        return None
    return scores, notes, usd, label


# ------------------------------------------------------------- 0041 · the epoch
EPOCH_EVERY = int(os.environ.get("ORRETH_EPOCH_EVERY", "300"))
_EPOCH_LAST = 0.0


def _epoch_nest(scope: str) -> Path:
    nest = HOME / "epochs" / scope.replace("/", "~")
    nest.mkdir(parents=True, exist_ok=True)
    return nest / "head.json"


def _machine_fingerprint(port: int, scope: str) -> dict:
    """The scope's machine, as content (0041 §1, v1 scope as locked): active
    Canon asset heads + the plane's edition + worldline POINTERS — the farm
    and stable keep their own books; the epoch cites where they stood."""
    heads: dict = {}
    for ref, body, dl, tags in wire_assets(port, "asset"):
        name = next((t for t in tags if t != "asset"), None)
        if name:
            heads[name] = ref        # rows ride oldest-first — last write is head
    try:
        plane = {"version": call(port, "GET", "/health").get("version", "?")}
    except Exception:
        plane = {"version": "unreachable"}
    worldlines = {"farm": crypto.content_hash(ledger_load(scope)),
                  "stable": crypto.content_hash(stable_ledger_load(scope))}
    fp = {"assets": heads, "plane": plane, "worldlines": worldlines}
    # 0045 sp3 — the machine's name covers its own FIRMWARE: the Canon
    # extraction made the driving words records; the fingerprint now cites
    # their heads, so a firmware change moves the name (Canon = release)
    if scope == UNIVERSE_SCOPE:
        fw: dict = {}
        for ref, b, _, _ in wire_assets(port, "firmware"):
            f = (b or {}).get("firmware") or {}
            if f.get("name"):
                fw[f["name"]] = ref
        if fw:
            fp["firmware"] = fw
    return fp


def _cut_epoch(port: int, scope: str, fp: dict) -> str | None:
    """Cut only when the fingerprint moved (0041 §2 — a noticing, never a
    ceremony). Returns the standing epoch id, fresh or held."""
    nest = _epoch_nest(scope)
    old: dict = {}
    try:
        old = json.loads(nest.read_text()) if nest.exists() else {}
    except Exception:
        pass
    fp_hash = crypto.content_hash(fp)
    if old.get("fp_hash") == fp_hash:
        return old.get("id")                     # the machine holds — no news
    changed: dict = {}
    for zone in ("assets", "plane", "worldlines", "floors"):
        a = (old.get("fp") or {}).get(zone) or {}
        b = fp.get(zone) or {}
        for k in sorted(set(a) | set(b)):
            if a.get(k) != b.get(k):
                changed[f"{zone}.{k}"] = {"from": a.get(k), "to": b.get(k)}
    seat_kp, seat_did = lib_seat(scope)
    reverted = _PENDING_REVERT.pop(scope, None)   # a revert just landed here?
    body = {"canon_epoch": {"scope": scope, "organ": "governance",
                            "parent": old.get("id"),
                            "rollback_parent": old.get("id"),
                            **({"revert_of": reverted} if reverted else {}),
                            **fp, "changed": changed, "cut_at": NOW()}}
    rec = make_memory({"did": seat_did, "scope": scope}, seat_kp, scope, body,
                      kind="semantic", tags=["canon-epoch"])
    try:
        call(port, "POST", "/records", rec)
    except Exception:
        if reverted:
            _PENDING_REVERT[scope] = reverted    # the citation survives the refusal
        return old.get("id")                     # the wire refused — hold the head
    nest.write_text(json.dumps({"id": rec["id"], "fp_hash": fp_hash,
                                "fp": fp, "at": NOW()}))
    print(f"  ↳ the epoch turns at {scope}: "
          + (f"{len(changed)} change(s) " if old.get("id")
             else "the machine takes its first name ")
          + f"[{rec['id'][:18]}…]")
    # drift class 2 (0041 sp3): a standing chain moved its Canon with no
    # adoption near it — genesis cuts never accuse (no chain stood before)
    if old.get("id") and any(k.startswith("assets.") for k in changed) \
            and not _recent_gate_word(port):
        _stage_drift(port, scope, changed,
                     "the Canon moved with no adoption behind it")
    return rec["id"]


# ------------------------------------------------ 0041 sp3 · drift is news
LAG_WINDOW = int(os.environ.get("ORRETH_LAG_WINDOW", "900"))
_LAG: dict = {}          # scope → {"t": first_seen, "staged": bool}


_ADOPTION_KINDS = ("release",                 # Canon change = epoch release (0045 sp3)
                   "improvement", "estate-adopt", "field-join", "drift",
                   "craft-edit",  # the one-motion door: the request IS the
                   #  human's word (0045 sp2) — learned 0050 sp2 when the
                   #  plain-speech siblings drew the honest accusation
                   "capability-verb",  # retire/reinstate plant manifest
                   #  siblings behind a staged human word (0055) — learned
                   #  2026-08-13 when the retire proof drew the accusation
                   "experiment")   # 0043 sp4's promotion IS an adoption — the
#   first live rollout taught the watchdog its missing word (JB left the
#   honest false accusation on record, 2026-07-30)
#  a resolved drift is a human's word on the Canon (revert OR leave-it) — the
#  restored/kept head that follows it is adopted, not fresh drift (0041 sp4)
_PENDING_REVERT: dict = {}   # scope → the revert the next epoch cut must cite
_REVERT_WAITS: set = set()   # scopes whose approved revert waits for a dark floor


def _recent_gate_word(port: int) -> bool:
    """A CANON ADOPTION resolved near the change (0041 sp3, v1 named coarse in
    the dive): only the gates that actually move Canon assets count —
    improvement (routing standards, dials, skills, prompts), estate-adopt,
    field-join, a human's word on a drift card. A parlor ask is NOT an
    adoption, so a busy universe never hides drift behind ordinary
    conversation. The word is dated by `result.resolved_at` — the moment it
    LANDED — never by the card's submission second: a gate is allowed to wait
    for its human (the req-322 lesson, 2026-07-25 — dating the word by
    submission turned one slow click into a self-accusing loop that re-adopted
    the very drift it was born to catch). Cards from before the stamp fall
    back to the submission second. When the gate is unreadable we NEVER accuse
    in the dark — the finer asset-name ↔ request match is future work,
    flagged, not faked."""
    try:
        items = call(universe_port(port), "GET", "/requests")
        items = items if isinstance(items, list) else (
            items.get("requests") or items.get("items") or [])
    except Exception:
        return True
    now = time.time()
    for r in items:
        if not isinstance(r, dict) or r.get("status") != "done":
            continue
        if r.get("kind") not in _ADOPTION_KINDS:
            continue
        ts = None
        landed = (r.get("result") or {}).get("resolved_at")
        if landed:
            try:
                from datetime import datetime
                ts = datetime.fromisoformat(
                    str(landed).replace("Z", "+00:00")).timestamp()
            except Exception:
                ts = None
        if ts is None:
            try:
                ts = int(str(r.get("id", "")).rsplit("-", 1)[1])
            except Exception:
                continue
        if now - ts < 2 * EPOCH_EVERY:
            return True
    return False


_LAG_NOTED: dict = {}   # scope → last lag-note time (JB's find: notes, throttled)


def _stage_drift(port: int, scope: str, changed: dict, why: str) -> None:
    """DRIFT stages a finding (0041 §4, locked: detection wears no levers) —
    the diff rides the card; the human's gate decides. The `from` head of each
    changed asset IS the pre-drift head: it rides the card as the revert target
    (sp4), so the human's yes restores the signed machine without walking a
    single chain."""
    diff = "\n".join(
        f"  {k}: {str((v or {}).get('from'))[:24]} → {str((v or {}).get('to'))[:24]}"
        for k, v in list(changed.items())[:8])
    restore = {k.split(".", 1)[1]: (v or {}).get("from")
               for k, v in changed.items()
               if k.startswith("assets.") and (v or {}).get("from")}
    # JB's find (2026-08-12, drowning in his own inbox): a lag with NOTHING
    # to restore asks the human NOTHING — it is a NOTE, never a lever, and
    # at most one per scope per hour. Only true drift (a restore exists)
    # stages at the gate; 0041's lock — detection wears no levers — holds
    # for the finding that actually needs a word.
    is_lag = not restore
    if is_lag:
        last = _LAG_NOTED.get(scope, 0.0)
        if time.time() - last < 3600:
            return                        # the hour's note already stands
        _LAG_NOTED[scope] = time.time()
    try:
        card = call(universe_port(port), "POST", "/requests", {
            "kind": "drift", "scope": scope, "restore": restore,
            "text": f"DRIFT at {scope} — {why}",
            "package": f"THE DIFF:\n{diff}\n"
                       "No adoption stood behind this change (0041 sp3). "
                       + ("Revert restores the signed machine as a new sibling "
                          "(nothing deleted); leaving it keeps the change and "
                          "the finding on record."
                          if restore else
                          "This is an attestation lag — it converges when the "
                          "point next loads; nothing to restore.")})
        if is_lag:
            call(universe_port(port), "POST", "/requests/resolve",
                 {"id": card["id"], "status": "done",
                  "result": {"reply": "a note for the record — the lag "
                                      "converges on its own; nothing was "
                                      "asked of you"}})
            print(f"  ↳ lag NOTED at {scope}: {why} — no word asked")
        else:
            print(f"  ↳ DRIFT staged at {scope}: {why} — the gate holds the diff")
    except Exception as e:
        print(f"    (drift staging stumbled: {e})")


def _reconcile(scope: str) -> None:
    """LAG vs convergence (0041 §4): the point swearing under an older epoch
    is amber and expected to converge; a lag that will not converge inside
    its window gets loud at the gate."""
    try:
        declared = json.loads(_epoch_nest(scope).read_text()).get("id")
        att = json.loads(_attest_nest(scope).read_text())
    except Exception:
        return
    sworn = att.get("epoch")
    if not declared or not sworn:
        return
    if sworn == declared:
        if scope in _LAG:
            _LAG.pop(scope, None)
            print(f"  ↳ the lag converged at {scope} — the point swears "
                  "under the standing epoch")
        return
    st = _LAG.setdefault(scope, {"t": time.time(), "staged": False})
    age = time.time() - st["t"]
    if age < LAG_WINDOW:
        print(f"  ↳ the point LAGS at {scope}: sworn [{str(sworn)[7:15]}…] "
              f"vs law [{str(declared)[7:15]}…] — amber, converging")
    elif not st["staged"]:
        st["staged"] = True
        port = next((p for p, s in FLOOR_SCOPES.items() if s == scope), None)
        if port:
            _stage_drift(port, scope,
                         {"attested.epoch": {"from": sworn, "to": declared}},
                         f"the point's oath would not converge in "
                         f"{LAG_WINDOW}s")


def epoch_beat() -> None:
    """THE CUT on the beat (0041 sp1; locked 2026-07-25: beat-detected diff,
    per-floor epochs + a universe roll-up citing the floors' heads). Which
    machine is this floor right now? — answered by a hash, on a chain."""
    global _EPOCH_LAST
    if time.time() - _EPOCH_LAST < EPOCH_EVERY:
        return
    if not FLOOR_SCOPES:
        return
    _EPOCH_LAST = time.time()
    u_port, floor_heads = None, {}
    for port, scope in sorted(FLOOR_SCOPES.items()):
        if scope == UNIVERSE_SCOPE:
            u_port = port
            continue
        try:
            eid = _cut_epoch(port, scope, _machine_fingerprint(port, scope))
            if eid:
                floor_heads[scope] = eid
            _reconcile(scope)                # lag vs law, every beat (sp3)
        except Exception:
            continue
    if u_port is None:
        return
    try:
        fp = _machine_fingerprint(u_port, UNIVERSE_SCOPE)
        fp["floors"] = floor_heads           # the roll-up cites the floors' heads
        _cut_epoch(u_port, UNIVERSE_SCOPE, fp)
        _reconcile(UNIVERSE_SCOPE)
    except Exception:
        pass


# --------------------------------------------------- 0041 sp2 · the attestation
ATTEST_EVERY = int(os.environ.get("ORRETH_ATTEST_EVERY", "21600"))  # ~6h, locked
_LOADED: dict = {}      # scope → {"port", "loaded": {name: head}, "at"} — what
#                         the organs ACTUALLY resolved at their standard doors


def attest_note(port: int, scope: str, node) -> None:
    """The loading, noticed (0041 §3): whenever an organ acts through the
    projection — the dispatcher routes, the metabolism turns, a ceremony runs —
    the heads it ACTUALLY held are noted here. The Canon declaring v2 makes
    nothing law; loading it does."""
    heads: dict = {}
    for rid, r in node.records.items():
        tags = r.get("tags") or []
        if "asset" not in tags:
            continue
        name = next((t for t in tags if t != "asset"), None)
        if not name:
            continue
        held = heads.get(name)
        if held is None or (r.get("received_at", "") >
                            node.records.get(held, {}).get("received_at", "")):
            heads[name] = rid
    if heads:
        _LOADED[scope] = {"port": port, "loaded": heads, "at": NOW()}


def _attest_nest(scope: str) -> Path:
    nest = HOME / "epochs" / scope.replace("/", "~")
    nest.mkdir(parents=True, exist_ok=True)
    return nest / "attest.json"


def attest_beat() -> None:
    """THE ATTESTATION on the beat (0041 sp2; locked: on change + a slow
    standing re-attest, so a silent point becomes VISIBLY silent). Each record
    carries the epoch this point believes governs it AND the heads it truly
    loaded — sp3's reconcile reads the gap between them."""
    for scope, seen in list(_LOADED.items()):
        try:
            nest = _attest_nest(scope)
            last: dict = {}
            try:
                last = json.loads(nest.read_text()) if nest.exists() else {}
            except Exception:
                pass
            loaded_hash = crypto.content_hash(seen["loaded"])
            fresh = last.get("loaded_hash") == loaded_hash
            recent = False
            try:
                from datetime import datetime, timezone
                at = datetime.fromisoformat(
                    str(last.get("at", "")).replace("Z", "+00:00"))
                recent = ((datetime.now(timezone.utc) - at).total_seconds()
                          < ATTEST_EVERY)
            except Exception:
                pass
            if fresh and recent:
                continue                    # unchanged and young — diff-quiet
            declared = None
            try:
                declared = json.loads(
                    _epoch_nest(scope).read_text()).get("id")
            except Exception:
                pass
            port = seen["port"]
            seat_kp, seat_did = lib_seat(scope)
            body = {"attestation": {
                "scope": scope, "point": "console-worker",
                "point_code": os.environ.get("ORRETH_VERSION", "dev"),
                "epoch": declared, "loaded": seen["loaded"],
                "at": NOW()}}
            rec = make_memory({"did": seat_did, "scope": scope}, seat_kp,
                              scope, body, kind="semantic",
                              tags=["attestation"])
            call(port, "POST", "/records", rec)
            nest.write_text(json.dumps({"loaded_hash": loaded_hash,
                                        "loaded": seen["loaded"],
                                        "at": NOW(), "id": rec["id"],
                                        "epoch": declared}))
            why = "the loading changed" if not fresh else "the standing word"
            print(f"  ↳ the point attests at {scope}: "
                  f"{len(seen['loaded'])} head(s) loaded — {why} "
                  f"[{rec['id'][:18]}…]")
        except Exception:
            continue


# ------------------------------------------- 0042 sp3 · the publish deed
DEED_SITE = "https://demo.orreth.ai"


def _deed_rec(author_kp, author_did: str, scope: str, role: str,
              body: dict) -> dict:
    """One family record, the sim's grammar exactly (0042 §2): body under the
    role's key, tags ["deed", role] — one walk, either ground."""
    return make_memory({"did": author_did, "scope": scope}, author_kp, scope,
                       {role: body}, kind="episodic", tags=["deed", role])


def _site_bucket() -> str | None:
    out, err = _aws_cli(["cloudformation", "list-stack-resources",
                         "--stack-name", "OrrethDemoStack",
                         "--query", "StackResourceSummaries[?ResourceType=="
                                    "'AWS::S3::Bucket'].PhysicalResourceId"])
    return out[0] if isinstance(out, list) and out else None


def on_publish(port: int, scope: str, r: dict, *,
               approved: bool = False, declined: bool = False) -> None:
    """THE SECOND CLASS (0042 sp3): outbound-publish, T2 witnessed. The card
    stages with the artifact pinned; the human's word is the authorization;
    allen's seat attempts ONE gated write through the toolroom's hand (the
    0037 read-only posture opens exactly this far, exactly here); the
    LIBRARIAN's seat — a different self — fetches back through the public
    door and the hashes speak. A clean world closes; a swapped one stages the
    unpublish as ANOTHER publish card walking this same family (the
    compensating deed, priced). Ceremony above a whisper, receipts verbatim,
    trusted never."""
    art = r.get("artifact") or "first-deed.json"
    content = r.get("content") or ""
    comp = bool(r.get("comp"))
    verify = bool(r.get("verify"))     # re-observe a standing deed — no hand moves
    if declined:
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"reply": "the word was no — nothing left the universe"}})
        return
    if not approved:
        seat_kp, seat_did = lib_seat(UNIVERSE_SCOPE)
        intent = _deed_rec(ALLEN, ALLEN_DID, UNIVERSE_SCOPE, "intent",
                           {"effect": "outbound-publish",
                            "change": ("unpublish " if comp else
                                       "verify " if verify else "publish ")
                                      + f"/deeds/{art}",
                            "objective": r.get("text", "")[:140], "at": NOW()})
        call(port, "POST", "/records", intent)
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "staged",
              "result": {"package_text":
                         (f"UNPUBLISH /deeds/{art} — the walk-back of a deed "
                          "whose world went wrong."
                          if comp else
                          f"VERIFY /deeds/{art} — re-observe the standing deed "
                          "through the public door; no hand moves, the hashes "
                          "speak, a wrong world stages its walk-back."
                          if verify else
                          f"PUBLISH /deeds/{art} to {DEED_SITE} — T2 witnessed "
                          "(0042): your word authorizes, allen attempts under "
                          "the standing epoch, the librarian's seat fetches it "
                          "back through the public door, and the hashes decide. "
                          "Nothing moves without you."),
                         "deed": intent["id"],
                         "note": "the intent stands on the record"}})
        print(f"  ↳ publish staged — the gate holds /deeds/{art} ({r['id']})")
        return
    # ------------------------------------------------ the walk, on your word
    seat_kp, seat_did = lib_seat(UNIVERSE_SCOPE)
    deed_id = ((r.get("result") or {}).get("deed")) or "?"
    fail = lambda why: call(port, "POST", "/requests/resolve",
                            {"id": r["id"], "status": "done",
                             "result": {"reply": f"the walk stopped honestly — {why}",
                                        "resolved_at": NOW()}})
    epoch = None
    try:
        epoch = json.loads(_epoch_nest(UNIVERSE_SCOPE).read_text()).get("id")
    except Exception:
        pass
    if not epoch:
        return fail("no epoch stands — the attempt names the machine (0041) or it floats free")
    bucket = _site_bucket()
    if not bucket:
        return fail("the estate would not name the site bucket")
    key = crypto.content_hash({"artifact": art, "content": content})
    auth = _deed_rec(seat_kp, seat_did, UNIVERSE_SCOPE, "authorization",
                     {"deed": deed_id, "authority": f"the human's word at {r['id']}",
                      "budget": 1.0, "window_s": 3600, "key": key, "at": NOW()})
    call(port, "POST", "/records", auth)
    if verify:
        out, err = "no hand moved — observation only (0042 sp4)", None
    elif comp:
        out, err = _aws_cli(["s3", "rm", f"s3://{bucket}/deeds/{art}"], raw=True)
    else:
        tmp = HOME / "tmp" / art
        tmp.parent.mkdir(parents=True, exist_ok=True)
        tmp.write_text(content)
        out, err = _aws_cli(["s3", "cp", str(tmp), f"s3://{bucket}/deeds/{art}",
                             "--content-type", "application/json",
                             "--cache-control", "no-cache"], raw=True)
    attempt = _deed_rec(ALLEN, ALLEN_DID, UNIVERSE_SCOPE, "attempt",
                        {"deed": deed_id, "key": key, "epoch": epoch,
                         "manifests": {"bucket": bucket, "path": f"deeds/{art}",
                                       "comp": comp, "verify": verify},
                         "at": NOW()})
    call(port, "POST", "/records", attempt)
    if err:
        return fail(f"the hand was refused: {err[:140]}")
    call(port, "POST", "/records",
         _deed_rec(ALLEN, ALLEN_DID, UNIVERSE_SCOPE, "receipt",
                   {"deed": deed_id, "acknowledged": {"cli": (out or "ok")[:200]},
                    "at": NOW()}))
    fetched_hash, status = None, "unreachable"
    for _ in range(3):                     # the world settles, briefly (class dial)
        try:
            with urllib.request.urlopen(f"{DEED_SITE}/deeds/{art}",
                                        timeout=8) as resp:
                fetched_hash = crypto.content_hash(
                    {"artifact": art, "content": resp.read().decode()})
                status = "found"
                break
        except Exception as e:
            status = str(e)[:60]
            time.sleep(4)
    call(port, "POST", "/records",
         _deed_rec(seat_kp, seat_did, UNIVERSE_SCOPE, "observation",
                   {"deed": deed_id, "found": {"status": status,
                                               "hash": fetched_hash}, "at": NOW()}))
    holds = (status != "found") if comp else (fetched_hash == key)
    recon = {"deed": deed_id, "holds": holds,
             "expected": ("absent" if comp else key),
             "observed": {"status": status, "hash": fetched_hash}, "at": NOW()}
    if not holds and not comp:
        recon["staged"] = {"compensation": "stage the unpublish at the gate",
                           "note": "staged, never enacted (0042 §5, locked)"}
    call(port, "POST", "/records",
         _deed_rec(seat_kp, seat_did, UNIVERSE_SCOPE, "reconciliation", recon))
    if holds:
        call(port, "POST", "/records",
             _deed_rec(ALLEN, ALLEN_DID, UNIVERSE_SCOPE, "closure",
                       {"deed": deed_id, "holds": True,
                        "uncertainty": "the fetch-back seat is separated, not "
                                       "independent (0042 §4)", "at": NOW()}))
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"reply": ("UNPUBLISHED on your word — the public door "
                                   "no longer answers, the family closed."
                                   if comp else
                                   f"VERIFIED — /deeds/{art} still is what the "
                                   "deed swore; the hashes agree, the family closed."
                                   if verify else
                                   f"PUBLISHED and WITNESSED — {DEED_SITE}/deeds/{art} "
                                   "fetched back by the librarian's seat, hashes "
                                   "matched, the family closed whole."),
                         "deed": deed_id, "resolved_at": NOW()}})
        print(f"  ↳ DEED closed whole — /deeds/{art} ({'gone' if comp else 'live'}), "
              f"witnessed ({r['id']})")
        return
    call(port, "POST", "/requests",
         {"kind": "publish", "comp": True, "artifact": art,
          "text": f"the world went wrong for /deeds/{art} — "
                  f"observed {status}; the walk-back waits for your word"})
    call(port, "POST", "/requests/resolve",
         {"id": r["id"], "status": "done",
          "result": {"reply": f"the world disagrees — expected the artifact "
                              f"{'gone' if comp else 'live and matching'}; the door "
                              + (f"answered with DIFFERENT bytes "
                                 f"[{str(fetched_hash)[7:19]}…]" if status == "found"
                                 else f"said: {status}")
                              + ". A wrong world does not close: the "
                                "unpublish is STAGED at your gate.",
                     "deed": deed_id, "resolved_at": NOW()}})
    print(f"  ↳ deed reconciliation FAILED for /deeds/{art} — compensation staged")


_METAB_LAST = 0.0
_METAB_STATE: dict = {}          # the beat's last numbers — the room reads them
METABOLISM_EVERY = int(os.environ.get("ORRETH_METABOLISM_EVERY", "900"))


def metabolism_wire_beat() -> None:
    """THE SCHEDULED METABOLISM (wire-honesty sp2, 2026-07-25): 0039's
    metabolism_beat — the SAME sim function, one law on both grounds — runs on
    the worker's clock against the rag floor's projection. Due-window records
    without recent recall distill; the recalled stay warm (the sp1 tap feeds
    this); every forgetting lands a report with its measured loss in bits.
    The dials stay Canon assets; only the heartbeat lives here."""
    global _METAB_LAST
    if time.time() - _METAB_LAST < METABOLISM_EVERY:
        return
    rag = next(((p, s) for p, s in FLOOR_SCOPES.items()
                if s.endswith("/e:rag/f:naive")), None)
    if rag is None:
        return          # the floor isn't known yet — retry next round, free
    _METAB_LAST = time.time()   # the cadence burns only when ground exists
    rag_port, rag_scope = rag
    try:
        from orreth_sim import canon as _cn
        n, kp, did = _stacks_node(rag_port, rag_scope)
        if n is None:
            return
        rep = _cn.metabolism_beat(n, {"did": did, "scope": rag_scope}, kp)
        recalls_save(rag_scope, n)
        attest_note(rag_port, rag_scope, n)    # the dials it turned under (sp2)
        global _METAB_STATE
        _METAB_STATE = {"kept_warm": rep.get("kept_warm", 0),
                        "distilled": rep.get("distilled", 0),
                        "loss": float(rep.get("loss_bits", 0.0))}
        if rep.get("distilled"):
            print(f"  ↳ the metabolism beats (wire): {rep['distilled']} "
                  f"distilled · {rep.get('kept_warm', 0)} kept warm · loss "
                  f"{_METAB_STATE['loss']:.2f} bits "
                  f"[{str(rep.get('distillation', ''))[:18]}…]")
        else:
            print(f"  ↳ the metabolism beats (wire): nothing due · "
                  f"{rep.get('kept_warm', 0)} kept warm — usage is evidence")
    except Exception as e:
        print(f"    (metabolism beat stumbled: {e})")


def on_drift(port: int, scope: str, r: dict, *,
             approved: bool = False, declined: bool = False) -> bool:
    """The drift finding's gate (0041 sp4 — the revert): the human's YES
    restores the signed machine. Each drifted asset's PRE-DRIFT head is
    re-adopted as a NEW sibling (never a deletion, the versioned shelf's law) —
    the revert epoch that follows cites both parents. LEAVE-IT keeps the change
    and the finding on record. Auto-revert stays REFUSED (0041 §5): detection
    stages, a human turns the key, the revert is merely the easiest yes.
    The revert's resolution carries `resolved_at` — the word dated when it
    LANDS, so the next cut reads an obeyed human, never fresh drift. Returns
    False only when the approval must wait for a dark floor's beat."""
    target = r.get("scope") or scope
    restore = r.get("restore") or {}
    if declined:
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"reply": "left as it stands — the change holds and the "
                                  "finding remains walkable in the Chronicle"}})
        print(f"  ↳ drift left standing at the gate ({r.get('id')})")
        return True
    if approved:
        if not restore:
            call(port, "POST", "/requests/resolve",
                 {"id": r["id"], "status": "done",
                  "result": {"reply": "nothing to restore — an attestation lag "
                                      "converges when the point next loads; the "
                                      "finding stays on record"}})
            print(f"  ↳ drift ack (lag, no revert) ({r.get('id')})")
            return True
        t_port = next((p for p, s in FLOOR_SCOPES.items() if s == target), None)
        if t_port is None:
            # a dark floor never eats the human's word (the no-op-button law):
            # the approval stands unresolved and the round retries each pass
            if target not in _REVERT_WAITS:
                _REVERT_WAITS.add(target)
                print(f"  ↳ the revert waits at {r.get('id')} — {target} is "
                      "dark; the word stands until the floor beats")
            return False
        _REVERT_WAITS.discard(target)
        seat_kp, seat_did = lib_seat(target)
        restored = []
        for name, from_ref in restore.items():
            try:
                body = call(t_port, "GET",
                            f"/records/{urllib.parse.quote(from_ref, safe='')}/body")
                prof = (body or {}).get("asset", {}).get("profile") \
                    if isinstance(body, dict) else None
                if prof is None:
                    continue
                sib = improver.make_asset({"did": seat_did, "scope": target},
                                          seat_kp, target, name=name,
                                          profile=prof, adopted_from=from_ref)
                call(t_port, "POST", "/records", sib)
                restored.append(f"{name} → [{sib['id'][:14]}…]")
            except Exception as e:
                print(f"    (revert of {name} stumbled: {e})")
        if restored:
            _PENDING_REVERT[target] = {"restored_to": list(restore.values()),
                                       "at": NOW()}
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"reply": "REVERTED on your word — the signed machine "
                                  "stands again as a new sibling (the drifted "
                                  "version is not erased, only outranked): "
                                  + "; ".join(restored)
                                  + ". the next epoch cites both parents.",
                         "resolved_at": NOW()}})
        print(f"  ↳ REVERT at {target}: {len(restored)} head(s) restored as "
              f"siblings on your word ({r.get('id')})")
        return True
    call(port, "POST", "/requests/resolve",
         {"id": r["id"], "status": "staged",
          "result": {"package_text": r.get("package", ""),
                     "note": "detection stages, never enforces (0041)"}})
    print(f"  ↳ drift staged — the gate holds the diff ({r.get('id')})")
    return True


def wire_stacks_panel(port: int) -> dict:
    """The Stacks panel's facts (0038 §6): the standard's word, the newest
    standings, and the choice ledger's pulse — composed for the room."""
    import json as _json

    from orreth_sim import crypto as _c
    from orreth_sim import dispatcher
    rag_port, rag_scope = next(
        ((p, s) for p, s in FLOOR_SCOPES.items()
         if s.endswith("/e:rag/f:naive")), (None, None))
    if rag_port is None:
        return {}
    n, _, _ = _stacks_node(rag_port, rag_scope)
    if n is None:
        return {}
    std = dispatcher.standard(n)
    standings = []
    for r in sorted(n.records.values(), key=lambda x: x.get("received_at", "")):
        if "tournament" in (r.get("tags") or []):
            b = _json.loads(_c._b64d(r["body"]).decode()).get("stacks_tournament") or {}
            standings = b.get("standings") or standings
    tap = recalls_load(rag_scope)
    metab = dict(_METAB_STATE)
    for r in sorted(n.records.values(), key=lambda x: x.get("received_at", "")):
        if "metabolism-report" in (r.get("tags") or []):
            b = _json.loads(_c._b64d(r["body"]).decode()).get("metabolism_report") or {}
            metab = {"kept_warm": b.get("kept_warm", 0),
                     "distilled": b.get("distilled", 0),
                     "loss": float(b.get("loss_bits", 0.0))}
    return {"version": std.get("version", "?"), "default": std.get("default"),
            "built": std.get("built") or [], "standings": standings,
            "choices": len(dispatcher.choices(n, 50)),
            "knowledge_chunks": sum(1 for r in n.records.values()
                                    if "knowledge" in (r.get("tags") or [])),
            "warm": len(tap),
            "touches": sum(int(e.get("n", 0)) for e in tap.values()),
            "metabolism": metab,
            "epoch": _epoch_short(rag_scope),
            "attested": _attest_short(rag_scope)}


def _attest_short(scope: str) -> str:
    """The point's last sworn loading, glass-sized: an age — or its absence,
    visible (0041 §3: a silent point is never assumed fine). A stale oath
    wears its LAG in the open (sp3)."""
    try:
        head = json.loads(_attest_nest(scope).read_text())
        from datetime import datetime, timezone
        at = datetime.fromisoformat(str(head.get("at", "")).replace("Z", "+00:00"))
        mins = int((datetime.now(timezone.utc) - at).total_seconds() // 60)
        age = f"{mins}m ago" if mins < 120 else f"{mins // 60}h ago"
        try:
            declared = json.loads(_epoch_nest(scope).read_text()).get("id")
            if head.get("epoch") and declared and head["epoch"] != declared:
                return f"{age} · LAGS"
        except Exception:
            pass
        return age
    except Exception:
        return "no word yet"


def _epoch_short(scope: str) -> str:
    """The floor's standing epoch, glass-sized: 8 hash chars + an age."""
    try:
        head = json.loads(_epoch_nest(scope).read_text())
    except Exception:
        return "not yet named"
    hid = str(head.get("id", "")).replace("sha256:", "")[:8]
    try:
        from datetime import datetime, timezone
        at = datetime.fromisoformat(str(head.get("at", "")).replace("Z", "+00:00"))
        mins = int((datetime.now(timezone.utc) - at).total_seconds() // 60)
        age = f"{mins}m" if mins < 120 else f"{mins // 60}h"
    except Exception:
        age = "?"
    return f"{hid} · {age}"


def wire_stacks_routing(port: int, scope: str) -> str:
    """The organ's ledger, in words: the standard's rules and the newest
    choices — 'why did this go there?' answered from the record."""
    from orreth_sim import dispatcher
    n, _, _ = _stacks_node(port, scope)
    if n is None:
        return "the stacks are unreachable — try again on the next beat"
    std = dispatcher.standard(n)
    rules = " · ".join(f"{r['when']} → {r['route']}" for r in std.get("rules", []))
    led = dispatcher.choices(n, 4)
    recent = "; ".join(f"“{c['ask'][:40]}” → {c['flavor']}"
                       + (f" (wanted {c['wanted']})" if c.get("wanted") else "")
                       for c in led) or "no choices yet — ask, and the ledger fills"
    return (f"the routing standard v{std.get('version', '?')} (a versioned asset "
            f"— I tend it, the lanes gate changes): {rules}; default → "
            f"{std.get('default', 'naive')}; rows breathing: "
            f"{', '.join(std.get('built', []))}. recent choices: {recent}. "
            "every choice is a record — walk any of them in the window.")


def wire_estate_template(port: int, subject: str) -> str:
    """The yaml, recallable by a human (0037 §4) — read back from the newest
    template asset for the subject."""
    from orreth_sim import estate
    rows = wire_assets(port, "asset", name=f"template-{estate._slug(subject)}")
    if not rows:
        return (f"no template stands for «{subject}» — say “plan <what you "
                "want>” and I draft one, free of consequence (§8.4).")
    prof = ((rows[-1][1].get("asset") or {}).get("profile")) or {}
    return (f"the template for «{subject}» ({prof.get('stack', '?')}):\n"
            + (prof.get("yaml") or "")[:480])


# ---------------------------------------------------------------- the shipyard (0009→wire)

UNIVERSE_SCOPE = "u:demo"
TRUST_ROOT = "did:web:orreth.ai:u:demo"
RIG_IMAGE = "orreth-demo-universe-eco-cloud"          # one binary, any tier (0000)
RIG_NET = "orreth-demo-universe_default"
RIG_PG = "postgres://postgres:orreth@pg:5432/postgres"
PROFILES_DIR = Path(__file__).resolve().parents[1] / "plane" / "profiles"


class Shipyard:
    """The dock crew: executes launch plans the brain (orreth_sim.shipyard) drafts.
    A staged plan waits for the human (0012 — growing the universe is consequential);
    an approved plan becomes real containers on the rig's own network, each new floor
    pulling its parent's floors at boot and beating into the orrery by itself. The
    ledger (~/.orreth/shipyard/floors.json) makes launches durable: the worker tends
    dynamic floors after its own restarts and relaunches hulls the rig lost."""

    def __init__(self) -> None:
        self.path = HOME / "shipyard" / "floors.json"
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.plans: dict[str, dict] = {}               # request id → drafted plan

    def ledger(self) -> dict:
        return json.loads(self.path.read_text()) if self.path.exists() else {}

    def save(self, led: dict) -> None:
        self.path.write_text(json.dumps(led, indent=1, sort_keys=True))

    def floors(self) -> list[int]:
        return sorted(int(p) for p in self.ledger())

    def _docker(self, *args: str) -> tuple[bool, str]:
        import subprocess
        r = subprocess.run(["docker", *args], capture_output=True, text=True, timeout=120)
        return r.returncode == 0, (r.stdout or r.stderr).strip()

    def _launch_one(self, spec: dict) -> tuple[bool, str]:
        # first launch carries the profile inline; a replant rides the file the
        # first launch left on disk (the ledger stores names, never bodies)
        prof = PROFILES_DIR / spec["profile_file"]
        if "profile" in spec:
            prof.write_text(json.dumps(spec["profile"], indent=2))
        elif not prof.exists():
            return False, f"no profile on disk for {spec['profile_file']} — cannot replant"
        parent = (f"http://{spec['parent_container']}:{spec['parent_port']}"
                  if spec.get("parent_container") else "http://universe:4500")
        port = str(spec["port"])
        self._docker("rm", "-f", spec["container"])    # a stale hull never blocks a launch
        return self._docker(
            "run", "-d", "--name", spec["container"], "--network", RIG_NET,
            "--restart", "unless-stopped",
            "-e", f"ORRETH_VERSION={os.environ.get('ORRETH_VERSION', 'dev')}",
            "-v", f"{PROFILES_DIR}:/profiles:ro",
            "-v", f"{spec['container']}-bodies:/data/bodies",
            "-p", f"{port}:{port}",
            RIG_IMAGE,
            "--profile", f"/profiles/{spec['profile_file']}", "--bind", "0.0.0.0",
            "--port", port, "--store-dir", "/data/bodies",
            "--root-pub", root_keypair().public,
            "--parent", parent, "--pg", RIG_PG)

    def on_field_join(self, port: int, r: dict) -> bool:
        """The field-join door (0038 sp4 — JB's gate catch): moons for a
        STANDING eco — planned against its real port, staged at the gate,
        launched into its hull's parentage, durable in the ledger. Nothing
        relaunched, nothing doubled."""
        status = r.get("status")
        eco = str(r.get("eco") or "").strip()
        fields = [str(f) for f in (r.get("fields") or [])]
        eco_port = next((p for p, s in FLOOR_SCOPES.items()
                         if s == f"{UNIVERSE_SCOPE}/e:{eco}"), None)
        if status == "pending":
            if eco_port is None:
                call(port, "POST", "/requests/resolve",
                     {"id": r["id"], "status": "denied",
                      "result": {"note": f"no standing e:{eco} to join — grow "
                                         "the ecosystem first"}})
                return True
            used = {4500, 4501, 4502, *self.floors(),
                    *(int(p) for p in FLOOR_SCOPES)}
            try:
                p = shipyard.join_plan(UNIVERSE_SCOPE, eco, fields, used,
                                       TRUST_ROOT, eco_port)
            except ValueError as e:
                call(port, "POST", "/requests/resolve",
                     {"id": r["id"], "status": "denied", "result": {"note": str(e)}})
                return True
            self.plans[r["id"]] = p
            call(port, "POST", "/requests/resolve",
                 {"id": r["id"], "status": "staged",
                  "result": {"plan": p["summary"],
                             "note": "consequence waits for you (0012)"}})
            print(f"  ↳ shipyard staged join: {p['summary']}")
            return False
        if status == "approved":
            p = self.plans.pop(r["id"], None)
            if p is None:
                call(port, "POST", "/requests/resolve",
                     {"id": r["id"], "status": "denied",
                      "result": {"note": "the drafted plan was lost to a restart "
                                         "— ask again and the yard redrafts"}})
                return True
            led = self.ledger()
            landed, missed = [], []
            for m in p["fields"]:
                ok, out = self._launch_one(m)
                if ok:
                    led[str(m["port"])] = {k: m[k] for k in
                                           ("container", "port", "parent_container",
                                            "parent_port", "scope", "profile_file")}
                    landed.append(f"{m['name']}:{m['port']}")
                else:
                    missed.append(f"{m['name']}: {out[:60]}")
            self.save(led)
            call(port, "POST", "/requests/resolve",
                 {"id": r["id"], "status": "done",
                  "result": {"reply": f"joined the standing e:{eco}: "
                                      + (", ".join(landed) or "nothing")
                                      + (f"; missed: {'; '.join(missed)}"
                                         if missed else "")}})
            print(f"  ↳ shipyard join complete — {len(landed)} moon(s), "
                  f"{len(missed)} miss(es)")
            return True
        if status == "denied":
            self.plans.pop(r["id"], None)
            return True
        return False

    def on_request(self, port: int, r: dict) -> bool:
        """Mirrors the farm gate: stage on pending, launch on approved.
        Returns True when the request reached a resting state."""
        status = r.get("status")
        if status == "pending":
            # the living-hull guard (0038 sp4 — the :4511 incident, 2026-07-22):
            # a whole-ecosystem plan for a STANDING scope would rm -f the living
            # hull and rebirth it elsewhere. Refuse at the plan; the join door
            # is the honest path for growth.
            eco_scope = f"{UNIVERSE_SCOPE}/e:{r.get('eco', '')}"
            standing = any(s.get("scope") == eco_scope
                           for s in self.ledger().values()) \
                or eco_scope in FLOOR_SCOPES.values()
            if standing:
                call(port, "POST", "/requests/resolve",
                     {"id": r["id"], "status": "denied",
                      "result": {"note": f"e:{r.get('eco', '')} already sails — "
                                         "a second hull would cut down the "
                                         "living one. say “add fields … to "
                                         f"ecosystem {r.get('eco', '')}” (the "
                                         "join door, 0038 sp4)"}})
                print(f"  ↳ shipyard REFUSED a duplicate hull for {eco_scope}")
                return True
            try:
                p = shipyard.plan(UNIVERSE_SCOPE, r.get("eco", ""),
                                  r.get("fields") or [],
                                  {4500, 4501, 4502, *self.floors()}, TRUST_ROOT,
                                  template=r.get("template"))
            except ValueError as e:
                call(port, "POST", "/requests/resolve",
                     {"id": r["id"], "status": "denied", "result": {"note": str(e)}})
                return True
            self.plans[r["id"]] = p
            call(port, "POST", "/requests/resolve",
                 {"id": r["id"], "status": "staged",
                  "result": {"plan": p["summary"],
                             "note": "consequence waits for you (0012)"}})
            print(f"  ↳ shipyard staged: {p['summary']}")
            return False
        if status == "approved":
            p = self.plans.pop(r["id"], None)
            if p is None:                              # worker restarted mid-gate: redraft
                try:
                    p = shipyard.plan(UNIVERSE_SCOPE, r.get("eco", ""),
                                      r.get("fields") or [],
                                      {4500, 4501, 4502, *self.floors()}, TRUST_ROOT,
                                      template=r.get("template"))
                except ValueError as e:
                    call(port, "POST", "/requests/resolve",
                         {"id": r["id"], "status": "denied", "result": {"note": str(e)}})
                    return True
            led, launched, failed = self.ledger(), [], None
            eco = {**p["eco"], "parent_port": 4500}
            ok, out = self._launch_one(eco)
            if ok:
                led[str(eco["port"])] = {k: eco[k] for k in
                                         ("kind", "name", "scope", "port", "container",
                                          "parent_container", "profile_file")}
                led[str(eco["port"])]["parent_port"] = 4500
                if eco.get("template"):        # the floor remembers its law (0034)
                    led[str(eco["port"])]["template"] = eco["template"]
                launched.append(f"{eco['scope']} :{eco['port']}")
                for m in p["fields"]:
                    m = {**m, "parent_port": eco["port"]}
                    ok, out = self._launch_one(m)
                    if not ok:
                        failed = out
                        break
                    led[str(m["port"])] = {k: m[k] for k in
                                           ("kind", "name", "scope", "port", "container",
                                            "parent_container", "profile_file")}
                    led[str(m["port"])]["parent_port"] = eco["port"]
                    if m.get("template"):
                        led[str(m["port"])]["template"] = m["template"]
                    launched.append(f"{m['scope']} :{m['port']}")
            else:
                failed = out
            self.save(led)
            result = {"launched": launched}
            if failed:
                result["note"] = f"partial launch — docker said: {failed[:160]}"
            call(port, "POST", "/requests/resolve",
                 {"id": r["id"], "status": "done", "result": result})
            for line in launched:
                print(f"    ✓ launched {line}")
            if failed:
                print(f"    (launch trouble: {failed[:120]})")
            return True
        if status == "denied":
            self.plans.pop(r["id"], None)
            call(port, "POST", "/requests/resolve", {"id": r["id"], "status": "done",
                 "result": {"note": "scrapped at the gate — nothing launched"}})
            print("  ↳ shipyard: plan scrapped at the gate")
            return True
        return False

    def replant(self) -> None:
        """The rig may restart without its dynamic hulls (they live outside compose):
        relaunch anything in the ledger that is not answering."""
        for port_s, spec in sorted(self.ledger().items()):
            try:
                call(int(port_s), "GET", "/health")
                continue
            except Exception:
                pass
            if spec.get("scope") in _down_load() \
                    or _hull_state(spec.get("container", "")) == "exited":
                # 0055 — shut down by the human's word (durable in the
                # down-ledger); a janitor never outranks a shutdown
                continue
            try:                                   # one bad hull never sinks the round
                ok, out = self._launch_one(spec)
            except Exception as e:
                ok, out = False, str(e)
            print(f"  ↳ shipyard replant {spec.get('scope', '?')} :{port_s} — "
                  + ("relaunched" if ok else f"failed: {out[:100]}"))


SHIPYARD = Shipyard()

ALLEN_FIELD_PORT = 4510


def ensure_allen_floor() -> None:
    """allen's BODY on the wire (0037 §1, locked §8.3): a field parented
    directly off the universe — no eco between. His floor rides the shipyard's
    own machinery: profile from the plain field shape, spec in the durable
    ledger (the replant tends it forever after), the hull beating into :4500
    so the orrery and the Brain finally SHOW the embodied tier (rule 7 —
    JB's walk finding 2026-07-22: 'if allen is a field off Universe, why
    can't we see it')."""
    led = SHIPYARD.ledger()
    if str(ALLEN_FIELD_PORT) in led:
        return                                # the ledger tends it from here
    try:
        base = json.loads((PROFILES_DIR / "dyn-e-retail-f-pos.json").read_text())
    except Exception as e:
        print(f"    (allen floor: no base profile — {e})")
        return
    base["scope"] = "u:demo/f:allen"
    base["clock"]["high_water_scope"] = "u:demo/f:allen"
    spec = {"container": "orreth-field-allen", "port": ALLEN_FIELD_PORT,
            "parent_port": 4500, "scope": "u:demo/f:allen",
            "profile_file": "dyn-f-allen.json", "profile": base}
    ok, out = SHIPYARD._launch_one(spec)
    if ok:
        led[str(ALLEN_FIELD_PORT)] = {k: spec[k] for k in
                                      ("container", "port", "parent_port",
                                       "scope", "profile_file")}
        SHIPYARD.save(led)
        print(f"  ↳ allen's field stands — u:demo/f:allen on :{ALLEN_FIELD_PORT}, "
              "parented to the universe itself (0037 §8.3)")
    else:
        print(f"    (allen floor launch failed: {out[:120]})")


# ---------------------------------------------------------------- the organ pins (R1)

_PIN_FAILED: set = set()                     # (port, organ): grumble once, not every beat


_STUDIO_DID: str | None = None


def _studio_did() -> str | None:
    """The studio's DID from its own join at becky's gate — the worker
    NEVER holds its key (rule 1: a self is its own); the pin attests the
    identity the gate already proved (0051 sp4)."""
    global _STUDIO_DID
    if _STUDIO_DID:
        return _STUDIO_DID
    try:
        rows = call(JOIN_PORT, "GET", "/requests").get("requests", [])
    except Exception:
        return None
    for q in reversed(rows):
        if (q.get("kind") == "join" and q.get("name") == "studio"
                and q.get("status") in ("approved", "done") and q.get("did")):
            _STUDIO_DID = q["did"]
            return _STUDIO_DID
    return None


def pin_organs(port: int, floor: str) -> None:
    """Authority beats archaeology (the stricter R1): becky mints each organ an
    identity token, the floor verifies its chain against the pinned root, and the
    roster stops mining records for that organ's DID. Idempotent every beat, so a
    restarted daemon is re-pinned within seconds — like the replant, for identity.
    The librarian pins her SEAT for this floor (0023 §1): the same mind, this
    floor's key, carried on her no-levers token."""
    try:
        pins = call(port, "GET", "/organs").get("pins", {})
    except Exception:
        return
    _, seat_did = lib_seat(floor)
    organs = (
        ("charlotte", CHA_DID,
         lambda: _BECKY.issue_token(CHA_DID, SCOPE, [{"action": "retrieve", "space": "self"}])),
        ("librarian", seat_did, lambda: lib_no_levers_token(floor)),
        ("ada", ADA_DID,
         lambda: _BECKY.issue_token(ADA_DID, SCOPE, [{"action": "retrieve", "space": "self"}])),
    )
    if floor == UNIVERSE_SCOPE:              # one workshop, the universe floor (0031 §4)
        organs += (
            ("grace", IMP_DID,
             lambda: _BECKY.issue_token(IMP_DID, SCOPE,
                                        [{"action": "retrieve", "space": "self"}])),
            # allen, staff of the universe (0037 §8.3): pin-only, like the smith;
            # his universe-parented field on the wire lands with the toolroom (sp4)
            ("allen", ALLEN_DID,
             lambda: _BECKY.issue_token(ALLEN_DID, SCOPE,
                                        [{"action": "retrieve", "space": "self"}])),
            # vera, the astronomer (0043 §2): one observatory, the universe
            # floor — the improver's precedent; her judges live elsewhere
            ("vera", VERA_DID,
             lambda: _BECKY.issue_token(VERA_DID, SCOPE,
                                        [{"action": "retrieve", "space": "self"}])),)
        # the studio takes its face (0051 sp4): the mind that reads every
        # ask joins the residents' rail — its KEY stays with its own citizen
        # process; the pin attests what becky's gate already proved
        sdid = _studio_did()
        if sdid:
            organs += (("studio", sdid,
                        lambda d=sdid: _BECKY.issue_token(
                            d, SCOPE, [{"action": "retrieve",
                                        "space": "self"}])),)
    for organ, did, mint in organs:
        if pins.get(organ) == did:
            continue
        try:
            call(port, "POST", "/organs/pin", {"organ": organ, "token": mint()})
            _PIN_FAILED.discard((port, organ))
            print(f"  ↳ pinned {organ} → {did[:22]}… on :{port} (becky-chained)")
        except Exception as e:
            if (port, organ) not in _PIN_FAILED:
                _PIN_FAILED.add((port, organ))
                print(f"    (pin {organ} on :{port} refused: {e} — mined fallback stands)")


# ---------------------------------------------------------------- the window's eyes (0030 §4)

WIN = _seed("window-viewer")                 # the glass's read-only self, persisted
WIN_DID = crypto.did_key_for(WIN.public)
_WINDOW_PINNED: set = set()


def window_charter(port: int, scope: str) -> None:
    """The glass's own eyes (0030 §4): becky mints the window a READ-ONLY viewer
    capability and pins it on the floor — so a human at :PORT/window sees their
    floor's spacetime bare, no CLI ceremony. Idempotent per boot, like the organ
    pins; the pane still holds no privileged path — this IS a capability."""
    if (port, scope) in _WINDOW_PINNED:
        return
    segs = scope.split("/")
    tiers = ["/".join(segs[:i + 1]) for i in range(len(segs))][::-1]  # deepest first
    token = _ROOT.issue_token(WIN_DID, "u:demo",
                              [{"action": "retrieve", "space": "self"}])
    cfg = {"requester": WIN_DID, "token": token, "requester_scope": scope,
           "tiers": tiers}
    try:
        call(port, "POST", "/window/cfg", {"cfg": cfg})
        _WINDOW_PINNED.add((port, scope))
        print(f"  ↳ the window sees (0030): viewer capability pinned on :{port}")
    except Exception:
        pass                                  # an older daemon — the CLI path still works


# ---------------------------------------------------------------- the parlor (0020)

RESIDENT_KEYS = {"charlotte": (CHA, CHA_DID), "ada": (ADA, ADA_DID),
                 "grace": (IMP, IMP_DID),    # the smith IS the improver (0031 §4)
                 "allen": (ALLEN, ALLEN_DID),  # the architect (0037)
                 "vera": (VERA, VERA_DID)}   # the astronomer (0043 §2)


def resident_key(name: str, scope: str = SCOPE):
    """The signing self behind a parlor seat — becky's door and her parlor chair are
    one identity. The librarian signs under her SEAT for the floor being served
    (0023 §1): the same mind, this floor's key. Unembodied organs return
    (None, None): they receive, never sign."""
    if name == "becky":
        return _BECKY.kp, _BECKY.did
    if name == "librarian":
        return lib_seat(scope)
    return RESIDENT_KEYS.get(name, (None, None))


class _WireNode:
    """A write-only shim (0029): the admission logic speaks `node.write`; the
    wire's write is POST /records. Reads never pass through here — the sim node
    it mimics stays the reference implementation."""

    def __init__(self, port: int, scope: str):
        self.port, self.scope = port, scope

    def write(self, rec: dict) -> str:
        call(self.port, "POST", "/records", rec)
        return rec["id"]


def parlor_facts(port: int, scope: str) -> dict:
    """What the resident may read before it answers — its floor's governed state.
    The human never sees any of this raw; only the composed answer travels."""
    facts: dict = {"scope": scope}
    try:
        facts["farm"] = [s for s in call(port, "GET", "/farm").get("services", [])
                         if s.get("floor") == scope]
    except Exception:
        pass
    try:
        st = call(port, "GET", "/stable")
        facts["stalls"] = [s for s in st.get("stalls", []) if s.get("floor") == scope]
        facts["usage"] = st.get("usage", [])
    except Exception:
        pass
    try:
        p = call(port, "GET", "/presence")
        facts["residents"] = p.get("residents", [])
        facts["workforce"] = p.get("workforce", [])
    except Exception:
        pass
    try:
        facts["requests"] = call(port, "GET", "/requests").get("requests", [])
    except Exception:
        pass
    return facts


def executable(port: int, model: str) -> str | None:
    """The litellm string cognition can actually call — or None when this floor holds
    no key for the routed model. Authorize is truth for routing; keys are truth for
    execution (0016 §6): a stall's route decides which key the call needs."""
    route = "litellm-direct"
    try:
        for s in call(port, "GET", "/stable").get("stalls", []):
            if s.get("id") == model:
                route = s.get("route", route)
                break
    except Exception:
        pass
    if route == "openrouter":
        return f"openrouter/{model}" if os.environ.get("OPENROUTER_API_KEY") else None
    keys = {"anthropic": "ANTHROPIC_API_KEY", "openai": "OPENAI_API_KEY"}
    need = keys.get(model.split("/")[0])
    return model if need and os.environ.get(need) else None


# 0046's roster, one source: the listen kit grounds referrals in it and the
# 0048 classify leg routes charter mismatches by it — two ears, one truth.
CHARTERS_ROSTER = (
    "becky keeps identity and every door · vigil keeps "
    "detection · steward keeps memory's metabolism · governance keeps "
    "the floors' law · charlotte keeps the FARM (tools, services, MCP "
    "stalls) · librarian keeps knowledge and the gathers · ada keeps "
    "the STABLE (minds, models) · grace keeps the workshop (craft "
    "proposals) · allen keeps the cloud estate · vera keeps the "
    "observatory (measurement, verdicts, the dial)")


def _listen_kit(name: str, port: int, scope: str, facts: dict,
                card: str) -> str:
    """0046 sp1 — the grounding kit: what this resident may honestly speak
    from, composed from the CACHED composers. The registry is the
    cross-scope library card (0045); the status card rides as context,
    never as the whole truth. ≤ ~2,000 chars."""
    u = universe_port(port)
    bits: list[str] = [
        "THE RESIDENTS AND THEIR CHARTERS (refer by NAME when a question "
        "is theirs): " + CHARTERS_ROSTER]
    try:
        g = compose_governance()
        cats: dict = {}
        for o in g.get("objects", []):
            cats.setdefault(o["category"], []).append(
                f"{o['name']} v{o['versions']}")
        bits.append("THE REGISTRY (the craft across the floors — 0045): "
                    + " · ".join(f"{c}: {', '.join(v[:8])}"
                                 for c, v in sorted(cats.items())))
        if g.get("rubrics"):
            bits.append(f"declared rubrics on file: {len(g['rubrics'])}")
    except Exception:
        pass
    if name == "vera":
        try:
            o = compose_observatory()
            bits.append(f"THE OBSERVATORY: dial {o['dial']['position']} · "
                        f"spent {o['dial'].get('spent_today', 0)} of "
                        f"{o['dial'].get('ceiling_tokens', 0)} tok today · "
                        f"the bell {o.get('bell', {}).get('state', '?')}")
        except Exception:
            pass
    if name == "charlotte":
        try:
            svc = call(u, "GET", "/farm").get("services", [])
            bits.append("THE FARM: " + " · ".join(
                f"{s.get('name')}({s.get('state')}, {s.get('calls', 0)} calls)"
                for s in svc[:10]))
        except Exception:
            pass
    if name == "allen":
        est_facts = facts.get("estate")
        if est_facts:
            bits.append("THE ESTATE: " + str(est_facts)[:300])
    kit = "\n".join(bits)[:2000]
    return (kit + "\n\nYOUR STATUS CARD (context, not the whole truth):\n"
            + str(card)[:400])


def governed_voice(port: int, name: str, did: str, question: str, grounded: str) -> str | None:
    """The resident phrases its grounded answer with one governed thought —
    authorize, think, meter, all under its own DID (0019 §4). The facts travel INTO
    the prompt; the prompt never touches the plane (0016 §6). Classes are tried
    cheap→rich, degrade-where-pins-allow (0010): a grant this floor cannot execute
    is refunded and the next class asked. Unfueled floors fall back to the grounded
    reply — deterministic, never silent, never faked."""
    try:
        import litellm
    except Exception:
        return None
    if not (os.environ.get("ANTHROPIC_API_KEY") or os.environ.get("OPENAI_API_KEY")
            or os.environ.get("OPENROUTER_API_KEY")):
        return None
    # 0046 sp1 — THE EAR IS EVERY FLOOR'S: the old one-floor gate left every
    # other parlor answering in canned cards (JB's find — "the parlor routes
    # keywords, it does not listen"). Authorization stays per-floor and
    # honest; execution was always worker-local.
    est = 380
    for klass in ("low", "medium", "high"):
        try:
            token = _BECKY.issue_token(did, SCOPE, [{"action": "retrieve", "space": "self"}],
                                       budget={"tokens": 50000})
            grant = call(port, "POST", "/model/authorize",
                         {"token": token, "class": klass, "est_tokens": est})
            model = executable(port, grant["model"])
            if model is None:             # honest refund: authorized, but no key to execute
                call(port, "POST", "/model/meter",
                     {"subject": did, "est_tokens": est, "tokens": 0, "usd": 0,
                      "model": grant["model"], "class": klass})
                FLIGHT.refuse(did, klass, "no-local-key")
                continue
            t0 = time.perf_counter()
            resp = litellm.completion(
                model=model, max_tokens=240,
                messages=[{"role": "system", "content":
                           craft_render(craft(universe_port(port),
                                              "resident-voice"),
                                        name=name, scope=SCOPE,
                                        facts=grounded)},
                          {"role": "user", "content": question}])
            ms = int((time.perf_counter() - t0) * 1000)
            tokens = resp.usage.total_tokens
            try:
                usd = litellm.completion_cost(completion_response=resp)
            except Exception:
                usd = 0.0
            call(port, "POST", "/model/meter",
                 {"subject": did, "est_tokens": est, "tokens": tokens,
                  "usd": round(usd, 6), "model": grant["model"], "class": klass})
            FLIGHT.note(caller=did, klass=klass, model=grant["model"],
                        tokens=tokens, usd=usd, ms=ms)
            out = (resp.choices[0].message.content or "").strip()
            if out:
                return out
        except Exception:
            FLIGHT.refuse(did, klass, "stumbled")
            continue
    return None


def on_objective_cancel(port: int, scope: str, r: dict) -> None:
    """0051 sp2 — covenant rule 11 at the objective: the human's stop is a
    governed act ON the queue. Staged work cancels without fanning;
    executing work stops at the next safe boundary — pending legs resolve
    «the origin withdrew», finished answers are KEPT and labeled, and the
    close-out says what was left undone. The cancellation record lands
    under the HUMAN seat; nothing is deleted, nothing rolls back by itself
    (reversal is the deed family's craft — 0042, offered never assumed)."""
    rid = str(r.get("id") or "")
    target = str(r.get("of") or "")

    def done(reply, **kw):
        call(port, "POST", "/requests/resolve",
             {"id": rid, "status": "done", "result": {"reply": reply, **kw}})

    try:
        reqs = call(port, "GET", "/requests").get("requests", [])
    except Exception:
        return done("the queue would not answer — nothing changed")
    t = next((x for x in reqs if x.get("id") == target), None)
    if t is None or t.get("status") in ("done", "denied", "cancelled"):
        return done(sentence(port, "cancel-nothing"))
    res = t.get("result") or {}
    finished, stopped, undone = [], [], []
    st = _OBJECTIVES.get(target)
    if t.get("status") == "approved" and st is not None:
        for t_port, leg in (st.get("legs") or {}).items():
            try:
                lr = next((x for x in call(t_port, "GET", "/requests")
                           .get("requests", [])
                           if x.get("id") == leg["id"]), None)
            except Exception:
                lr = None
            if lr is not None and lr.get("status") in ("pending", "staged"):
                try:
                    call(t_port, "POST", "/requests/resolve",
                         {"id": leg["id"], "status": "cancelled",
                          "result": {"reply": sentence(port, "cancel-leg")}})
                except Exception:
                    pass
                stopped.append(leg["seat"])
            else:
                finished.append(leg["seat"])
        undone = [i.get("intent", "")[:80]
                  for i in (st.get("plan") or {}).get("intentions", [])
                  if i.get("seat") in stopped]
        if st.get("question"):
            try:      # the flow's question dies with it — silence was denial
                call(port, "POST", "/requests/resolve",
                     {"id": st["question"], "status": "cancelled",
                      "result": {"reply": sentence(port, "cancel-leg")}})
            except Exception:
                pass
        _OBJECTIVES.pop(target, None)
    kp_h, did_h = human_seat(scope)
    rec = make_memory({"did": did_h, "scope": scope}, kp_h, scope,
                      {"cancellation": {"of": target,
                                        "objective": str(t.get("text") or "")[:200],
                                        "finished": finished,
                                        "stopped": stopped,
                                        "left_undone": undone, "at": NOW()}},
                      kind="semantic", tags=["cancellation"])
    if res.get("plan_record"):
        rec["derived_from"] = [res["plan_record"]]
    try:
        call(port, "POST", "/records", rec)
    except Exception as e:
        print(f"    (cancellation record failed: {e})")
    reply = sentence(port, "cancel-reply", finished=len(finished),
                     stopped=len(stopped))
    call(port, "POST", "/requests/resolve",
         {"id": target, "status": "cancelled",
          "result": {**res, "reply": reply,
                     "cancelled": {"finished": finished, "stopped": stopped,
                                   "left_undone": undone,
                                   "record": rec["id"]}}})
    done(reply, record=rec["id"])
    print(f"  ✋ objective {target} CANCELLED by the human's word — "
          f"{len(finished)} finished · {len(stopped)} stopped")


def on_standing_rest(port: int, scope: str, r: dict) -> None:
    """0051 sp2 — rule 11 at the standing doors: a duty or a watcher the
    human approved always offers its REST. Reversible by a new word,
    recorded under the human seat, never a deletion."""
    rid = str(r.get("id") or "")
    target = str(r.get("of") or "")
    kind = "reflexes" if r.get("kind") == "reflex-rest" else "charters"

    def done(reply):
        call(port, "POST", "/requests/resolve",
             {"id": rid, "status": "done", "result": {"reply": reply}})

    rows = _standing_load(kind)
    if target not in rows:
        return done(f"nothing standing under {target} — nothing changed")
    rows[target]["active"] = False
    rows[target]["rested_at"] = NOW()
    _standing_save(kind, rows)
    kp_h, did_h = human_seat(scope)
    rec = make_memory({"did": did_h, "scope": scope}, kp_h, scope,
                      {"rest": {"of": target, "kind": kind[:-1], "at": NOW()}},
                      kind="semantic", tags=["cancellation", "rest"])
    try:
        call(port, "POST", "/records", rec)
    except Exception as e:
        print(f"    (rest record failed: {e})")
    singular = "reflex" if kind == "reflexes" else "charter"
    done(sentence(port, f"{singular}-rest-reply"))
    print(f"  ✋ {singular} {target} RESTED by the human's word")


def on_gate_word(port: int, scope: str, r: dict) -> None:
    """0051 sp3 — the words back: a decision may carry the human's words.
    They land as a signed record under the HUMAN seat either way; a
    DECLINED gate's words additionally birth an open feedback record, so
    the 0048 loop reads and routes them exactly like a 👎 — a declined
    plan with a reason becomes fuel, never silence. No verdict is minted
    (a request is not a graded record); the words are the payload."""
    rid = str(r.get("id") or "")
    target = str(r.get("of") or "")
    decision = str(r.get("decision") or "").strip().lower()
    words = str(r.get("text") or "").strip()

    def done(reply):
        call(port, "POST", "/requests/resolve",
             {"id": rid, "status": "done", "result": {"reply": reply}})

    if not target or not words:
        return done("no words arrived — nothing landed")
    kp_h, did_h = human_seat(scope)
    rec = make_memory({"did": did_h, "scope": scope}, kp_h, scope,
                      {"gate_word": {"of": target, "decision": decision,
                                     "quoted": words}},
                      kind="semantic", tags=["gate-word"])
    try:
        call(port, "POST", "/records", rec)
    except Exception as e:
        print(f"    (gate-word record failed: {e})")
    if decision == "denied":
        fb = make_memory({"did": did_h, "scope": scope}, kp_h, scope,
                         {"feedback": {"of": target, "quoted": words,
                                       "state": "open",
                                       "source": "gate-decline"}},
                         kind="semantic", tags=["feedback", "gate-word"])
        fb["derived_from"] = [rec["id"]]
        try:
            call(port, "POST", "/records", fb)
            print(f"  🗣 gate-word on {target} (declined) — the words enter "
                  f"the loop as feedback [{fb['id'][:18]}…]")
        except Exception as e:
            print(f"    (gate-word feedback failed: {e})")
        return done(sentence(port, "gate-word-declined-reply"))
    print(f"  🗣 gate-word on {target} ({decision}) — on the record")
    done(sentence(port, "gate-word-approved-reply"))


def on_thumb(port: int, scope: str, r: dict) -> None:
    """0048 sp2: the human's thumb arrives at the door — judgment, never
    authorship. The sim's laws do the judging (one record by hash, a seated
    signer, 👍 a quiet verdict on vera's shelf, 👎 + words a feedback record
    quoting the human verbatim); this door only signs with the floor's human
    seat, lands the records, and answers the law's own promise: heard — on
    the record. A thumb needs no gate — it IS the human's word."""
    of = str(r.get("of") or "").strip()
    up = bool(r.get("up"))
    words = str(r.get("text") or "")
    kp, did = human_seat(scope)
    try:
        verdict, fb = thumb_mod.make_thumb({"did": did, "scope": scope}, kp,
                                           scope, of=of, up=up, text=words)
    except ValueError as e:
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done", "result": {"refused": str(e)}})
        print(f"  ✋ thumb {r.get('id')} refused: {e}")
        return
    for rec in (verdict, fb):
        if rec is None:
            continue
        try:
            call(port, "POST", "/records", rec)
        except Exception as e:
            print(f"    (thumb record write failed: {e})")
    call(port, "POST", "/requests/resolve",
         {"id": r["id"], "status": "done",
          "result": {"reply": sentence(port, "reply-thumb-heard"),
                     "verdict": verdict["id"],
                     **({"feedback": fb["id"]} if fb is not None else {})}})
    print(f"  {'👍' if up else '👎'} thumb on [{of[:18]}…] — verdict "
          f"{verdict['id'][:18]}…"
          + (f" · feedback {fb['id'][:18]}…" if fb is not None else ""))


def on_parlor(port: int, scope: str, r: dict) -> None:
    """An audience: the caller asks, the resident fetches with its own authority,
    and the exchange lands signed in the Window. Humans never read; they are answered."""
    name = str(r.get("to") or "").strip().lower()
    facts = parlor_facts(port, scope)
    if name == "librarian":                   # the desk answers her card too (0032)
        facts["subscriptions"] = wire_subscriptions(port, scope)
        facts["deliveries"] = wire_deliveries(port, scope)
        facts["passage"] = wire_passage(port, scope)  # the frozen portrait (0035 §4)
    if name == "becky":                       # the door-keeper's ledger (0034 §4)
        facts["consents"] = wire_consents(port, scope)
        facts["testament"] = wire_testaments(port, scope)  # the last word (0035)
        facts["passage"] = wire_passage(port, scope)       # and the machine's state
    if name == "allen":                       # the architect reads his estate (0037)
        facts["estate"] = wire_estate(universe_port(port))
    if name == "vera":                        # the astronomer reads her observatory (0043)
        u_port = universe_port(port)
        facts["dial"] = OBS["dial"]
        rows = wire_assets(u_port, "verdict")
        facts["verdicts"] = [(b or {}).get("assay") or {}
                             for _, b, _, _ in rows]   # whole shelf — her
        #   exhibit counts everything; the room's panels window for display
        s = FLIGHT.recorder.series
        facts["flight"] = {
            "thoughts": len(s.read("plane.thoughts")["points"]),
            "refusals": len(s.read("plane.refusals")["points"]),
            "note": observatory.INSTRUMENT_LABEL}
    if name == "studio":                      # the reader's own exhibits (0051 sp4)
        u_port = universe_port(port)
        try:
            _rq = call(u_port, "GET", "/requests").get("requests", [])
        except Exception:
            _rq = []
        _rs = [(q.get("result") or {}).get("understanding") or {}
               for q in _rq
               if q.get("kind") == "understand" and q.get("status") == "done"]
        facts["readings"] = [u for u in reversed(_rs) if u.get("reading")][:5]
        _sd = _studio_did()
        if _sd:
            facts["did"] = _sd
    if name == "grace":                       # the smith reads her shelf (0031 §4)
        u_port = universe_port(port)
        facts["shelf"] = wire_shelf(u_port)
        facts["requests"] = [x for x in facts.get("requests") or []]
        held = [x for x in facts["requests"]
                if x.get("kind") == "improvement" and x.get("status") == "staged"]
        res = held[-1].get("result") if held else None
        if isinstance(res, dict) and res.get("package_text"):
            facts["package_text"] = res["package_text"]
    if r.get("verb") == "card":
        c = parlor.card(name, facts)
        _, did = resident_key(name, scope)
        if did:
            c["did"] = did
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done", "result": {"card": c}})
        print(f"  ↳ parlor · {name}'s card handed to the caller")
        return
    if r.get("verb") == "upload":             # 0029 §2 — a file enters as an ask
        if name != "librarian":
            call(port, "POST", "/requests/resolve",
                 {"id": r["id"], "status": "done",
                  "result": {"reply": f"{name} does not receive files — hand them "
                                      "to the librarian; upload is her ask."}})
            return
        import base64 as _b64
        seat_kp, seat_did = lib_seat(scope)
        filename = str(r.get("filename") or "unnamed")
        try:
            data = _b64.b64decode(str(r.get("data_b64") or ""), validate=True)
        except Exception:
            data = b""
        try:
            from orreth_sim import artifacts
            from orreth_sim.node import Refusal as _Refusal
            try:
                receipt = artifacts.admit_upload(
                    _WireNode(port, scope), {"did": seat_did, "scope": scope},
                    seat_kp, filename, str(r.get("mime") or ""), data)
            except _Refusal:
                call(port, "POST", "/requests/resolve",
                     {"id": r["id"], "status": "denied",
                      "result": {"reply": "request cannot be served under this "
                                          "capability"}})
                print(f"  ↳ upload refused at the bars — {filename}")
                return
            reply = (f"“{filename}” admitted — extracted to knowledge, quarantined "
                     f"at 0.0000 [{receipt['extraction'][:18]}…]"
                     if receipt["status"] == "extracted" else
                     f"“{filename}” admitted dark — no eye saddled yet; the "
                     f"extraction intent is parked (0014) and will be read the day "
                     f"a vision mind joins the Stable")
            call(port, "POST", "/requests/resolve",
                 {"id": r["id"], "status": "done",
                  "result": {"reply": reply, **receipt}})
            print(f"  ↳ upload · {filename}: {receipt['status']} — "
                  f"artifact {receipt['artifact'][:18]}…")
        except Exception as e:
            print(f"    (upload admission failed: {e})")
            call(port, "POST", "/requests/resolve",
                 {"id": r["id"], "status": "done",
                  "result": {"reply": "the admission stumbled — try again"}})
        return
    if r.get("verb") == "workspace":          # 0028 §1 — the room is an ask too
        if name == "librarian":               # the richest room reads more state
            facts["stacks"] = wire_stacks_panel(port)   # the seven rows (0038)
            facts["profile_text"] = profile_read(port, scope)
            facts["markers"] = recent_markers(port, scope)
            facts["domains"] = domain_packages(port, scope)  # 0031 §5
            facts["subscriptions"] = wire_subscriptions(port, scope)  # 0032 §1
            facts["deliveries"] = wire_deliveries(port, scope)  # 0032 §2
            facts["interop"] = wire_interop(port, scope)  # 0034 sp3 — the mirror
        ws = parlor.workspace(name, facts)
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"workspace": ws or {"resident": name, "panels": []}}})
        print(f"  ↳ parlor · {name}'s room composed for the caller")
        return
    asked = str(r.get("text") or "").strip()
    ans = parlor.answer(name, asked, facts)
    reply = ans["reply"]
    if ans.get("action") == "self-dialog":  # 0023 §3 — the librarian asks her seats
        start_self_dialog(port, scope, r, ans["topic"], asked)
        return                              # resolves on a later beat, legs in hand
    if ans.get("action") == "gather":     # the librarian's real duty (0014), front-doored
        reply = gather(port, scope, ans["topic"])
    if ans.get("action") == "challenge":  # the human's doubt is a trigger (0031 §5)
        reply = challenge_walk(port, scope, ans["topic"])
    if ans.get("action") == "subscribe":  # 0032 §1 — the standing spend stages
        call(port, "POST", "/requests",
             {"kind": "subscription", "topic": ans["topic"],
              **({"cadence": ans["cadence"]} if ans.get("cadence") else {}),
              "text": f"subscribe to “{ans['topic']}” — a standing delivery"})
    if ans.get("action") == "unsubscribe":  # 0032 §1 — retired on the record
        reply = wire_unsubscribe(port, scope, ans["topic"])
    if ans.get("action") == "estate-answer":  # 0037 §3 — the human seat answers
        err = wire_charter_answer(universe_port(port), ans["key"], ans["answer"],
                                  ans.get("subject", ""))
        if err:
            reply = err
    if ans.get("action") == "estate-create":  # 0037 §3 — the in-ask interrogation
        reply = wire_estate_create(universe_port(port), ans["ask"])
    if ans.get("action") == "estate-preview":  # 0037 §4 — plan is free
        reply = wire_estate_preview(universe_port(port), ans["ask"])
    if ans.get("action") == "estate-adopt":   # 0037 §7 — the first touch stages
        call(port, "POST", "/requests",
             {"kind": "estate-adopt",
              "text": "adopt the estate — READ-ONLY walk of "
                      + " + ".join(ADOPT_STACKS) + ": describe, fetch "
                      "templates, attest; never mutate. the receipts open the "
                      "acceptance gate (0037 §7)"})
    if ans.get("action") == "field-join":     # 0038 sp4 — moons for a standing eco
        call(port, "POST", "/requests",
             {"kind": "field-join", "eco": ans["eco"], "fields": ans["fields"],
              "text": f"field(s) {', '.join(ans['fields'])} ask to join the "
                      f"standing e:{ans['eco']} — moons only, nothing doubled "
                      "(0038 sp4)"})
    if ans.get("action") == "estate-decide":  # the human's word, spoken (0037 §7)
        staged = [x for x in call(port, "GET", "/requests").get("requests", [])
                  if x.get("kind") == "estate-adopt"
                  and x.get("status") == "staged"]
        if staged:
            call(port, "POST", "/requests/resolve",
                 {"id": staged[-1]["id"],
                  "status": "approved" if ans.get("ok") else "denied"})
            print(f"  ↳ estate adoption {'APPROVED' if ans.get('ok') else 'denied'} "
                  "by the human's spoken word")
        else:
            reply = ("nothing stands at the gate to decide — say “adopt the "
                     "estate” first and the walk stages for you (0037 §7).")
    if ans.get("action") == "estate-template":  # 0037 §4 — the yaml, recallable
        reply = wire_estate_template(universe_port(port), ans["subject"])
    if ans.get("action") in ("stacks-ingest", "stacks-ask", "stacks-routing"):
        # one mind, many seats (0023 — JB's catch 2026-07-22): from a foreign
        # floor the ask RIDES TO HER RAG SEAT — same DID lineage, the origin
        # scope pinned into the choice record so the hop is on the record
        rag_port, rag_scope = next(
            ((p, s) for p, s in FLOOR_SCOPES.items()
             if s.endswith("/e:rag/f:naive")),   # the LOG lives at the naive row
            (None, None))
        if rag_port is None:
            reply = ("my rag seat is not standing — the stacks' floor is dark; "
                     "the shipyard can regrow it")
        else:
            origin = scope if scope != rag_scope else ""
            via = (" — carried from my seat at " + scope if origin else "")
            if ans["action"] == "stacks-ingest":   # 0038 §1 — once, at her seat
                seat_kp, seat_did = lib_seat(rag_scope)
                rec = make_memory({"did": seat_did, "scope": rag_scope}, seat_kp,
                                  rag_scope,
                                  {"stacks_document": {"name": ans["doc"],
                                                       "text": ans["text_body"][:4000],
                                                       **({"origin": origin}
                                                          if origin else {})}},
                                  kind="semantic",
                                  tags=["stacks", "document", ans["doc"]])
                try:
                    call(rag_port, "POST", "/records", rec)
                    print(f"  ↳ stacks shelve — “{ans['doc']}” "
                          f"[{rec['id'][:18]}…]{via}")
                except Exception as e:
                    reply = f"the shelving stumbled at the record — {e}"
            elif ans["action"] == "stacks-ask":
                reply = wire_stacks_ask(rag_port, rag_scope, ans["q"],
                                        origin=origin) + via
            else:
                reply = wire_stacks_routing(rag_port, rag_scope) + via
    if ans.get("action") == "graduation":     # 0039 sp4 — the ceremony, on the wire
        from orreth_sim import canon as _cn
        n2, kp2, did2 = _stacks_node(*next(
            ((p, s2) for p, s2 in FLOOR_SCOPES.items()
             if s2.endswith("/e:rag/f:naive")), (None, None)) or (None, None))
        if n2 is None:
            reply = "the stacks' floor is dark — no ground for a ceremony"
        else:
            me2 = {"did": did2, "scope": n2.scope}
            try:
                sk = _cn.crystallize(n2, me2, kp2,
                                     objective="summarize a floor's week",
                                     craft={"steps": ["gather the week's records",
                                                      "distill by score", "cite"]},
                                     rubric={"min_score": 0.8, "n": 3},
                                     proven_tier="high")
            except Exception:
                sk = "skill-summarize-a-floor-s-week"   # already on the shelf —
                # the same craft content-addresses to the same asset (0039)
            live = _live_graduation(n2, universe_port(port))
            if live is not None:
                scores, notes, usd, label = live
                for sc in scores:
                    _cn.canary_run(n2, me2, kp2, sk, tier="low", score=sc)
            else:
                notes, usd = [], 0.0
                label = "sim-judge v0 — no live ground (keys/stalls); honestly labeled"
                for sc in (0.9, 0.85, 0.88):
                    _cn.canary_run(n2, me2, kp2, sk, tier="low", score=sc)
            v = _cn.graduate(n2, me2, kp2, sk, mentee_tier="low")
            attest_note(next((p for p, s2 in FLOOR_SCOPES.items()
                              if s2 == n2.scope), 0), n2.scope, n2)  # sp2
            said = ("; the judge's word: " + " · ".join(notes[:2])) if notes else ""
            reply = (f"🎓 THE GRADUATION — «{sk}» crystallized at the smart tier, "
                     f"canaried {v['runs']}× at «{v['tier']}» ({label}), "
                     f"mean {v['mean']:.2f} vs rubric "
                     f"{v['rubric']['min_score']}: "
                     + ("GRADUATED — the cheap tier serves, the sibling version "
                        f"is on the shelf [{v['version'][:18]}…]. never silently "
                        "dumber — earned, on the record."
                        if v["graduated"] else v["why"])
                     + said
                     + (f" · the ceremony cost ${usd:.4f} on the meter"
                        if usd else ""))
    if ans.get("action") == "canon-census":   # 0039 sp1 — the genome's roll call
        from orreth_sim import canon
        rows = wire_assets(universe_port(port), "asset")
        seen: dict = {}
        for ref, body, dl, tags in rows:
            name = next((t for t in tags if t != "asset"), "?")
            seen[name] = seen.get(name, 0) + 1
        rag_port2 = next((p for p, s in FLOOR_SCOPES.items()
                          if s.endswith("/e:rag/f:naive")), None)
        if rag_port2:
            for ref, body, dl, tags in wire_assets(rag_port2, "asset"):
                name = next((t for t in tags if t != "asset"), "?")
                seen[name] = seen.get(name, 0) + 1
        floor_list = [c for c, v in canon.CLASSES_V1["classes"].items()
                      if not v["retrievable"]]
        entries = "; ".join(f"{n} ({v} version(s))"
                            for n, v in sorted(seen.items())) or "an empty shelf"
        reply = (f"THE CANON — the genome's roll call: {len(seen)} entry(ies): "
                 f"{entries}. the privacy floor (0039 §7, yours to gate): "
                 + " · ".join(floor_list) + " never enter a projection. every "
                 "entry versioned; changing any is a proposal at your gate.")
    if ans.get("action") == "stacks-tournament":  # 0038 sp4 — the demo itself
        rag_port, rag_scope = next(
            ((p, s) for p, s in FLOOR_SCOPES.items()
             if s.endswith("/e:rag/f:naive")), (None, None))
        reply = (wire_stacks_tournament(rag_port, rag_scope, ans.get("q", ""))
                 if rag_port else "the stacks' floor is dark — the shipyard "
                                  "can regrow it")
    if ans.get("action") == "domain":     # the package, a view over the record (0031 §5)
        rows = domain_packages(port, scope, ans.get("topic", ""))
        reply = ("; ".join(f"{d['topic']} — {d['meta']}" for d in rows[:6])
                 or "no domains yet — a gather starts one; say “gather sourced "
                    "knowledge on …” and the package grows from the record.")
    if ans.get("action") == "asset-walk":     # the smith walks a lineage (0031 §4)
        reply = wire_walk_reply(universe_port(port), ans["asset"])
    if ans.get("action") == "asset-feedback":  # the feedback door (0031 §4)
        wire_feedback(universe_port(port), UNIVERSE_SCOPE,
                      ans["asset"], ans.get("note", ""))
    if ans.get("action") == "profile-read":    # 0025 §4 — the portrait, labeled
        reply = profile_read(port, scope)
    if ans.get("action") == "profile-forget":  # 0025 §3 — consent withdrawn
        reply = profile_forget(port, scope, ans["topic"])
    if ans.get("action") == "ecosystem":  # the shipyard's front door — staged, never direct
        call(port, "POST", "/requests",
             {"kind": "ecosystem", "eco": ans["eco"], "fields": ans["fields"],
              **({"template": ans["template"]} if ans.get("template") else {}),
              "text": f"grow e:{ans['eco']}"
                      + (f" with field(s) {', '.join(ans['fields'])}" if ans["fields"]
                         else " — sailing alone")
                      + (f" · {ans['template']} template" if ans.get("template") else "")})
    if ans.get("action") == "consent-grant":  # 0034 §4 — access stages (0012)
        call(port, "POST", "/requests",
             {"kind": "consent",
              **({"role": ans["role"], "purpose": ans.get("purpose", ""),
                  "days": ans.get("days", 30)} if ans.get("role") else
                 {"modality": ans["modality"]}),
              "text": (f"grant {ans['role']} access"
                       + (f" — “{ans.get('purpose', '')}”" if ans.get("purpose")
                          else "")
                       if ans.get("role") else
                       f"resume {ans['modality']} recording")})
    if ans.get("action") == "consent-revoke":  # 0034 §4 — safety acts NOW
        reply = write_revocation(port, scope, role=ans.get("role"),
                                 modality=ans.get("modality"),
                                 reason="the human withdrew consent")
    if ans.get("action") == "testament-stage":  # 0035 §2 — the last word STAGES
        call(port, "POST", "/requests",
             {"kind": "testament", "fates": ans["fates"],
              "executor": ans.get("executor", ""),
              "heir": ans.get("heir", ""),
              "witnesses": ans.get("witnesses") or [],
              "silence_days": ans.get("silence_days", 30),
              "text": "testament: "
                      + (" · ".join(f"{d} {f}"
                                    for d, f in ans["fates"].items()))})
    if ans.get("action") == "testament-revoke":  # 0035 §2 — withdrawal acts NOW
        reply = write_testament_revocation(port, scope)
    if ans.get("action") == "attest-death":   # 0035 §3 — the gravest gate
        tst = [h for h in wire_testaments(port, scope)
               if h.get("posture") == "standing"]
        pstate, _ = passage_now(port, scope)
        if not tst:
            reply = ("no testament stands — the operational path is the only "
                     "door (0026 §2), and it waits for humans, plural")
        elif not continuity.may_stage_attestation({"state": pstate}):
            reply = (f"the universe is {pstate.upper()} — only a SEALED "
                     "universe may be attested dead (0035 §3)")
        elif not continuity.attestation_met(tst[-1], ans["attestors"],
                                            ans["evidence"],
                                            registry=ans.get("registry", False)):
            reply = ("the bar is not met — quorum 2: the executor + evidence "
                     "+ a named witness (or registry evidence), against the "
                     "testament's roster (0035 §8)")
        else:
            call(port, "POST", "/requests",
                 {"kind": "attestation", "evidence": ans["evidence"],
                  "attestors": ans["attestors"],
                  "registry": ans.get("registry", False),
                  "text": "attest death — the gravest gate (0035 §3)"})
    if ans.get("action") == "attestation-abort":  # one voice saves — acts NOW
        reply = abort_attestation(port, scope)
    if ans.get("action") == "dial-set":       # G4: depth is a governed choice
        call(port, "POST", "/requests",
             {"kind": "dial", "dial": ans["dial"],
              "text": f"turn the observatory dial «{OBS['dial']}» → "
                      f"«{ans['dial']}» — depth costs money and says so "
                      "(0043 §5)"})
    kp, did = resident_key(name, scope)
    voiced = None
    # descriptive answers may be voiced; actions and flow-control words never are —
    # a governed thought phrases facts, it does not rewrite protocol
    if kp is not None and not ans.get("action") and not ans.get("verbatim"):
        voiced = governed_voice(port, name, did, asked,
                                _listen_kit(name, port, scope, facts, reply))
    final = voiced or reply
    # safer mode (0034 §4): consent withdrawn ⇒ the parlor's recorder falls
    # quiet — the exchange is still ANSWERED, never written. Recall of what was
    # recorded under consent follows its own grant; nothing here erases.
    recordable = continuity.recording_allowed(wire_consents(port, scope),
                                              "conversation", NOW())
    if kp is not None and not recordable:
        final += "  ⸱  (unrecorded — conversation consent is withdrawn; safer mode)"
    # 0048 sp2: the exchange record is built BEFORE the resolve so its id can
    # ride the result — a thumb judges ONE record by hash, so an exchange that
    # will never land (safer mode, unembodied organ) honestly offers no thumb.
    rec = None
    if kp is not None and recordable:
        body = parlor.audience_body(name, asked, final,
                                    session=str(r.get("session") or ""),
                                    voiced=bool(voiced))
        rec = make_memory({"did": did, "scope": scope}, kp, scope, body,
                          kind="episodic", tags=["parlor", name])
    call(port, "POST", "/requests/resolve",
         {"id": r["id"], "status": "done",
          "result": {"reply": final, "voiced": bool(voiced), "by": did,
                     **({"exchange": rec["id"]} if rec is not None else {})}})
    if not asked.strip().lower().startswith(_NOT_A_HEARTBEAT):
        _HUMAN_HAND[scope] = time.time()      # first-hand: a living human spoke
    if kp is not None and not recordable:
        print(f"  ↳ parlor · {name} answered UNRECORDED at {scope} — safer mode (0034 §4)")
        return
    if rec is not None:                   # embodied residents sign the audience
        try:
            call(port, "POST", "/records", rec)
        except Exception as e:
            print(f"    (audience write failed: {e})")
        if ans.get("action") == "remember":   # 0024 §4 — the human's marker, auto lane
            mk = markers.make_marker({"did": did, "scope": scope}, kp, scope,
                                     [rec["id"]],
                                     reason="the human asked to remember",
                                     life_event=ans.get("weight", "minor"),
                                     quoted=ans.get("note", ""))
            try:
                call(port, "POST", "/records", mk)
                print(f"  ↳ marker · life_event={ans.get('weight', 'minor')} on the "
                      f"auto lane (R6) — {mk['id'][:18]}…")
                # 0025 §2: a weighty moment becomes an OBSERVATION — the Librarian's
                # stroke on the portrait, entering untrusted, its evidence named
                if ans.get("weight") in ("major", "substantial"):
                    obs = profile.make_claim(
                        {"did": did, "scope": scope}, kp, scope,
                        f"a {ans['weight']} moment: {ans.get('note', '')}",
                        asserted_by="librarian", inferred_from=mk["id"])
                    call(port, "POST", "/records", obs)
                    print(f"  ↳ profile · observation inferred (untrusted) — "
                          f"{obs['id'][:18]}…")
            except Exception as e:
                print(f"    (marker write failed: {e})")
        if ans.get("action") == "profile-assert":  # 0025 §2 — the sovereign stroke
            mk = profile.make_claim({"did": did, "scope": scope}, kp, scope,
                                    ans["claim"], asserted_by="human",
                                    quoted=ans["claim"])
            mk["derived_from"] = [rec["id"]]      # the ask is the provenance
            try:
                call(port, "POST", "/records", mk)
                print(f"  ↳ profile · human assertion (trusted) — {mk['id'][:18]}…")
            except Exception as e:
                print(f"    (profile write failed: {e})")
    print(f"  ↳ parlor · {name} received “{asked[:48]}”" + (" · voiced" if voiced else ""))


# ---------------------------------------------------------------- the reel

REEL = {"farm", "life", "spacetime", "knowledge", "chassis", "model",
        "stable", "parlor", "recall", "gate", "crew"}  # names only — never user text
_REEL_LOCK = threading.Lock()                          # one stage, one story at a time
_REPO = Path(__file__).resolve().parents[2]


def on_demo(port: int, r: dict) -> None:
    """Roll a demo from the glass: the request queue carries the ask, a background
    thread runs the reel (the round must keep turning — the demo's own requests need
    tending), and the transcript lands as the result when the story ends."""
    name = r.get("demo", "")
    if name not in REEL:
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"refused": f"no “{name}” on the reel"}})
        return
    if not _REEL_LOCK.acquire(blocking=False):
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"refused": "a story is already rolling — one at a time"}})
        return
    call(port, "POST", "/requests/resolve",
         {"id": r["id"], "status": "staged",
          "result": {"note": f"the reel is rolling: {name}"}})
    print(f"  ↳ the reel rolls: {name} (asked from the glass)")

    def roll() -> None:
        try:
            p = subprocess.run(["bash", str(_REPO / "scripts" / "demo.sh"), name],
                               capture_output=True, text=True, timeout=300)
            out, ok = (p.stdout + p.stderr)[-8000:], p.returncode == 0
        except subprocess.TimeoutExpired:
            out, ok = "(the story ran long — cut at 300s)", False
        except Exception as e:
            out, ok = f"(the projector jammed: {e})", False
        finally:
            _REEL_LOCK.release()
        try:
            call(port, "POST", "/requests/resolve",
                 {"id": r["id"], "status": "done",
                  "result": {"ok": ok, "transcript": out}})
            print(f"    ✓ reel {name}: {'the story landed' if ok else 'the story broke'}")
        except Exception as e:
            print(f"    (reel resolve failed: {e})")

    threading.Thread(target=roll, daemon=True).start()


# ---------------------------------------------------------------- the round

# --------------------------------------------------- 0043 sp2 · vera's assay beat
def _dial_load() -> str | None:
    try:
        with open(os.path.join(FlightBook.HOME, "dial.json")) as f:
            d = json.load(f).get("dial")
            return d if d in ("glance", "watch", "assay") else None
    except Exception:
        return None


# the dial is RUNTIME state (G4) and the WORD persists (G10, 0043 sp5): the
# nest outlives the process — a governed turn survives a restart; the env is
# the genesis default only. glance · watch · assay.
OBS = {"dial": _dial_load() or os.environ.get("ORRETH_OBS_DIAL", "glance")}
ASSAY_EVERY = int(os.environ.get("ORRETH_ASSAY_EVERY", "300"))
_ASSAY_LAST = 0.0


def _judge_seat(scope: str):
    """The judge's floor seat — a persisted self whose key signs what its
    floor's mind scored (the sim bench's wire twin; author ≠ executor)."""
    kp = _seed("judge-" + scope.replace("/", "~"))
    return {"did": crypto.did_key_for(kp.public), "scope": scope}, kp


def _parse_verdict(text: str):
    """The strict-JSON dance (the 0041-era live-judge lesson): a truncated
    verdict may still carry its number; an unparseable one is VOIDED —
    named, never scored, never blamed on the work."""
    import re as _re
    try:
        got = json.loads(_re.search(r"\{.*\}", text, _re.S).group(0))
        return (max(0.0, min(1.0, float(got.get("score", 0.0)))),
                str(got.get("why", ""))[:120])
    except Exception:
        m = _re.search(r'"score"\s*:\s*([0-9.]+)', text)
        if m:
            return (max(0.0, min(1.0, float(m.group(1)))),
                    "the judge's sentence was cut short; the score survived")
    return None, None


def _stage_assay_card(port: int, card: dict) -> None:
    """Detection wears no levers (0043 §2 law 3): the degradation stages at
    the human's gate with its yardstick, standing, and evidence — one open
    card per floor holds until the human decides."""
    try:
        reqs = call(port, "GET", "/requests").get("requests", [])
        if any(r.get("kind") == "assay" and r.get("status") in ("pending", "staged")
               and r.get("scope") == card["scope"] for r in reqs):
            return
        call(port, "POST", "/requests", {
            "kind": "assay", "to": "human", "scope": card["scope"],
            "text": f"ASSAY at {card['scope']} — {card['why']}",
            "package": "THE STANDING:\n" + json.dumps(card["standing"], indent=1)
                       + "\nEVIDENCE:\n"
                       + "\n".join(f"· {e[:44]}…" for e in card["evidence"][:6])
                       + "\nvera measures; humans move (0043 §2 — no levers)."})
        print(f"  🔭 assay DEGRADATION staged at {card['scope']}: {card['why']}")
    except Exception as e:
        print(f"    (assay staging stumbled: {e})")


# ---- G5: the declared ceiling — a budget the meter shows, then ENFORCES ---------------
ASSAY_CEILING = int(os.environ.get("ORRETH_ASSAY_DAILY_TOKENS", "25000"))


def _vera_spent_today() -> int:
    """Log-truth from the flight book: vera's metered tokens since UTC
    midnight — restart-proof, because the book is."""
    today = NOW()[:10]
    return sum(int(r.get("tokens") or 0) for r in FLIGHT.call_log
               if r.get("caller") == VERA_DID
               and str(r.get("at", "")).startswith(today))


