_BELL_SENDER = "bell@jsbarth.com"            # L-A as amended by JB 2026-08-02
_BELL_ENDPOINT = "jonathan_barth@ymail.com"  # named on the card; JB's word opens it
_CONSOLE_URL = "http://localhost:4500/window#f=4500&v=req"
_BELL: "bell_mod.Bell | None" = None


def _ses_send(payload: dict) -> None:
    """L-A: SES carries the ring, from the domain-verified sender. The payload
    reaching here already passed the bell's door — content-minimal by
    construction, and the door's laws, not this function, are the guarantee."""
    text = ("kind: {kind}\nscope: {scope}\nsubject: {subject}\nage: {age}\n"
            "the Console has the card: {pointer}\n\n"
            "— the bell · every send on the record (0044)").format(
        **{k: str(payload.get(k, "—")) for k in
           ("kind", "scope", "subject", "age", "pointer")})
    env = {k: v for k, v in os.environ.items()
           if k not in ("AWS_ACCESS_KEY_ID", "AWS_SECRET_ACCESS_KEY",
                        "AWS_SESSION_TOKEN")}
    subprocess.run(
        ["aws", "sesv2", "send-email", "--profile", "jb_support",
         "--region", "us-east-1", "--from-email-address", _BELL_SENDER,
         "--destination", json.dumps({"ToAddresses": [payload["endpoint"]]}),
         "--content", json.dumps({"Simple": {
             "Subject": {"Data": f"🔔 orreth · {payload.get('kind')} at "
                                 f"{payload.get('scope')}"},
             "Body": {"Text": {"Data": text}}}})],
        check=True, capture_output=True, timeout=30, env=env)


def _bell_state_load() -> dict:
    try:
        with open(os.path.join(FlightBook.HOME, "bell.json")) as f:
            return json.load(f)
    except Exception:
        return {}


def _bell_state_save(b: "bell_mod.Bell") -> None:
    rows = {f"{k}|{s}": {"at": v["at"], "ring": v["ring"]["id"],
                         "repeats": v["repeats"]}
            for (k, s), v in b.rung.items()}
    with open(os.path.join(FlightBook.HOME, "bell.json"), "w") as f:
        json.dump(rows, f)


def _bell_service(port: int) -> "bell_mod.Bell":
    """The bell as a standing resident: one DID, one pinned manifest (landed
    idempotently — content-addressed), the cooldown book reloaded so law 6
    survives the process (the ledger-seeds pattern)."""
    global _BELL
    if _BELL is None:
        me = {"did": BELL_DID, "scope": UNIVERSE_SCOPE}
        manifest = bell_mod.make_manifest(me, BELL, UNIVERSE_SCOPE,
                                          transport="ses", sender=_BELL_SENDER)
        try:
            call(port, "POST", "/records", manifest)
        except Exception:
            pass                              # the pin re-lands next start
        _BELL = bell_mod.Bell(
            me, BELL, UNIVERSE_SCOPE, manifest, transport=_ses_send,
            cooldown_s=int(os.environ.get("ORRETH_BELL_COOLDOWN_S", "3600")))
        for k, row in _bell_state_load().items():
            kind, _, subject = k.partition("|")
            _BELL.rung[(kind, subject)] = {"at": row["at"],
                                           "ring": {"id": row["ring"]},
                                           "repeats": row.get("repeats", 0)}
    return _BELL


def _bell_consent_head(port: int) -> dict | None:
    """The standing grant off the shelf — rows come oldest-first, the last
    posture wins (revoked is a state, never an absence; the bell's own door
    then refuses it one-faced)."""
    head = None
    for _, b, _, _ in wire_assets(port, "consent-bell"):
        if isinstance(b, dict) and isinstance(b.get("consent"), dict):
            head = b["consent"]
    return head


def ring_bell(port: int, request: dict) -> dict:
    """Any organ's ring request meets the door (0044 §3). Refusals wear the
    one face; a served ring lands record-then-wire and the outcome always."""
    b = _bell_service(port)
    out = b.ring(request, _bell_consent_head(port), at=NOW())
    if "ring" in out:
        for rec in (out["ring"], out["delivery"]):
            try:
                call(port, "POST", "/records", rec)
            except Exception as e:
                print(f"    (bell record write failed: {e})")
        _bell_state_save(b)
        print(f"  🔔 the bell rings: {request.get('kind')} · "
              f"{request.get('subject')} → {out['outcome']} "
              f"({out['ring']['id'][:18]}…)")
    elif "aged_into" in out:
        _bell_state_save(b)                   # the repeat OUTLIVES the process too
        print(f"  🔕 the bell holds: {request.get('kind')} · "
              f"{request.get('subject')} aged into the standing ring "
              f"(+{out['repeats']}) — the wire stays quiet (law 6)")
    return out


def _age_of(at: str | None) -> str:
    try:
        s = bell_mod._seconds_between(str(at), NOW())
    except Exception:
        return "—"
    return f"{s/3600:.1f}h" if s >= 3600 else f"{int(s)}s"


def first_sound(port: int) -> None:
    """The grant's echo: the bell's first ring is REAL news — the standing
    witness card if one waits, else the grant itself as its own subject."""
    q = call(port, "GET", "/requests").get("requests", [])
    w = next((x for x in q if x.get("kind") == "witness"
              and x.get("status") == "staged"), None)
    req = ({"kind": "witness", "scope": UNIVERSE_SCOPE,
            "subject": f"the worker at {UNIVERSE_SCOPE}",
            "age": _age_of(w.get("at")), "pointer": _CONSOLE_URL} if w else
           {"kind": "witness", "scope": UNIVERSE_SCOPE, "subject": "first-sound",
            "age": "0s", "pointer": _CONSOLE_URL})
    ring_bell(port, req)


def on_bell_consent(port: int, scope: str, r: dict, *, approved: bool,
                    declined: bool) -> None:
    """The bell's grant rides the consent gate (0034's door, the bell's
    purpose): staged with its terms readable; opened only on the human's
    word; declined stays on the record. The first ring answers the grant."""
    if declined:
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"declined": True,
                         "reply": "declined — the bell stays silent, and the "
                                  "record keeps that you chose"}})
        print("  🔕 bell consent declined — the last mile stays closed")
        return
    if approved:
        me = {"did": BELL_DID, "scope": scope}
        rec = bell_mod.make_ring_consent(
            me, BELL, scope, endpoint=_BELL_ENDPOINT,
            kinds=["witness", "gate-age", "tamper"],
            approved_ref=str(r.get("id") or ""))
        call(port, "POST", "/records", rec)
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"consent": rec["id"],
                         "reply": f"the last mile opens on your word — "
                                  f"{_BELL_ENDPOINT}, witness · gate-age · "
                                  f"tamper, a 90-day window (0044)"}})
        print(f"  🔔 bell consent OPENED — {rec['id'][:18]}…")
        first_sound(port)
        return
    if r.get("status") == "pending":
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "staged",
              "result": {"held": "reaching you beyond the glass is a "
                                 "consequence — open or decline (0044 §2)",
                         "terms": f"endpoint {_BELL_ENDPOINT} · kinds "
                                  f"witness/gate-age/tamper · cooldown "
                                  f"{int(os.environ.get('ORRETH_BELL_COOLDOWN_S', '3600'))//60}min "
                                  f"per subject · content-minimal · every "
                                  f"send on the record"}})


def on_commission(port: int, scope: str, r: dict) -> None:
    """0045 sp6 — THE COMMISSION (law 6): the human's click births craft
    through the machine's own organs — the librarian gathers, the factory
    drafts (a metered thought at a chosen bench), grace lands v1 with the
    whole ancestry named, and the finished work WAITS AT THE GATE for the
    human's welcome. The bell carries the card in-glass; out-of-band
    commission rings await a consent widening (one row, behind consent —
    law 3 kept)."""
    rid = str(r.get("id") or "")
    want = str(r.get("text") or "").strip()
    ckind = str(r.get("craft_kind") or "skill")

    def done(reply):
        call(port, "POST", "/requests/resolve",
             {"id": rid, "status": "done", "result": {"reply": reply}})

    if not want:
        return done("a commission with no objective refuses loudly. "
                    "Nothing created")
    print(f"  🏭 commission {rid}: “{want[:64]}” — the librarian goes gathering")
    knowledge = gather(port, scope, want)
    bench = _judge_bench(scope)
    if bench is None:
        return done("no bench holds a serving medium mind — the factory "
                    "rests honestly. Nothing created")
    draft = governed_thought(
        bench[0], JUDGE_MIND, "medium",
        "You are the FACTORY of a governed universe drafting a reusable "
        f"{ckind}. The human's commission: \"{want}\". The librarian "
        "gathered:\n" + str(knowledge)[:1200] + "\n\nReply with STRICT JSON "
        "only — begin with the { character, no preamble, no code fences: "
        "{\"name\": \"kebab-short-name\", \"steps\": [\"3 to 5 short "
        "imperative steps\"], \"text\": \"the craft's working prompt, 2-3 "
        "sentences\"}",
        max_tokens=600)
    import re as _re6
    prof = None
    for _attempt in range(2):                 # the factory redrafts ONCE (honest
        if draft and draft.get("text"):       # resilience, never a silent loop)
            try:
                prof = json.loads(_re6.search(r"\{.*\}", draft["text"],
                                              _re6.S).group(0))
                break
            except Exception:
                prof = None
        if _attempt == 0:
            print("    (the factory's first draft came back empty — redrafting once)")
            draft = governed_thought(
                bench[0], JUDGE_MIND, "medium",
                f"Draft a reusable {ckind} for: \"{want}\". Reply with STRICT "
                "JSON only, begin with the {{ character: {\"name\": "
                "\"kebab-short-name\", \"steps\": [\"3 to 5 short imperative "
                "steps\"], \"text\": \"the working prompt, 2-3 sentences\"}",
                max_tokens=600)
    if not isinstance(prof, dict):
        print(f"    (the factory's draft, verbatim head: "
              f"{draft['text'][:160]!r})" if draft else
              "    (the factory returned NO thought — the bench refused)")
        return done("the factory's draft was LOST — voided, never landed; "
                    "commission again")
    name = f"{ckind}-" + _re6.sub(
        r"[^a-z0-9]+", "-", str(prof.get("name") or want).lower()).strip("-")[:40]
    body = {"asset": {"name": name,
                      "profile": {"objective": want,
                                  "steps": prof.get("steps"),
                                  "text": prof.get("text")},
                      "commissioned_by": f"the human's word at {rid} "
                                         f"(0045 sp6 — the commission)",
                      "born_of": str(knowledge)[:220]}}
    rec = node.make_memory({"did": IMP_DID, "scope": scope}, IMP, scope,
                           body, kind="semantic", tags=["asset", name])
    call(port, "POST", "/records", rec)
    _GOV_CACHE["at"] = 0.0
    call(port, "POST", "/requests/resolve",
         {"id": rid, "status": "staged",
          "result": {"held": f"THE {ckind.upper()} STANDS — “{name}” v1 in "
                             f"the registry ({rec['id'][:16]}…), born of the "
                             f"librarian's gathering and the factory's "
                             f"metered draft. Welcome it, or leave it standing",
                     "record": rec["id"], "name": name}})
    print(f"  🏭 commission {rid}: “{name}” v1 STANDS — the gate waits "
          f"for the welcome")


def on_release(port: int, scope: str, r: dict) -> None:
    """0045 sp3 — CANON CHANGE = EPOCH RELEASE (JB's lock): the firmware
    edit stages a release showing blue (the standing machine) and green
    (the would-be head); the human's word lands the record, and the next
    beat cuts the new name WITH that word standing — the watchdog stays
    quiet only on this path. becky signs firmware, as at genesis."""
    rid = str(r.get("id") or "")
    name = str(r.get("name") or "")

    def done(reply, **kw):
        call(port, "POST", "/requests/resolve",
             {"id": rid, "status": "done", "result": {"reply": reply, **kw}})

    heads = _craft_heads(port)
    if name not in heads or heads[name][0] != "canon":
        return done(f"“{name}” is not Canon firmware — the chronicle door "
                    f"(✎ propose an edit) is its path. Nothing changed")
    head = heads[name][1]
    text = str(r.get("text") or "")
    if not text.strip():
        return done("a release with no words refuses loudly. Nothing changed")
    if r.get("status") == "pending":
        try:
            eid = json.loads(_epoch_nest(UNIVERSE_SCOPE).read_text()).get("id", "?")
        except Exception:
            eid = "?"
        import re as _re3
        preview = node.make_memory({"did": _BECKY.did, "scope": scope},
                                   _BECKY.kp, scope,
                                   {"firmware": {"name": name, "text": text}},
                                   kind="semantic", tags=["preview"])
        call(port, "POST", "/requests/resolve",
             {"id": rid, "status": "staged",
              "result": {"held": f"BLUE stands: epoch {str(eid)[:19]}… · GREEN "
                                 f"waits: “{name}” would head at "
                                 f"{preview['id'][:19]}… — your word cuts the "
                                 f"release and the machine takes a new name "
                                 f"(0041 · 0045 sp3)"}})
        print(f"  ⚑ release staged: “{name}” — blue stands, green waits ({rid})")
        return
    if r.get("status") == "denied":
        return done("declined — the machine keeps its name, and the record "
                    "keeps that you chose")
    if r.get("status") != "approved":
        return
    import re as _re4
    body = {"firmware": {"name": name, "text": text,
                         "slots": sorted(set(_re4.findall(r"⟦(\w+)⟧", text))),
                         "released_by": f"the human's word at {rid} (0045 sp3)"}}
    if r.get("note"):
        body["firmware"]["note"] = str(r["note"])[:200]
    rec = node.make_memory({"did": _BECKY.did, "scope": scope}, _BECKY.kp,
                           scope, body, kind="semantic",
                           tags=["canon", "firmware", "prompt", f"fw-{name}"])
    rec["derived_from"] = [head]
    call(port, "POST", "/records", rec)
    _CRAFT_CACHE["at"] = 0.0                  # the worker re-reads its firmware
    _GOV_CACHE["at"] = 0.0
    global _EPOCH_LAST
    _EPOCH_LAST = 0.0                         # the cut comes on the next beat
    print(f"  ⚑ RELEASE: “{name}” → {rec['id'][:18]}… — the machine's name "
          f"moves on the next beat, the word standing")
    done(f"THE RELEASE IS CUT — “{name}” wears its new words "
         f"({rec['id'][:16]}…) and the machine takes a new name on the next "
         f"beat, your word standing behind it (the watchdog stays quiet only "
         f"on this path)", record=rec["id"])


def bell_beat(port: int) -> None:
    """The bell tends its own door (0044 sp2): with no standing grant and no
    open card, it ASKS — a human's word opens the last mile, never code."""
    if _bell_consent_head(port) is not None:
        return
    q = call(port, "GET", "/requests").get("requests", [])
    if any(x.get("kind") == "consent" and x.get("bell")
           and x.get("status") in ("pending", "staged") for x in q):
        return
    call(port, "POST", "/requests", {
        "kind": "consent", "bell": True,
        "text": f"the bell asks: may it reach {_BELL_ENDPOINT} beyond the "
                f"glass? witness · gate-age · tamper rings only — revocable, "
                f"content-minimal, every send on the record (0044 §2)"})
    print("  🔔 the bell asks at the gate — the last mile waits for a word")


# ------------------------------------------- 0044 sp3 · the subscribers

_VERIFY_LAST = 0.0
VERIFY_EVERY = int(os.environ.get("ORRETH_VERIFY_EVERY_S", "3600"))
_GATE_AGE_H = float(os.environ.get("ORRETH_BELL_GATE_AGE_H", "48"))


def _age_seconds(at) -> float:
    try:
        return bell_mod._seconds_between(str(at), NOW())
    except Exception:
        return 0.0


def _standing_deeds(port: int) -> dict:
    """The published estate per path: the LAST attempt wins (the shelf is
    oldest-first) — comp=True means deliberately gone, and gone things are
    not verified in v1."""
    last: dict[str, dict] = {}
    for _, b, _, _ in wire_assets(port, "attempt"):
        a = b.get("attempt") if isinstance(b, dict) else None
        m = (a or {}).get("manifests") or {}
        if m.get("path"):
            last[m["path"]] = a
    return {p: a for p, a in last.items()
            if not (a.get("manifests") or {}).get("comp")}


# blindness ≠ betrayal (JB's find, 2026-08-10): consecutive failed LOOKS per
# path; the tamper card requires SIGHT of a wrong world, never a dark wire.
_VERIFY_BLIND: dict[str, int] = {}
VERIFY_BLIND_LOOKS = 3


def verify_beat(port: int) -> None:
    """0042's deferral, standing at last (L-B): observation-only — no hand
    moves, so no word is asked just to LOOK. Every standing deed is fetched
    back and compared to its sworn key; the observation lands either way.
    Only a wrong world SEEN wakes the human: a tamper ring + the walk-back
    card at the gate (staged, never enacted — 0042 §5 holds). A wire that
    would not answer is the observer's own condition — noted without a
    lever after patient looks, never dressed as a tamper."""
    global _VERIFY_LAST
    if time.time() - _VERIFY_LAST < VERIFY_EVERY:
        return
    _VERIFY_LAST = time.time()
    seat_kp, seat_did = lib_seat(UNIVERSE_SCOPE)
    for path, a in _standing_deeds(port).items():
        art = path.split("/", 1)[1] if "/" in path else path
        expected = a.get("key")
        fetched, status = None, "unreachable"
        try:
            with urllib.request.urlopen(f"{DEED_SITE}/{path}",
                                        timeout=8) as resp:
                fetched = crypto.content_hash(
                    {"artifact": art, "content": resp.read().decode()})
                status = "found"
        except Exception as e:
            status = str(e)[:60]
        holds = fetched == expected
        call(port, "POST", "/records",
             _deed_rec(seat_kp, seat_did, UNIVERSE_SCOPE, "observation",
                       {"deed": a.get("deed"), "standing": True,
                        "found": {"status": status, "hash": fetched},
                        "holds": holds, "at": NOW()}))
        if holds:
            _VERIFY_BLIND.pop(path, None)     # sighted and true — all clear
            continue
        if status != "found":
            # JB's find (2026-08-10, req-579): a network hiccup left the
            # watchman BLIND and this path judged blindness as betrayal —
            # an UNPUBLISH card staged for an intact deed. A failed
            # observation is not an observation of a wrong world (0042 §4):
            # blindness speaks in its own words, wears no lever, and only
            # after patient looks — the tamper path below needs SIGHT.
            n = _VERIFY_BLIND[path] = _VERIFY_BLIND.get(path, 0) + 1
            print(f"  👁 the standing verify is BLIND for /{path} "
                  f"(look {n}): {status}")
            if n == VERIFY_BLIND_LOOKS:
                try:
                    card = call(port, "POST", "/requests", {
                        "kind": "verify-blind",
                        "text": sentence(port, "card-verify-blind",
                                         path=path, looks=n, error=status)})
                    call(port, "POST", "/requests/resolve",
                         {"id": card["id"], "status": "done",
                          "result": {"reply": sentence(
                              port, "card-verify-blind-reply")}})
                except Exception as e:
                    print(f"    (blind note stumbled: {e})")
            continue
        _VERIFY_BLIND.pop(path, None)         # SIGHTED, and the world is wrong
        print(f"  ⚠ the standing verify DISAGREES for /{path} — "
              f"observed {status} [{str(fetched)[7:19]}…]")
        q = call(port, "GET", "/requests").get("requests", [])
        if not any(x.get("kind") == "publish" and x.get("comp")
                   and x.get("artifact") == art
                   and x.get("status") in ("pending", "staged") for x in q):
            call(port, "POST", "/requests",
                 {"kind": "publish", "comp": True, "artifact": art,
                  "text": sentence(port, "card-verify-tamper", path=path)})
        ring_bell(port, {"kind": "tamper", "scope": UNIVERSE_SCOPE,
                         "subject": f"/{path}", "age": _age_of(a.get("at")),
                         "pointer": _CONSOLE_URL})


def gate_age_beat(port: int) -> None:
    """Consequence that has waited past the declared age rings ONCE — the
    oldest card only, at most one gate-age ring a day: the pointer leads to
    the whole queue, and a bell that lists every gate is noise (law 6).
    witness cards are excluded — that kind already has its own voice."""
    b = _bell_service(port)
    for (kind, _), v in b.rung.items():
        if kind == "gate-age" and _age_seconds(v["at"]) < 86400:
            return
    # the whole rig's queues — the bell must agree with the room's gate-wait
    # panel (rule 7, one picture): aged consequence on ANY floor is the news
    old: list[tuple[dict, str]] = []
    for p in set([*FLOORS, *SHIPYARD.floors()]):
        try:
            scope = FLOOR_SCOPES.get(p) or call(p, "GET", "/health")["scope"]
            for x in call(p, "GET", "/requests").get("requests", []):
                if ((x.get("status") == "staged"
                     or (x.get("kind") == "question"
                         and x.get("status") == "pending"))
                        and x.get("kind") != "witness"
                        and _age_seconds(x.get("at")) >= _GATE_AGE_H * 3600):
                    old.append((x, scope))
        except Exception:
            continue
    if not old:
        return
    oldest, where = min(old, key=lambda t: str(t[0].get("at") or ""))
    ring_bell(port, {"kind": "gate-age", "scope": where,
                     "subject": f"{oldest['id']} at {where}",
                     "age": _age_of(oldest.get("at")),
                     "pointer": _CONSOLE_URL})


# ---- 0047 sp3 · the studio's readings ride onto the plan cards ------------------------
STUDIO_DARK_S = int(os.environ.get("ORRETH_STUDIO_DARK_S", "90"))

# The 0047 lock-4 label retired 0051 sp1 (req-622, JB's word): it now lives
# on the shelf as «plan-fallback-label» — quinn called the old words poetry,
# and the human who wrote them agreed. Use sites speak via sentence().


def studio_tend(port: int) -> None:
    """The plan card carries what the universe UNDERSTOOD — or its honest
    absence (0047 sp3). The gate never waits on the studio: cards stage
    instantly; this beat attaches the reading when the mind answers, and
    past the deadline labels the silence dark. A late reading still lands
    while the card stands at the gate (dark → read is an upgrade, never a
    rewrite of history — the leg's own record keeps the times)."""
    try:
        reqs = call(port, "GET", "/requests").get("requests", [])
    except Exception:
        return
    scope = FLOOR_SCOPES.get(port) or UNIVERSE_SCOPE
    by_id = {q.get("id"): q for q in reqs}
    for r in reqs:
        if r.get("kind") != "objective" or r.get("status") != "staged":
            continue
        res = r.get("result") or {}
        u = res.get("understanding") or {}
        pb = res.get("planned_by") or {}
        if u.get("state") == "asked" and u.get("leg"):
            leg = by_id.get(u["leg"])
            if (leg and leg.get("status") == "done"
                    and (leg.get("result") or {}).get("understanding")):
                read = dict(leg["result"]["understanding"])
                read.setdefault("state", "read")
                # 0047 sp4 — the chain: a mind that has READ may now PLAN.
                # The draft leg carries the reading and the legal seats; the
                # card declares "drafting" while the fallback keeps standing
                update = {**res, "understanding": read}
                # 0047 sp5 — the gap is fuel: a reading that names a lack
                # offers to GROW the craft, unchecked by default (0032 §4)
                goffer = fingertip.gap_offer(read)
                if goffer:
                    update["gap_offer"] = goffer
                if read["state"] == "read" and pb.get("state") == "fallback":
                    seats = [s for p, s in sorted(FLOOR_SCOPES.items())
                             if s != scope]
                    try:
                        draft = call(port, "POST", "/requests", {
                            "kind": "plan-draft", "of": r["id"],
                            "objective": (res.get("plan") or {}).get("objective")
                                          or r.get("text") or "",
                            "rubric": str(r.get("rubric") or ""),
                            "reading": read.get("reading") or "",
                            "seats": seats,
                            "text": f"the studio drafts the plan for {r['id']}"})["id"]
                        update["planned_by"] = {"state": "drafting",
                                                "leg": draft,
                                                "asked_at": NOW(),
                                                "label": sentence(port, "plan-fallback-label")}
                    except Exception as e:
                        print(f"    (plan-draft leg failed to post: {e})")
                call(port, "POST", "/requests/resolve",
                     {"id": r["id"], "status": "staged", "result": update})
                print(f"  🧠 the studio read {r['id']}: "
                      f"“{str(read.get('reading', read.get('why', '')))[:64]}”"
                      + (f" · confidence {read.get('confidence')}"
                         if "confidence" in read else ""))
            elif _age_seconds(u.get("asked_at")) > STUDIO_DARK_S:
                call(port, "POST", "/requests/resolve",
                     {"id": r["id"], "status": "staged",
                      "result": {**res,
                                 "understanding": {**u, "state": "dark",
                                                   "note": "the studio is dark — "
                                                           "staged without a "
                                                           "reading"}}})
                print(f"  🧠 the studio stayed dark for {r['id']} — the card says so")
            continue
        # ---- sp4: the draft returns — the save gate decides, never the mind
        if pb.get("state") == "drafting" and pb.get("leg"):
            leg = by_id.get(pb["leg"])
            done = (leg and leg.get("status") == "done"
                    and (leg.get("result") or {}).get("plan"))
            if done:
                draft = leg["result"]["plan"]
                if draft.get("state") == "parked":
                    call(port, "POST", "/requests/resolve",
                         {"id": r["id"], "status": "staged",
                          "result": {**res, "planned_by": {
                              "state": "parked", "why": draft.get("why", ""),
                              "label": sentence(port, "plan-fallback-label")}}})
                    print(f"  🗺 the studio's plan for {r['id']} PARKED — "
                          "the fallback stands, labeled")
                    continue
                try:
                    newplan = fingertip.author_plan(
                        scope, req_id=r["id"],
                        objective=(res.get("plan") or {}).get("objective")
                                   or r.get("text") or "",
                        proposals=draft.get("intentions"),
                        floors=[s for p, s in FLOOR_SCOPES.items()],
                        budget=int(r.get("budget") or 2400))
                except fingertip.WorkflowError as e:
                    call(port, "POST", "/requests/resolve",
                         {"id": r["id"], "status": "staged",
                          "result": {**res, "planned_by": {
                              "state": "refused", "why": str(e),
                              "label": sentence(port, "plan-fallback-label")}}})
                    print(f"  🗺 the studio's plan for {r['id']} REFUSED AT "
                          f"SAVE: {e} — the fallback stands, labeled")
                    continue
                me = {"did": ORCH_DID, "scope": scope}
                rec = make_memory(me, ORCH, scope, {"plan": newplan},
                                  kind="semantic",
                                  tags=["plan",
                                        *fingertip.coordinate_tags(newplan["goal"])])
                rec["coordinate"] = fingertip.coordinate(objective=newplan["goal"])
                if res.get("plan_record"):
                    rec["derived_from"] = [res["plan_record"]]   # lineage, never rewrite
                try:
                    call(port, "POST", "/records", rec)
                except Exception as e:
                    print(f"    (mind-plan record write failed: {e})")
                beyond = sum(1 for i in newplan["intentions"]
                             if i.get("beyond_token"))
                summary = (f"{len(newplan['intentions'])} intention(s) → "
                           + ", ".join(i["seat"].split("/")[-1]
                                       for i in newplan["intentions"][:6])
                           + " · asks you 1 question"
                           + (f" · {beyond} beyond this token (will ask leave)"
                              if beyond else ""))
                _PLANS[r["id"]] = newplan
                call(port, "POST", "/requests/resolve",
                     {"id": r["id"], "status": "staged",
                      "result": {**res, "plan": newplan, "plan_record": rec["id"],
                                 "plan_summary": summary,
                                 "graph": fingertip.choreography(newplan),
                                 "planned_by": {"state": "mind",
                                                "spec": newplan["spec"],
                                                "by": draft.get("by", ""),
                                                "why": draft.get("why", ""),
                                                "label": "planned by the studio"}}})
                print(f"  🗺 the studio PLANNED {r['id']}: {summary} · "
                      f"spec {newplan['spec'][:22]}… — the fallback retires")
            elif _age_seconds(pb.get("asked_at")) > STUDIO_DARK_S:
                call(port, "POST", "/requests/resolve",
                     {"id": r["id"], "status": "staged",
                      "result": {**res, "planned_by": {
                          "state": "fallback", "label": sentence(port, "plan-fallback-label"),
                          "note": "the studio read but never planned"}}})
                print(f"  🗺 the studio read but never planned {r['id']} — "
                      "the fallback stands, labeled")


# ---- 0047 sp6 · the standing doors: the schedule and the reflex -----------------------
from orreth_sim import standing as standing_law  # noqa: E402


def _standing_load(name: str) -> dict:
    try:
        with open(os.path.join(FlightBook.HOME, name + ".json")) as f:
            return json.load(f)
    except Exception:
        return {}


def _standing_save(name: str, rows: dict) -> None:
    try:
        os.makedirs(FlightBook.HOME, exist_ok=True)
        with open(os.path.join(FlightBook.HOME, name + ".json"), "w") as f:
            json.dump(rows, f, indent=1)
    except Exception:
        pass


def _reflex_seat(scope: str):
    kp = _seed("reflex-" + scope.replace("/", "~"))
    return {"did": crypto.did_key_for(kp.public), "scope": scope}, kp


def on_standing_charter(port: int, scope: str, r: dict, *, approved: bool,
                        declined: bool) -> None:
    """The Schedule (0047 sp6, JB's vector): an Objective ASSIGNED to a
    machine — the charter approved ONCE, then the MACHINE owns the cadence.
    Malformed charters refuse at the gate, never at firing time."""
    rid = str(r.get("id") or "")
    if r.get("status") == "pending":
        try:
            every = max(int(r.get("every_s") or 0), 30)
            budget = int(r.get("budget") or 1200)
            cap = max(int(r.get("max_instances") or 3), 1)
            text = str(r.get("text") or "").strip()
            who = str(r.get("assigned_to") or "the orchestrator").strip()
            assert text
        except Exception:
            call(port, "POST", "/requests/resolve",
                 {"id": rid, "status": "done",
                  "result": {"refused": "a charter declares text, every_s, "
                                        "budget, max_instances — refused"}})
            return
        call(port, "POST", "/requests/resolve",
             {"id": rid, "status": "staged",
              "result": {"held": "the machine's standing duty waits for your "
                                 "ONE word — then it owns the cadence",
                         "terms": f"“{text[:64]}” · assigned to {who} · every "
                                  f"{every}s · {budget} tokens/instance · at "
                                  f"most {cap} instance(s), then the charter "
                                  "RESTS at this gate for renewal"}})
        return
    if approved:
        rows = _standing_load("charters")
        rows[rid] = {"text": str(r.get("text")), "assigned_to":
                     str(r.get("assigned_to") or "the orchestrator"),
                     "every_s": max(int(r.get("every_s") or 0), 30),
                     "budget": int(r.get("budget") or 1200),
                     "max_instances": max(int(r.get("max_instances") or 3), 1),
                     "rubric": str(r.get("rubric") or ""),
                     "active": True, "fired": 0}
        _standing_save("charters", rows)
        seat = {"did": ORCH_DID, "scope": scope}
        rec = node.make_memory(seat, ORCH, scope,
                               {"standing_charter": {**rows[rid], "id": rid,
                                                     "approved_by": "the human's word"}},
                               kind="semantic", tags=["standing-charter"])
        try:
            call(port, "POST", "/records", rec)
        except Exception:
            pass
        call(port, "POST", "/requests/resolve",
             {"id": rid, "status": "done",
              "result": {"reply": "the charter stands — the machine owns the "
                                  "cadence now; it rests at this gate when "
                                  "its instances are spent"}})
        print(f"  🕰 charter {rid} STANDS: “{str(r.get('text'))[:56]}” — "
              "the machine's duty, the human's one word behind it")
    elif declined:
        call(port, "POST", "/requests/resolve",
             {"id": rid, "status": "done",
              "result": {"reply": "unchartered, on the record"}})


def on_reflex(port: int, scope: str, r: dict, *, approved: bool,
              declined: bool) -> None:
    """The Trigger (0047 sp6, JB's vector): the reflex arc — when X, then Y,
    Y wearing exactly observe | escalate | act. An unreadable reflex refuses
    at DECLARATION, never surprises at firing."""
    rid = str(r.get("id") or "")
    if r.get("status") == "pending":
        try:
            assert (r.get("when") or {}).get("kind") == "record-tagged"
            assert (r.get("when") or {}).get("tag")
            standing_law.reflex_response({"then": r.get("then")}, "sha256:probe")
        except Exception as e:
            call(port, "POST", "/requests/resolve",
                 {"id": rid, "status": "done",
                  "result": {"refused": f"the reflex could not be read: {e}"}})
            return
        then = r.get("then") or {}
        call(port, "POST", "/requests/resolve",
             {"id": rid, "status": "staged",
              "result": {"held": "a reflex waits for your word — when it "
                                 "fires, it answers with "
                                 f"{then.get('shape')} (0047 sp6)",
                         "terms": f"when a record tagged "
                                  f"“{(r.get('when') or {}).get('tag')}” lands"
                                  f" → {then.get('shape')}"}})
        return
    if approved:
        rows = _standing_load("reflexes")
        rows[rid] = {"when": r.get("when"), "then": r.get("then"),
                     "active": True, "last_seen": NOW()}
        _standing_save("reflexes", rows)
        seat, kp = _reflex_seat(scope)
        rec = node.make_memory(seat, kp, scope,
                               {"reflex": {**rows[rid], "id": rid,
                                           "approved_by": "the human's word"}},
                               kind="semantic", tags=["reflex"])
        try:
            call(port, "POST", "/records", rec)
        except Exception:
            pass
        call(port, "POST", "/requests/resolve",
             {"id": rid, "status": "done",
              "result": {"reply": "the reflex is live — it hears only what "
                                  "lands AFTER this word, never history"}})
        print(f"  ⚡ reflex {rid} LIVE: when “{(r.get('when') or {}).get('tag')}”"
              f" → {(r.get('then') or {}).get('shape')}")
    elif declined:
        call(port, "POST", "/requests/resolve",
             {"id": rid, "status": "done",
              "result": {"reply": "no reflex, on the record"}})


def schedule_beat(port: int) -> None:
    """The machine's cadence (0047 sp6): due charters fire instance
    objectives — each a NORMAL governed objective in the visible queue,
    approved by the charter's standing word, metered inside its budget —
    and a spent charter RESTS with a renewal card, never a silent stop."""
    rows = _standing_load("charters")
    if not rows:
        return
    changed = False
    for cid, ch in rows.items():
        if standing_law.charter_resting(ch) and not ch.get("rest_carded"):
            try:
                call(port, "POST", "/requests", {
                    "kind": "assay", "to": "human",
                    "text": f"the charter {cid} spent its "
                            f"{ch['max_instances']} instance(s) — it RESTS; "
                            "renew it with a new charter at this gate"})
                ch["rest_carded"], changed = True, True
                print(f"  🕰 charter {cid} RESTS — instances spent, the "
                      "renewal is yours")
            except Exception:
                pass
            continue
        if standing_law.charter_due(ch, time.time()):
            try:
                inst = call(port, "POST", "/requests", {
                    "kind": "objective", "text": ch["text"],
                    "charter": cid, "budget": ch["budget"],
                    **({"rubric": ch["rubric"]} if ch.get("rubric") else {})})
                ch["fired"] = int(ch.get("fired", 0)) + 1
                ch["last_fired_s"] = time.time()
                changed = True
                print(f"  🕰 charter {cid} fires instance {ch['fired']}/"
                      f"{ch['max_instances']}: {inst['id']}")
            except Exception as e:
                print(f"    (charter instance failed to post: {e})")
    if changed:
        _standing_save("charters", rows)
    # the charter's standing word approves its own staged instances —
    # visibly, in the queue, exactly where a human's word would sit
    try:
        reqs = call(port, "GET", "/requests").get("requests", [])
    except Exception:
        return
    for q in reqs:
        if (q.get("kind") == "objective" and q.get("status") == "staged"
                and q.get("charter") in rows
                and rows[q["charter"]].get("active")):
            call(port, "POST", "/requests/resolve",
                 {"id": q["id"], "status": "approved",
                  "result": {**(q.get("result") or {}),
                             "approved_by": f"the charter's word ({q['charter']})"}})
            print(f"  🕰 instance {q['id']} approved by the charter's "
                  "standing word — no human click, exactly as chartered")


def reflex_beat(port: int) -> None:
    """The reflex arc (0047 sp6): active reflexes hear NEW records wearing
    their tag and answer in their declared shape — observation, escalation
    (the bell, never a lever), or a governed act posted to the queue."""
    rows = _standing_load("reflexes")
    if not rows:
        return
    scope = FLOOR_SCOPES.get(port) or UNIVERSE_SCOPE
    changed = False
    for rid, rx in rows.items():
        if not rx.get("active"):
            continue
        tag = (rx.get("when") or {}).get("tag")
        where = (rx.get("when") or {}).get("scope") or scope
        try:
            rows2 = call(port, "POST", "/retrieve", {
                "query": {"requester": IMP_DID,
                          "subject": {"cohort": {"scope": where}},
                          "space": "self", "time": {"from": rx["last_seen"]},
                          "intent": "recall", "budget": {"cost": 8},
                          "auth": "biscuit-sim"},
                "token": _ROOT.issue_token(IMP_DID, "u:demo",
                                           [{"action": "retrieve",
                                             "space": "self"}]),
                "requester_scope": where}).get("hits", [])
        except Exception:
            continue
        fresh = [h for h in rows2
                 if tag in (h.get("tags") or [])
                 and str(h.get("occurred_at", "")) > str(rx["last_seen"])][:3]
        for h in fresh:
            try:
                out = standing_law.reflex_response(
                    {"id": rid, "then": rx.get("then")}, h["ref"])
            except ValueError as e:
                print(f"    (reflex {rid} unreadable at fire: {e})")
                continue
            if out["shape"] == "observe":
                seat, kp = _reflex_seat(scope)
                rec = node.make_memory(
                    seat, kp, scope,
                    {"reflex_observation": {"reflex": rid, "of": h["ref"],
                                            "note": out["note"]}},
                    kind="semantic", tags=["reflex-observation"])
                rec["derived_from"] = [h["ref"]]
                try:
                    call(port, "POST", "/records", rec)
                    print(f"  ⚡ reflex {rid} OBSERVED [{h['ref'][:18]}…] — "
                          "a finding on the record")
                except Exception as e:
                    print(f"    (reflex observation refused: {e})")
            elif out["shape"] == "escalate":
                try:
                    card = call(port, "POST", "/requests", {
                        "kind": "reflex-escalation",
                        "text": sentence(port, "card-reflex-escalation",
                                         event=out["text"],
                                         ref=h["ref"][:22])})
                    call(port, "POST", "/requests/resolve",
                         {"id": card["id"], "status": "staged",
                          "result": {"held": sentence(
                              port, "card-reflex-escalation-held")}})
                    ring_bell(port, {"kind": "reflex", "scope": scope,
                                     "subject": out["text"][:60],
                                     "pointer": _CONSOLE_URL})
                    print(f"  ⚡ reflex {rid} ESCALATED — the card stages, "
                          "the bell rings, no lever moves")
                except Exception as e:
                    print(f"    (reflex escalation stumbled: {e})")
            elif out["shape"] == "act":
                try:
                    act = dict(out["request"])
                    act["text"] = (str(act.get("text") or "")
                                   + f" (reflex {rid}, of {h['ref'][:22]}…)")
                    acted = call(port, "POST", "/requests", act)
                    print(f"  ⚡ reflex {rid} ACTED — a governed "
                          f"{act.get('kind')} posted: {acted['id']}")
                except Exception as e:
                    print(f"    (reflex act refused: {e})")
            if str(h.get("occurred_at", "")) > str(rx["last_seen"]):
                rx["last_seen"] = h["occurred_at"]
                changed = True
    if changed:
        _standing_save("reflexes", rows)


# 0048 sp3 — the routing's live memory: feedback id → its classify leg (this
# process). The durable guard is the resolution record itself: a routed
# feedback is never open again; a restart merely re-asks an unanswered leg.
_FEEDBACK_LEGS: dict[str, str] = {}
_FEEDBACK_DARK: set[str] = set()


def wire_open_feedback(port: int, scope: str) -> list[dict]:
    """The unanswered words from the wire — sp1's open_feedback, wire twin:
    open feedback records with no resolution deriving from them, read under
    the librarian's seat like the desk's ledger (0032 §1's pattern)."""
    from datetime import datetime, timedelta, timezone
    _, seat_did = lib_seat(scope)
    token = _ROOT.issue_token(seat_did, "u:demo",
                              [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc) - timedelta(days=90)).strftime(
        "%Y-%m-%dT%H:%M:%SZ")
    try:
        r = call(port, "POST", "/retrieve", {
            "query": {"requester": seat_did, "subject": {"cohort": {"scope": scope}},
                      "space": "self", "time": {"from": frm}, "intent": "recall",
                      "budget": {"cost": 8}, "auth": "biscuit-sim"},
            "token": token, "requester_scope": scope})
    except Exception:
        return []
    rows, resolved = [], set()
    for h in r.get("hits", []):
        tags = h.get("tags") or []
        if "feedback" not in tags:
            continue
        if "resolution" in tags:
            resolved.update(h.get("derived_from") or [])
            continue
        try:
            body = call(port, "GET",
                        f"/records/{urllib.parse.quote(h['ref'], safe='')}/body")
        except Exception:
            continue
        fb = (body or {}).get("feedback") or {}
        if fb.get("state") == "open":
            rows.append({"id": h["ref"], "at": h.get("occurred_at", ""), **fb})
    rows.sort(key=lambda x: x["at"])
    return [x for x in rows if x["id"] not in resolved]


def feedback_beat(port: int) -> None:
    """0048 sp3 — the words go back into the machine: each open feedback is
    READ by the studio (the typed route — one re-ask upstream, honest park)
    and lands at the organ that can answer it; the resolution sibling names
    what the words became (OUTCOME_FOR — the craft route lands EVIDENCE,
    0031 §4, never an auto-proposal). The mind proposes; every consequential
    landing still waits at a human gate. V1 sweeps the universe floor — the
    glass posts thumbs there; the whole-rig sweep is a named gap."""
    scope = UNIVERSE_SCOPE
    open_rows = wire_open_feedback(port, scope)
    if not open_rows:
        return
    try:
        reqs = call(port, "GET", "/requests").get("requests", [])
    except Exception:
        return
    by_id = {q.get("id"): q for q in reqs}
    me = {"did": ORCH_DID, "scope": scope}
    reg_names: set[str] = set()
    try:
        reg_names = {o["name"] for o in compose_governance().get("objects", [])}
    except Exception:
        pass
    for fb in open_rows[:2]:                  # two words a beat — no storms
        leg = by_id.get(_FEEDBACK_LEGS.get(fb["id"], ""))
        if leg is None:
            try:
                judged = call(port, "GET", "/records/"
                              + urllib.parse.quote(str(fb.get("of") or ""),
                                                   safe="") + "/body")
            except Exception:
                judged = {}
            try:
                leg_id = call(port, "POST", "/requests", {
                    "kind": "classify-feedback", "of": fb["id"],
                    "quoted": fb.get("quoted", ""),
                    "context": str(judged)[:600],
                    "charters": CHARTERS_ROSTER,
                    "text": "the studio reads the human's words on "
                            f"[{fb['id'][:18]}…]"})["id"]
                _FEEDBACK_LEGS[fb["id"]] = leg_id
                print(f"  🧭 feedback [{fb['id'][:18]}…] → the studio reads "
                      f"({leg_id})")
            except Exception as e:
                print(f"    (classify leg failed to post: {e})")
            continue
        if leg.get("status") != "done":
            if (_age_seconds(leg.get("at")) > STUDIO_DARK_S
                    and fb["id"] not in _FEEDBACK_DARK):
                _FEEDBACK_DARK.add(fb["id"])  # honest, once: the word WAITS
                print(f"  🧭 the studio is dark for [{fb['id'][:18]}…] — "
                      "the human's words stay open, never dropped")
            continue
        route = (leg.get("result") or {}).get("route") or {}
        why = str(route.get("why") or "")
        target = str(route.get("target") or "")
        outcome, ref = "", ""
        if route.get("state") == "parked" or not route.get("route"):
            outcome = "parked"
            why = why or "the mind could not type the lack — the words wait"
        elif route["route"] == "gap":
            try:
                ref = call(port, "POST", "/requests", {
                    "kind": "commission", "craft_kind": "skill",
                    "born_of": fb["id"],
                    "text": "grow the craft the human's words found lacking "
                            f"(born of [{fb['id'][:18]}…]): {target or why}"})["id"]
            except Exception as e:
                print(f"    (feedback commission failed: {e})")
                continue
        elif route["route"] == "execution":
            try:
                ref = call(port, "POST", "/requests", {
                    "kind": "objective", "born_of": fb["id"],
                    "text": f"repair — {target or 'the judged work'}",
                    # the human's own words become the yardstick (0043 G6)
                    "rubric": str(fb.get("quoted") or "")[:200]})["id"]
            except Exception as e:
                print(f"    (repair objective failed to post: {e})")
                continue
        elif route["route"] == "charter":
            note = make_memory(me, ORCH, scope,
                               {"referral": {"of": fb["id"], "keeper": target,
                                             "note": why}},
                               kind="semantic", tags=["feedback-referral"])
            note["derived_from"] = [fb["id"]]
            try:
                call(port, "POST", "/records", note)
                ref = note["id"]
            except Exception as e:
                print(f"    (referral note failed to land: {e})")
                continue
        elif route["route"] == "craft":
            # 0031 §4's own door: the words land VERBATIM as evidence against
            # the named craft — the smith must carry them, never auto-adopt.
            name = target if target in reg_names else "resident-voice"
            evid = make_memory(me, ORCH, scope,
                               {"feedback": {"asset": name,
                                             "quoted": str(fb.get("quoted")
                                                           or "")[:400]}},
                               kind="semantic", tags=["asset-feedback", name])
            evid["derived_from"] = [fb["id"]]
            try:
                call(port, "POST", "/records", evid)
                ref = evid["id"]
                if name != target:
                    why = (why + " — landed against «resident-voice», the "
                           f"speaking craft (no registry object named "
                           f"“{target}”)").strip(" —")
            except Exception as e:
                print(f"    (craft evidence failed to land: {e})")
                continue
        if not outcome:
            outcome = thumb_mod.OUTCOME_FOR[route["route"]]
        try:
            res_rec = thumb_mod.resolve_feedback(
                me, ORCH, scope, {"id": fb["id"], "of": fb.get("of", "")},
                outcome=outcome, ref=ref, why=why)
            call(port, "POST", "/records", res_rec)
        except Exception as e:
            print(f"    (feedback resolution failed: {e})")
            continue
        _FEEDBACK_LEGS.pop(fb["id"], None)
        _FEEDBACK_DARK.discard(fb["id"])
        print(f"  🧭 feedback [{fb['id'][:18]}…] {outcome.upper()}"
              + (f" → {ref[:22]}…" if ref else "")
              + (f" — {why[:64]}" if why else ""))
        # sp4 (L3) — CLOSURE: the outcome always lands as a card on the
        # author's own queue; the bell decides for itself under STANDING
        # consent (0044's one law — no new grant, no new machinery).
        try:
            card = call(port, "POST", "/requests", {
                "kind": "feedback-closure", "of": fb["id"],
                "text": sentence(port, "card-feedback-closure",
                                 outcome=speech.OUTCOME_SPOKEN.get(outcome,
                                                                   outcome))
                        + (sentence(port, "card-feedback-closure-ref",
                                    ref=ref[:22]) if ref else "")
                        + (sentence(port, "card-feedback-closure-why",
                                    why=why[:110]) if why else "")})
            call(port, "POST", "/requests/resolve",
                 {"id": card["id"], "status": "done",
                  "result": {"reply": sentence(
                                 port, "card-feedback-closure-reply"),
                             "feedback": fb["id"], "outcome": outcome,
                             **({"ref": ref} if ref else {})}})
            ring_bell(port, {"kind": "feedback-closure", "scope": scope,
                             "subject": f"your feedback: {outcome}",
                             "pointer": _CONSOLE_URL})
        except Exception as e:
            print(f"    (closure card stumbled: {e})")


# sp4 — the calibration's own cadence and memory: whole-rig verdict sweeps
# are priced work, so they ride a slow beat; the state prints only when it
# CHANGES, and one open finding bars a second (no storms — 0028's precedent).
CAL_EVERY = 120
_CAL_LAST = 0.0
_CAL_STATE: tuple = ()


def calibration_beat(port: int) -> None:
    """0048 sp4 (L2): the human's thumbs are ground truth for the examiner —
    where both judged the SAME work, the disagreement is the news, behind
    min-n so one thumb never indicts vera. A finding is a staged card citing
    its widest gaps; detection wears no levers (0043 law 3)."""
    global _CAL_LAST, _CAL_STATE
    if time.time() - _CAL_LAST < CAL_EVERY:
        return
    _CAL_LAST = time.time()                  # set early — never hot-loop
    rows: list[dict] = []
    for p, s in sorted(FLOOR_SCOPES.items()):
        try:
            for _, body, _, _tags in wire_assets(p, "verdict", scope=s):
                a = (body or {}).get("assay") or {}
                if a.get("of"):
                    rows.append({"of": a["of"],
                                 "score": float(a.get("score") or 0.0),
                                 "human": a.get("judge_floor") == "human"})
        except Exception:
            continue                          # a dark floor never stops the sweep
    out = thumb_mod.calibration(rows)
    state = (out["pairs"], out["mean_gap"], out["news"])
    if state != _CAL_STATE:
        _CAL_STATE = state
        print(f"  ⚖ calibration: {out['pairs']} pair(s) of {out['min_n']} · "
              f"mean gap {out['mean_gap']}"
              + (" — NEWS" if out["news"] else " — the tongue is held"))
    if not out["news"]:
        return
    try:
        reqs = call(port, "GET", "/requests").get("requests", [])
    except Exception:
        return
    cals = [q for q in reqs if q.get("kind") == "calibration"]
    if any(q.get("status") == "staged" for q in cals):
        return                                # one argument at a time
    # JB's find (2026-08-09, minutes after the first live card): approving
    # the finding immediately birthed its twin — the shelf still disagreed
    # and this guard watched only STAGED cards. The human's word now
    # SETTLES the argument: a new card stages only when the argument
    # itself has changed (new pairs, or a moved gap).
    last = max(cals, key=lambda q: str(q.get("at", "")), default=None)
    if last is not None:
        prev = (last.get("result") or {}).get("calibration") or {}
        if (prev.get("pairs"), prev.get("mean_gap")) == \
                (out["pairs"], out["mean_gap"]):
            return                            # the same argument, already worded
    # sp2 (0050): the card shows the WORK, not the hash — a glimpse of each
    # disputed piece rides the pair fragment; the words live on the shelf
    def _work_glimpse(of: str) -> str:
        try:
            b = call(port, "GET", "/records/"
                     + urllib.parse.quote(of, safe="") + "/body") or {}
        except Exception:
            return of[:20] + "…"              # unreadable — the hash, honestly
        for path_keys in (("outcome", "answer"), ("objective_outcome",
                                                  "objective"),
                          ("exchange", "reply"), ("audience", "asked")):
            v = (b.get(path_keys[0]) or {})
            if isinstance(v, dict) and v.get(path_keys[1]):
                return str(v[path_keys[1]])[:60]
        return str(b)[:60]
    ex = " · ".join(sentence(port, "card-calibration-pair",
                             work=_work_glimpse(p["of"]),
                             human=p["human"], examiner=p["examiner"])
                    for p in out["sample"][:3])
    try:
        card = call(port, "POST", "/requests", {
            "kind": "calibration",
            "text": sentence(port, "card-calibration", pairs=out["pairs"],
                             mean_gap=out["mean_gap"], bar=out["bar"],
                             examples=ex)})
        call(port, "POST", "/requests/resolve",
             {"id": card["id"], "status": "staged",
              "result": {"held": sentence(port, "card-calibration-held"),
                         "calibration": out}})
        ring_bell(port, {"kind": "calibration", "scope": UNIVERSE_SCOPE,
                         "subject": f"human vs examiner: gap {out['mean_gap']}",
                         "pointer": _CONSOLE_URL})
        print(f"  ⚖ calibration finding STAGED: {card['id']} — the bell "
              "carries it, no lever moves")
    except Exception as e:
        print(f"    (calibration card stumbled: {e})")


def assay_beat(u_port: int) -> None:
    """The Examiner (0043 §6), dial-gated: only at «assay» does vera sample
    completed work and commission judges — metered under HER did, under the
    DECLARED daily ceiling (G5: the budget the meter shows, then enforces).
    The universe floor always; any floor with a running experiment joins the
    round. Then the experiments' standings turn."""
    global _ASSAY_LAST
    if OBS["dial"] != "assay" or time.time() - _ASSAY_LAST < ASSAY_EVERY:
        return
    _ASSAY_LAST = time.time()
    spent = _vera_spent_today()
    if spent >= ASSAY_CEILING:
        print(f"  🔭 assay: the declared ceiling holds — {spent}/"
              f"{ASSAY_CEILING} tokens today; the examiner rests (G5)")
        return
    # THE WHOLE RIG (sp5, JB's lock): every tended floor wears the examiner —
    # the universe first, then each floor in order; quiet floors cost one
    # read; the ceiling and the dial bound the spend
    targets = [(u_port, UNIVERSE_SCOPE)] + [
        (p, s) for p, s in sorted(FLOOR_SCOPES.items())
        if s != UNIVERSE_SCOPE]
    for port, scope in targets:
        if _vera_spent_today() >= ASSAY_CEILING:
            print(f"  🔭 assay: the ceiling closed mid-round at {scope} — "
                  "the rest of the rig waits for tomorrow (G5)")
            break
        try:
            _assay_floor(port, scope)
        except Exception as ex:
            print(f"    (assay stumbled at {scope}: {ex})")
    experiment_beat(u_port)


def _wire_verdict_standings(port: int, *, scope: str = "u:demo") -> tuple[list, dict]:
    """The verdicts and their standings, read off the shelf — one aggregation
    serving both the beat's cards and the instrument room (sp3)."""
    rows = wire_assets(port, "verdict", scope=scope)
    compact, per = [], {}
    for vref, b, _, _ in rows:
        a = (b or {}).get("assay") or {}
        compact.append({"score": a.get("score"), "why": str(a.get("why", ""))[:90],
                        "judge_floor": a.get("judge_floor", "?"),
                        "work_floor": a.get("work_floor", "?"),
                        "cost": a.get("cost") or {}})
        s = per.setdefault(a.get("work_floor", "?"),
                           {"scores": [], "humans": 0, "refs": []})
        s["scores"].append(float(a.get("score", 0.0)))
        s["refs"].append(vref)
        if a.get("judge_floor") == "human":
            s["humans"] += 1
    stand = {}
    for fl, s in per.items():
        n, half = len(s["scores"]), len(s["scores"]) // 2
        stand[fl] = {"n": n, "mean": round(sum(s["scores"]) / n, 4),
                     "trend": round(sum(s["scores"][half:]) / (n - half)
                                    - sum(s["scores"][:half]) / half, 4)
                     if n >= 4 else None,
                     "humans": s["humans"], "refs": s["refs"]}
    return compact, stand


_OBS_CACHE: dict = {"at": 0.0, "payload": {}}


# ---------------------------------------------------------------- the craft room (0045 sp1)
_GOV_CACHE: dict = {"at": 0.0, "payload": None}


def _craft_heads(port: int) -> dict:
    """name -> (lifecycle, head_ref) off the shelves — the editor's map."""
    heads: dict = {}
    for ref, b, _, _ in wire_assets(port, "firmware"):
        f = (b or {}).get("firmware") or {}
        if f.get("name"):
            heads[f["name"]] = ("canon", ref)
    for ref, _, _, t in wire_assets(port, "asset"):
        name = next((x for x in (t or []) if x not in
                     ("asset", "asset-variant", "adopted")), None)
        if name:
            heads[name] = ("chronicle", ref)
    return heads


def on_craft_edit(port: int, scope: str, r: dict) -> None:
    """0045 sp2 — THE ONE LAW OF CHANGE at the glass door: a human's edit
    lands as a versioned sibling with lineage, adopted on the same click
    (one motion — the request IS the word; grace signs as the shelf's
    keeper and the body names the human's authority). Canon refuses toward
    the release; a bad shape refuses loudly; nothing saves outside the
    grammar."""
    rid = str(r.get("id") or "")

    def done(reply, **kw):
        call(port, "POST", "/requests/resolve",
             {"id": rid, "status": "done", "result": {"reply": reply, **kw}})

    name = str(r.get("name") or "")
    if ORRETH_MODE == "prod":
        # the kernel law (JB, 2026-08-16): in PROD the residents' firmware
        # is READ-ONLY at every studio door — a change rides the release
        # ceremony or it does not ride at all
        return done("PROD refuses the edit door — this machine runs in prod "
                    "mode, where resident firmware is read-only and every "
                    "change is a RELEASE (0045 sp3). Nothing changed")
    heads = _craft_heads(port)
    if name not in heads:
        return done(f"the shelf holds no craft named “{name}” — nothing changed")
    lifecycle, head = heads[name]
    if lifecycle == "canon":
        return done("CANON refuses the chronicle door — this word is firmware: "
                    "a change is a RELEASE and moves the machine's name "
                    "(0041 · 0045 sp3). Nothing changed")
    try:
        parsed = json.loads(str(r.get("text") or ""))
    except Exception as e:
        return done("the edit refuses loudly — the body must be valid JSON "
                    f"({str(e)[:60]}). Nothing changed")
    if isinstance(parsed, dict) and isinstance(parsed.get("asset"), dict):
        parsed = parsed["asset"].get("profile", parsed["asset"])
    if name.startswith("capability-"):
        flaw = cap_manifest_flaw(parsed)
        if flaw:
            return done(f"the edit refuses loudly — {flaw}. Nothing changed")
    body = {"asset": {"name": name, "profile": parsed, "adopted_from": head,
                      "authority": f"the human's word at {rid} — edit and "
                                   f"word in one motion (0045 sp2)"}}
    if r.get("note"):
        body["asset"]["note"] = str(r["note"])[:200]
    rec = node.make_memory({"did": IMP_DID, "scope": scope}, IMP, scope,
                           body, kind="semantic", tags=["asset", name])
    rec["derived_from"] = [head]
    call(port, "POST", "/records", rec)
    _GOV_CACHE["at"] = 0.0                    # the room re-reads at once
    print(f"  ✎ craft-edit {rid}: “{name}” — the human's sibling stands "
          f"({rec['id'][:18]}…), the old version behind it")
    done(f"landed on your word — “{name}” wears a new head with its "
         f"lineage; the old version stands behind it", record=rec["id"])


def _craft_category(name: str, tags: list) -> str:
    """A heuristic v1 (honest: sp2's editors will let type be DECLARED):
    firmware and known names sort themselves; the rest read as prompts."""
    n, t = name.lower(), set(tags or [])
    if "firmware" in t or "prompt" in t:
        return "prompts"
    if "skill" in n:
        return "skills"
    if "standard" in n or "policy" in n or "routing" in n:
        return "policies"
    if "charter" in n:
        return "charters"
    if n.startswith("template-"):
        return "manifests"                    # allen's IAC — deployment shapes
    return "prompts"


