def craft_serve(name: str, did: str, *, pin: str | None = None) -> dict:
    """The supply line's door (0045 sp5, law 8): resolve craft by name —
    head or pinned — for an external consumer. If an argument is running
    on this craft, the consumer draws an ARM by its own DID (deterministic,
    visible in the reply — no secret experiments). Every serving lands on
    the instrument tier (servings.jsonl — the flight recorder's precedent:
    telemetry, not testimony)."""
    if not name:
        return {"error": "name required"}
    port = 4500
    refs, lifecycle, texts = [], None, {}
    for ref, b, _, _ in wire_assets(port, "firmware"):
        f = (b or {}).get("firmware") or {}
        if f.get("name") == name:
            refs.append(ref)
            texts[ref] = f.get("text")
            lifecycle = "canon"
    if not refs:
        for ref, b, _, t in wire_assets(port, "asset"):
            nm = next((x for x in (t or []) if x not in
                       ("asset", "asset-variant", "adopted")), None)
            if nm == name:
                refs.append(ref)
                texts[ref] = (b or {}).get("asset", {}).get("profile")
                lifecycle = "chronicle"
    if not refs:
        return {"error": f"the shelf holds no craft named {name!r}"}
    ref = pin if (pin and pin in refs) else refs[-1]
    if pin and pin not in refs:
        return {"error": "the pinned version is not on this worldline"}
    arm = None
    try:
        exp = next((e for e in _exps_load().values()
                    if e.get("state") == "running"
                    and name in json.dumps(e)[:500]), None)
        if exp is not None:
            arm = "a" if int(crypto.content_hash({"d": did})[10:12], 16) % 2 == 0 \
                else "b"
    except Exception:
        pass
    out = {"name": name, "ref": ref, "version": refs.index(ref) + 1,
           "lifecycle": lifecycle}
    body = texts.get(ref)
    if isinstance(body, str):
        out["text"] = body
    elif body is not None:
        out["profile"] = body
    if arm:
        out["arm"] = arm                      # visible — never a secret split
    try:
        with open(os.path.join(FlightBook.HOME, "servings.jsonl"), "a") as f:
            f.write(json.dumps({"at": NOW(), "name": name, "ref": ref,
                                "did": did[:48], "arm": arm}) + "\n")
    except Exception:
        pass
    return out


def compose_governance() -> dict:
    """The registry (0045 law 1): a PROJECTION over the signed shelves —
    one payload, worldlines collapsed, every object wearing its lifecycle.
    Bodies are not carried here; the glass reads them through the records
    door, so the index stays light at thousands of objects."""
    if time.time() - _GOV_CACHE["at"] < 10 and _GOV_CACHE["payload"]:
        return _GOV_CACHE["payload"]
    port = 4500
    objects: list = []
    # the Canon firmware — one worldline per name, oldest-first, head last
    fw: dict[str, list] = {}
    for ref, b, _, t in wire_assets(port, "firmware"):
        f = (b or {}).get("firmware") or {}
        if f.get("name"):
            fw.setdefault(f["name"], []).append(ref)
    for name, refs in sorted(fw.items()):
        objects.append({"name": name, "category": "prompts",
                        "lifecycle": "canon", "versions": len(refs),
                        "head": refs[-1], "refs": refs,
                        "wearers": _WEARERS.get(name, [])})
    # the Chronicle shelf — grace's assets, grouped by their name tag
    sh: dict[str, dict] = {}
    for ref, b, _, t in wire_assets(port, "asset"):
        name = next((x for x in (t or []) if x not in
                     ("asset", "asset-variant", "adopted")), None)
        if not name:
            continue
        row = sh.setdefault(name, {"refs": [], "tags": t})
        row["refs"].append(ref)
    for name, row in sorted(sh.items()):
        objects.append({"name": name,
                        "category": _craft_category(name, row["tags"]),
                        "lifecycle": "chronicle",
                        "versions": len(row["refs"]),
                        "head": row["refs"][-1], "refs": row["refs"],
                        "wearers": _WEARERS.get(name,
                                   ["allen · a deployment shape"]
                                   if name.startswith("template-") else [])})
    # the rows' floor joins the registry (0045 sp4): the argument machinery
    # lives at e:rag, so its craft shows HERE with the argue door open.
    # (The full-rig shelf sweep is a named gap — one floor at a time.)
    try:
        rag_port, rag_scope = _rag_floor()
        if rag_port:
            rg: dict[str, dict] = {}
            for ref, b, _, t in wire_assets(rag_port, "asset", scope=rag_scope):
                nm = next((x for x in (t or []) if x not in
                           ("asset", "asset-variant", "adopted")), None)
                if nm:
                    rg.setdefault(nm, {"refs": [], "tags": t})["refs"].append(ref)
            for nm, row in sorted(rg.items()):
                objects.append({"name": nm,
                                "category": _craft_category(nm, row["tags"]),
                                "lifecycle": "chronicle", "at": rag_scope,
                                "versions": len(row["refs"]),
                                "head": row["refs"][-1], "refs": row["refs"],
                                "argue": True, "port": rag_port,
                                "wearers": _WEARERS.get(nm, [])})
    except Exception:
        pass
    # charters and manifests — records already on the shelf
    for tag, cat in (("charter", "charters"), ("bell-manifest", "manifests")):
        seen: dict[str, list] = {}
        for ref, b, _, t in wire_assets(port, tag):
            key = next((x for x in (t or []) if x != tag), tag)
            seen.setdefault(key, []).append(ref)
        for name, refs in sorted(seen.items()):
            objects.append({"name": name, "category": cat,
                            "lifecycle": "canon" if cat == "manifests"
                            else "chronicle",
                            "versions": len(refs), "head": refs[-1],
                            "refs": refs})
    # declared rubrics — short, carried inline from the nest
    rubrics = [{"goal": k[:20] + "…", "text": v}
               for k, v in _rubrics_load().items()]
    counts: dict = {}
    for o in objects:
        counts[o["category"]] = counts.get(o["category"], 0) + 1
    payload = {"at": NOW(), "objects": objects, "rubrics": rubrics,
               "counts": counts,
               "note": "a projection over the signed log — never a second "
                       "truth (0045 law 1)"}
    _GOV_CACHE.update(at=time.time(), payload=payload)
    return payload


def _bell_room_view() -> dict:
    """The bell's own state for the room (0044 sp4): consent posture, the
    standing rings, rung-or-resting — read from the ledger seeds, cheap."""
    rows = _bell_state_load()
    last = (max(rows.values(), key=lambda v: v.get("at", ""))
            if rows else None)
    consent = None
    try:
        consent = _bell_consent_head(4500)
    except Exception:
        pass
    cooldown = int(os.environ.get("ORRETH_BELL_COOLDOWN_S", "3600"))
    state = ("silent — no standing grant"
             if not consent or consent.get("posture") != "granted"
             else "rung" if last and _age_seconds(last["at"]) < cooldown
             else "resting")
    return {"state": state,
            "consent": (consent or {}).get("posture") or "none",
            "last": last and {"at": last["at"],
                              "repeats": last.get("repeats", 0)},
            "standing_rings": len(rows), "cooldown_s": cooldown}


