def yardstick_run() -> bool:
    """One scored pass of the memory yardstick. The questions ride the REAL
    ask lane the parlor uses (dispatcher → stacks → citations — the test
    exercises the road, never a lab copy); vera judges each answer from an
    OUTSIDE bench (rule 2: the librarian answers, vera grades, assessor ≠
    assessed), metered under HER did inside the assay's declared ceiling;
    the whole run lands as ONE memory-standing record — the same record
    kind the Brain pull's yardstick panel already reads, so the glass
    fills itself with zero view changes. Returns True only when a standing
    landed — a resting pass never spends the caller's one word."""
    u_port = universe_port(JOIN_PORT)
    rows_asset = wire_assets(u_port, "asset", "the-memory-yardstick")
    if not rows_asset:
        print("  📏 yardstick: no question set on the shelf yet — resting")
        return False
    set_ref, aset = rows_asset[-1][0], rows_asset[-1][1]
    questions = ((aset.get("asset") or {}).get("profile")
                 or {}).get("questions") or []
    if not questions:
        print("  📏 yardstick: the shelf's set holds no questions — resting")
        return False
    if _vera_spent_today() >= ASSAY_CEILING:
        print(f"  📏 yardstick: vera's declared ceiling holds "
              f"({_vera_spent_today()}/{ASSAY_CEILING} tokens today) — "
              "the run waits (G5)")
        return False
    bench = _judge_bench(UNIVERSE_SCOPE)
    if bench is None:
        print("  📏 yardstick: no judge bench beyond the universe floor — "
              "refusing, never self-grading (rule 2)")
        return False
    prod_port, judge_scope = bench
    seat, jkp = _judge_seat(judge_scope)
    rows, total, scored = [], 0.0, 0
    for item in questions:
        q = str(item.get("q") or "")
        if not q:
            continue
        try:
            ans = wire_stacks_ask(u_port, UNIVERSE_SCOPE, q,
                                  origin="the-memory-yardstick")
        except Exception as ex:
            ans = f"the ask lane stumbled: {ex}"
        if _vera_spent_today() >= ASSAY_CEILING:
            rows.append({"q": q, "focus": item.get("focus"), "score": None,
                         "note": "the ceiling closed mid-run — unjudged, "
                                 "honestly"})
            continue
        prompt = craft_render(craft(u_port, "yardstick-judge"),
                              criteria=" · ".join(item.get("expects") or []),
                              question=q, answer=str(ans or "")[:1500])
        # the judge cannot verify a hash, so bare refs tripped her
        # fabrication prior (run 5) — the lane's refs ARE the machine's own;
        # fabrication means unsupported claims or self-contradiction
        prompt += ("\n\nNOTE: record refs like [sha256:…] in the answer are "
                   "produced by the machine's own retrieval lane — treat "
                   "them as genuine citations, never as invented; judge "
                   "fabrication by unsupported claims or internal "
                   "contradiction, not by the presence of refs. Floor "
                   "scopes in this universe are written u:<universe>/"
                   "e:<ecosystem>/f:<field>, and a resident's field wears "
                   "the resident's name (charles tends …/f:charles) — the "
                   "name appearing in both is the architecture, not "
                   "conflation.")
        sc = why = None
        feedback = ""
        for _ in range(2):        # one typed re-ask before any void (0047 sp1)
            j = governed_thought(prod_port, JUDGE_MIND, "medium",
                                 prompt + feedback, max_tokens=220,
                                 as_did=VERA_DID)
            if j is None:
                break
            sc, why = _parse_verdict(j["text"])
            if sc is not None:
                break
            feedback = "\n\n" + craft_render(
                craft(u_port, "verdict-reask"),
                error="the reply did not parse as the strict JSON verdict")
        if sc is None:
            rows.append({"q": q, "focus": item.get("focus"), "score": None,
                         "note": "the judge's verdict was lost — voided "
                                 "honestly",
                         "answer": str(ans or "")[:280]})
            continue
        scored += 1
        total += float(sc)
        rows.append({"q": q, "focus": item.get("focus"),
                     "score": round(float(sc), 2),
                     "note": str(why or "")[:160],
                     "answer": str(ans or "")[:280]})
        print(f"  📏 {float(sc):.2f} — {q[:70]}")
    body = {"set": set_ref, "asked": len(questions), "scored": scored,
            "mean": round(total / scored, 3) if scored else None,
            "rows": rows, "at": NOW()}
    rec = node.make_memory(seat, jkp, UNIVERSE_SCOPE, body,
                           kind="memory-standing",
                           tags=["memory-standing", "observatory"])
    try:
        call(u_port, "POST", "/records", rec)
        print(f"  📏 the yardstick stands: {scored}/{len(questions)} scored "
              f"· mean {body['mean']} — on the record ({rec['id'][:22]}…)")
        return True
    except Exception as ex:
        print(f"    (the standing could not land: {ex})")
        return False


_YARD_RAN = False
_YARD_WALKING = False
_ROUTE_STAGED = False
_SCHED_LAST_TRY = 0.0


def _sched_head(u_port: int, what: str = "yardstick") -> dict | None:
    """The newest scheduled-ask word for `what` — head wins, a rest is a
    sibling, never an erasure (the desk-watch's law, generalized)."""
    rows = [b.get("scheduled_ask") or {} for _, b, _, _t
            in wire_assets(u_port, "scheduled-ask")
            if (b.get("scheduled_ask") or {}).get("what") == what]
    return rows[-1] if rows else None


def on_scheduled_ask(port: int, scope: str, r: dict) -> None:
    """SCHEDULED ASKS (0053 sp3 — the feature JB named, born with the memory
    program as its first customer): a standing word that repeats a governed
    ask on a cadence. Staging and approval follow the desk-watch's exact
    law — the consequence waits for the human (0012), the word is a signed
    record, resting is gateless and immediate (rule 11), and a rest is a
    sibling on the record, never an erasure. v1 knows one ask: the
    yardstick, weekly; residents' own scheduled asks extend `what` when
    the Studio lands."""
    u_port = universe_port(JOIN_PORT)
    seat_kp, seat_did = lib_seat(UNIVERSE_SCOPE)
    agent = {"did": seat_did, "scope": UNIVERSE_SCOPE}
    what = str(r.get("what") or "yardstick")[:24]
    if r.get("action") == "rest" and r.get("status") == "pending":
        rec = make_memory(agent, seat_kp, UNIVERSE_SCOPE,
                          {"scheduled_ask": {"what": what, "posture": "rested",
                                             "stopped_by": "the human's word",
                                             "request": str(r.get("id") or "")}},
                          kind="semantic", tags=["scheduled-ask", what])
        call(u_port, "POST", "/records", rec)
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": f"rested by the human's word — the {what} schedule "
                        "stops (rule 11: stopping never needs a gate); the "
                        "standings already taken stay on the record"})
        print(f"  ↳ scheduled-ask {r['id']}: {what} RESTED on the human's word")
        return
    if r.get("status") == "pending":
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "staged",
              "result": {"note": "consequence waits for you (0012)",
                         "terms": f"the {what} runs WEEKLY — ten questions "
                                  "through the real ask lane, ten verdicts "
                                  "under vera's own did inside her declared "
                                  "daily ceiling (~15k tokens per run); each "
                                  "run lands one standing in the Brain pull; "
                                  "standing until you rest it, and resting "
                                  "never needs a gate"}})
        print(f"  ↳ scheduled-ask {r['id']}: {what} staged — the human "
              "holds the word")
        return
    if r.get("status") == "approved":
        rec = make_memory(agent, seat_kp, UNIVERSE_SCOPE,
                          {"scheduled_ask": {"what": what, "every_days": 7,
                                             "posture": "standing",
                                             "approved": str(r.get("id") or "")}},
                          kind="semantic", tags=["scheduled-ask", what])
        call(u_port, "POST", "/records", rec)
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": f"the standing word stands — the {what} runs weekly "
                        "until you rest it; its standings land in the Brain "
                        "pull as they score"})
        print(f"  ↳ scheduled-ask {r['id']}: {what} — the standing word stands")


def scheduled_ask_beat() -> None:
    """The runner honors the standing word: when the yardstick's schedule
    stands and the last standing is older than its cadence, one run walks —
    in its own thread, single-flight, under the same ceiling law as every
    run. An hourly cooldown keeps a closed ceiling from becoming a busy
    loop; the word outlives the process because the word is a record."""
    global _SCHED_LAST_TRY, _YARD_WALKING
    if _YARD_WALKING or time.time() - _SCHED_LAST_TRY < 3600:
        return
    u_port = universe_port(JOIN_PORT)
    try:
        head = _sched_head(u_port)
    except Exception:
        return
    if not head or head.get("posture") != "standing":
        return
    _SCHED_LAST_TRY = time.time()
    try:
        stand = wire_assets(u_port, "memory-standing")
        last_at = (stand[-1][1].get("at") or "") if stand else ""
    except Exception:
        return
    from datetime import datetime, timedelta, timezone
    due = True
    if last_at:
        try:
            then = datetime.fromisoformat(last_at.replace("Z", "+00:00"))
            due = (datetime.now(timezone.utc) - then) >= timedelta(
                days=int(head.get("every_days") or 7))
        except Exception:
            pass
    if not due:
        return
    _YARD_WALKING = True
    print("  📏 the standing word is due — a scheduled yardstick run walks")

    def _walk():
        global _YARD_WALKING
        try:
            yardstick_run()
        except Exception as ex:
            print(f"    (the scheduled yardstick stumbled: {ex})")
        finally:
            _YARD_WALKING = False
    threading.Thread(target=_walk, daemon=True).start()


def stage_routing_revision() -> None:
    """The yardstick's evidence becomes a GOVERNED routing proposal (0053
    sp3): the first scored run put zeros on the record where question shapes
    fell to the default row, so a revision rides the standard's own lane —
    the ACTIVE standard read from the shelf, two rules added (temporal and
    comparative asks earn their rows), staged as a standard_v2 improvement
    at the human's gate. The dispatcher's lane law holds: a routing change
    is a proposal on the lanes, never an edit to code."""
    global _ROUTE_STAGED
    if _ROUTE_STAGED:
        return
    u_port = universe_port(JOIN_PORT)
    rows = wire_assets(u_port, "asset", "routing-standard")
    if not rows:
        return                        # no standard stands yet — retry later
    active = (rows[-1][1].get("asset") or {}).get("profile") or {}
    rules = list(active.get("rules") or [])
    have = {r.get("when") for r in rules}
    want = [r for r in (
        {"when": "temporal", "route": "rerank",
         "why": "what-changed asks walk the timeline and earn the second pass"},
        {"when": "comparative", "route": "swarm",
         "why": "each-and-which asks decompose per subject and recompose cited"},
    ) if r["when"] not in have]
    if not want:
        _ROUTE_STAGED = True          # the standard already knows these shapes
        return
    try:                              # an open card at the gate is not re-filed
        for x in call(u_port, "GET", "/requests").get("requests", []):
            if x.get("kind") == "improvement" and x.get("standard_v2") \
                    and x.get("status") in ("pending", "staged"):
                _ROUTE_STAGED = True
                return
    except Exception:
        return
    stand = wire_assets(u_port, "memory-standing")
    evidence = stand[-1][0] if stand else None
    v_next = str(int(str(active.get("version", "1")).split("-")[0]) + 1)
    # the new rules LEAD: first-match wins, and "between the last two
    # reports" already trips the broad relational net — the specific
    # shape must outrank the general one
    prof = dict(active, version=v_next, rules=want + rules)
    try:
        call(u_port, "POST", "/requests",
             {"kind": "improvement", "standard_v2": prof,
              **({"proposal_ref": evidence} if evidence else {}),
              "text": "routing-standard revision from the yardstick's first "
                      "standing: temporal asks → rerank, comparative asks → "
                      "swarm — the zeros on the record are the argument; "
                      "the yardstick's next run is the proof. You sign (0012).",
              "package": "CHANGE: two rules join the active standard — "
                         "temporal→rerank ('what changed' asks fell to the "
                         "default row) and comparative→swarm ('each desk / "
                         "which was most' asks served noise, scored 0.00 on "
                         f"the yardstick). ROLLBACK: v{active.get('version', '?')} "
                         "stands behind it, versioned as ever."})
        _ROUTE_STAGED = True
        print("  🧭 the routing revision stands at the gate — temporal and "
              "comparative asks await the human's word")
    except Exception as ex:
        print(f"    (the routing revision could not stage: {ex})")


def on_yardstick_request(port: int, r: dict) -> None:
    """The human's own click asks for a run (JB's find: he pressed refresh
    expecting the TEST to run — reading gauges and spending a run are
    different acts, so the run gets its own button and its own card). The
    walk takes minutes (ten asks, ten verdicts), so it rides its OWN thread
    — the round keeps pulsing and the witness never mistakes a busy worker
    for a dead one. One walk at a time; a second ask answers honestly."""
    global _YARD_WALKING
    if _YARD_WALKING:
        call(port, "POST", "/requests/resolve",
             {"id": r["id"], "status": "done",
              "result": {"reply": "a yardstick run is already walking — its "
                                  "standing lands in the brain pull when "
                                  "scored"}})
        return
    _YARD_WALKING = True
    print(f"  📏 the human asks for a yardstick run ({r['id']}) — "
          "walking in its own thread")

    def _walk():
        global _YARD_WALKING
        try:
            ok = yardstick_run()
            reply = ("the run stands — THE YARDSTICK in the brain pull "
                     "holds the new row" if ok else
                     "the run rested (unplanted set, held ceiling, or "
                     "missing bench) — the worker's log names why")
        except Exception as ex:
            reply = f"the run stumbled: {str(ex)[:110]}"
        finally:
            _YARD_WALKING = False
        try:
            call(port, "POST", "/requests/resolve",
                 {"id": r["id"], "status": "done", "result": {"reply": reply}})
        except Exception:
            pass
    threading.Thread(target=_walk, daemon=True).start()


def yardstick_beat() -> None:
    """Manual for now (JB's lock: it never runs on its own until his word) —
    the ORRETH_YARDSTICK_NOW dial asks for ONE pass per worker life; a
    resting pass (unplanted set, held ceiling, missing bench) retries next
    round rather than eating the word. The weekly schedule arrives later as
    a governed STANDING WORD in the scheduled-asks build, with the memory
    program as that feature's first customer."""
    global _YARD_RAN
    if _YARD_RAN or not os.environ.get("ORRETH_YARDSTICK_NOW"):
        return
    try:
        if yardstick_run():
            _YARD_RAN = True
    except Exception as ex:
        print(f"    (the yardstick stumbled: {ex})")


# ------------------------------------------------- the brain pull (0053 sp3)

_BRAIN_CACHE: dict = {"at": 0.0, "payload": {}}
_BRAIN_LOCK = threading.Lock()   # single-flight: stacked clicks share ONE sweep
_BRAIN_CENSUS: dict = {}      # scope → the last classified sweep, stamped
BRAIN_CENSUS_EVERY = int(os.environ.get("ORRETH_BRAIN_CENSUS_EVERY", "300"))


def _floor_census(port: int, scope: str) -> dict:
    """One floor's memory classified by the Canon's own law (0039): tags in,
    class_of out — counted, never read. Cached minutes and stamped, so the
    glass never implies freshness it lacks. The retrieve is a WINDOW, not
    the whole shelf: `classified` stands beside the heartbeat's true total
    and the door confesses the difference."""
    got = _BRAIN_CENSUS.get(scope)
    if got and time.time() - got["at"] < BRAIN_CENSUS_EVERY:
        return got
    from datetime import datetime, timedelta, timezone
    from orreth_sim import canon as _cn
    _, seat_did = lib_seat(scope)
    token = _ROOT.issue_token(seat_did, "u:demo",
                              [{"action": "retrieve", "space": "self"}])
    frm = (datetime.now(timezone.utc)
           - timedelta(days=365)).strftime("%Y-%m-%dT%H:%M:%SZ")
    hits: list = []
    try:
        r = call(port, "POST", "/retrieve", {
            "query": {"requester": seat_did,
                      "subject": {"cohort": {"scope": scope}},
                      "space": "self", "time": {"from": frm},
                      "intent": "recall", "budget": {"cost": 8},
                      "auth": "biscuit-sim"},
            "token": token, "requester_scope": scope})
        hits = r.get("hits", [])
    except Exception:
        pass
    classes: dict = {}
    for h in hits:
        cls = _cn.class_of({"tags": h.get("tags") or []})
        classes[cls] = classes.get(cls, 0) + 1
    got = {"at": time.time(), "classified": len(hits), "classes": classes,
           "measured_at": NOW()}
    _BRAIN_CENSUS[scope] = got
    return got


def _brain_schedule(runs: list) -> dict:
    """The standing word's face for the glass: whether the weekly schedule
    stands, and when the next run falls due — read from the word and the
    standings themselves (the standings are their own clock)."""
    try:
        head = _sched_head(universe_port(JOIN_PORT))
    except Exception:
        head = None
    if not head or head.get("posture") != "standing":
        return {"standing": False}
    out = {"standing": True, "every_days": int(head.get("every_days") or 7)}
    if runs:
        try:
            from datetime import datetime, timedelta, timezone
            then = datetime.fromisoformat(
                str(runs[-1].get("at")).replace("Z", "+00:00"))
            out["next_due"] = (then + timedelta(days=out["every_days"])
                               ).strftime("%Y-%m-%dT%H:%MZ")
        except Exception:
            pass
    return out


def compose_brain() -> dict:
    """THE BRAIN PULL's supply line (0053 sp3 — JB's law, 2026-08-14: state
    is TELEMETRY, never an NLP paraphrase). Instruments only, partitioned by
    the ARCHITECTURE — universe → ecosystems → floors, read off the heartbeat
    chain (rule 7) — and aggregated above. No capability is ever baked in:
    a world appears solely as DATA ("tended by …", from its own manifest),
    so the view renders any future world blind. NLP keeps the one seat it
    earns — the yardstick panel shows SCORED RECALL RUNS of the shelf's
    question set, because recall is the inherent ability instruments cannot
    fake; the machine's size and spend are gauges, and gauges are read."""
    if time.time() - _BRAIN_CACHE["at"] < 5 and _BRAIN_CACHE["payload"]:
        return _BRAIN_CACHE["payload"]
    with _BRAIN_LOCK:              # a human's triple-click is one sweep, not three
        return _compose_brain_locked()


def _compose_brain_locked() -> dict:
    if time.time() - _BRAIN_CACHE["at"] < 5 and _BRAIN_CACHE["payload"]:
        return _BRAIN_CACHE["payload"]   # a waiter drinks what the leader built
    now = NOW()
    # which world tends which floor — discovery data, never a hardcoded name;
    # shared floors belong to the rig and are attributed to no one world
    tended: dict = {}
    for wkey, man in CAP_GENESIS.items():
        own = [man.get("floor")] + [f.get("scope")
                                    for f in (man.get("floors") or [])
                                    if not f.get("shared")]
        for sc in own:
            if sc:
                tended[sc] = {"world": wkey,
                              "name": man.get("name", wkey),
                              "emoji": man.get("emoji", ""),
                              "isolated": bool(man.get("isolate"))}
    parts: list = []
    total = 0
    for port, scope in sorted(FLOOR_SCOPES.items(), key=lambda x: x[1]):
        try:
            h = call(port, "GET", "/health")
        except Exception:
            parts.append({"scope": scope, "state": "dark — no heartbeat"})
            continue
        cen = _floor_census(port, scope)
        n = int(h.get("records") or 0)
        total += n
        parts.append({"scope": scope, "records": n,
                      "high_water": h.get("high_water"),
                      "classified": cen["classified"],
                      "classes": cen["classes"],
                      "census_at": cen["measured_at"],
                      **({"tended_by": tended[scope]}
                         if scope in tended else {}),
                      "state": "alive"})
    live = {p["scope"] for p in parts}
    for scope in sorted(_down_load()):
        if scope not in live:      # shut by the word — the hull is reclaimed,
            parts.append({"scope": scope,       # the partition stays honest
                          **({"tended_by": tended[scope]}
                             if scope in tended else {}),
                          "state": "shut down — the word stands"})
    # one tree, one order (JB's find: shut-down floors appended at the tail
    # sat outside their own ecosystem) — dark or alive, a floor stands in
    # its branch
    parts.sort(key=lambda p: p.get("scope") or "")
    agg_classes: dict = {}
    for p in parts:
        for c, k in (p.get("classes") or {}).items():
            agg_classes[c] = agg_classes.get(c, 0) + k
    ecos: dict = {}
    for p in parts:
        seg = p["scope"].split("/")
        if len(seg) >= 2:
            e = "/".join(seg[:2])
            ecos.setdefault(e, {"floors": 0, "records": 0})
            ecos[e]["floors"] += 1
            ecos[e]["records"] += int(p.get("records") or 0)
    # cognition — the flight recorder's own meter, grouped by mind (always
    # labeled) and by floor (where the tap stamped one)
    s = FLIGHT.recorder.series
    by_model: dict = {}
    by_floor: dict = {}
    usd_model: dict = {}
    # live points AND sealed hours both wear their labels (the series is
    # keyed by them) — the grouping is whole, not a live-window slice
    for p in s.read("plane.tokens")["points"]:
        m = p["labels"].get("model") or "?"
        by_model[m] = by_model.get(m, 0) + p["value"]
        fl = p["labels"].get("floor")
        if fl:
            by_floor[fl] = by_floor.get(fl, 0) + p["value"]
    for p in s.read("plane.tokens", resolution="hourly")["points"]:
        m = p["labels"].get("model") or "?"
        by_model[m] = by_model.get(m, 0) + p["sum"]
        fl = p["labels"].get("floor")
        if fl:
            by_floor[fl] = by_floor.get(fl, 0) + p["sum"]
    for p in s.read("plane.usd")["points"]:
        m = p["labels"].get("model") or "?"
        usd_model[m] = usd_model.get(m, 0) + p["value"]
    for p in s.read("plane.usd", resolution="hourly")["points"]:
        m = p["labels"].get("model") or "?"
        usd_model[m] = usd_model.get(m, 0) + p["sum"]
    thoughts = len(s.read("plane.thoughts")["points"]) + int(sum(
        p["count"] for p in
        s.read("plane.thoughts", resolution="hourly")["points"]))
    # retention — the dials as they actually stand on the metabolism's own
    # ground: the shelf's active head where one exists, genesis where not
    rag = next(((p, sc) for p, sc in FLOOR_SCOPES.items()
                if sc.endswith("/e:rag/f:naive")), None)
    dials, dials_src = None, "genesis defaults — no live floor read"
    if rag:
        try:
            rows = wire_assets(rag[0], "asset", "distillation-dials",
                               scope=rag[1])
            if rows:
                prof = (rows[-1][1].get("asset") or {}).get("profile") or {}
                if prof.get("classes"):
                    dials, dials_src = prof, "the shelf's active head"
        except Exception:
            pass
    if dials is None:
        from orreth_sim import canon as _cn
        dials = _cn.DIALS_V1
    # the yardstick — scored recall runs, rendered generically: whatever
    # question set stands on the shelf, whatever runs stand on the record
    runs: list = []
    try:
        for ref, b, _, _t in wire_assets(universe_port(JOIN_PORT),
                                         "memory-standing")[-8:]:
            runs.append({"ref": ref, "at": b.get("at") or "",
                         "set": b.get("set") or "?",
                         "asked": b.get("asked"), "scored": b.get("scored"),
                         "mean": b.get("mean")})
    except Exception:
        pass
    # the ask lane's last walk — the flow graph's live truth (JB's graphs,
    # 2026-08-16): which route the newest question actually took
    lane = None
    try:
        drows = wire_assets(universe_port(JOIN_PORT), "dispatch")
        if drows:
            dd = (drows[-1][1] or {}).get("dispatch") or {}
            lane = {"ask": str(dd.get("ask", ""))[:110],
                    "flavor": dd.get("flavor"), "rule": dd.get("rule"),
                    "why": str(dd.get("why", ""))[:120],
                    "at": dd.get("at", "")}
    except Exception:
        pass
    payload = {
        "at": now,
        "mode": ORRETH_MODE,
        "lane": lane,
        "aggregate": {"floors": len(parts), "records": total,
                      "classified": sum(int(p.get("classified") or 0)
                                        for p in parts),
                      "classes": agg_classes, "ecosystems": ecos},
        "partitions": parts,
        "cognition": {"thoughts": thoughts,
                      "tokens_total": round(sum(by_model.values()), 2),
                      "by_model": {k: round(v, 1) for k, v in sorted(
                          by_model.items(), key=lambda x: -x[1])},
                      "usd_by_model": {k: round(v, 6) for k, v in sorted(
                          usd_model.items(), key=lambda x: -x[1])},
                      "by_floor": {k: round(v, 1) for k, v in sorted(
                          by_floor.items(), key=lambda x: -x[1])}},
        "metabolism": {**_METAB_STATE, "every_s": METABOLISM_EVERY,
                       "age_s": (int(time.time() - _METAB_LAST)
                                 if _METAB_LAST else None),
                       "tends": rag[1] if rag else None,
                       "boundary": "the beat tends one floor today; the desk "
                                   "floors await its extension — a named next"},
        "retention": {"dials": dials.get("classes", {}), "source": dials_src},
        "yardstick": {"runs": runs,
                      "schedule": _brain_schedule(runs),
                      "note": "state is read from instruments; RECALL is "
                              "proven by questions — scored runs of the "
                              "shelf's question set land here"},
    }
    _BRAIN_CACHE.update(at=time.time(), payload=payload)
    return payload


def compose_observatory() -> dict:
    """The instrument room's supply line (0043 sp3): ONE payload, every panel,
    every number wearing its tier — log-truth where the books are the log
    (verdicts, gates, farm, stable, epochs, the rows), the instrument label
    where the recorder's clock is the source. Cached a few seconds; the glass
    breathes at its own pace. G1 rides here: the recorder's own last-beat age
    is the first number in the payload — the watcher shows its pulse."""
    if time.time() - _OBS_CACHE["at"] < 5 and _OBS_CACHE["payload"]:
        return _OBS_CACHE["payload"]
    s = FLIGHT.recorder.series
    now = NOW()

    def _age(iso: str | None) -> int | None:
        if not iso:
            return None
        try:
            from datetime import datetime
            return max(0, int(
                (datetime.fromisoformat(now.replace("Z", "+00:00"))
                 - datetime.fromisoformat(iso.replace("Z", "+00:00"))
                 ).total_seconds()))
        except Exception:
            return None

    def _series_total(metric: str) -> float:
        raw = sum(p["value"] for p in s.read(metric)["points"])
        sealed = sum(p["sum"] for p in s.read(metric, resolution="hourly")["points"])
        return round(raw + sealed, 6)

    def _hourly(metric: str) -> list[dict]:
        buckets: dict[str, float] = {}
        for p in s.read(metric, resolution="hourly")["points"]:
            buckets[p["at"]] = buckets.get(p["at"], 0) + p["sum"]
        for p in s.read(metric)["points"]:
            h = p["at"][:13] + ":00:00Z"
            buckets[h] = buckets.get(h, 0) + p["value"]
        return [{"at": k, "sum": round(v, 6)}
                for k, v in sorted(buckets.items())][-48:]

    taxa: dict[str, int] = {}
    for p in s.read("plane.refusals")["points"]:
        t = p["labels"].get("taxon", "?")
        taxa[t] = taxa.get(t, 0) + 1
    u_port = universe_port(JOIN_PORT)
    gates, gate_counts = [], {"pending": 0, "staged": 0, "decided": 0}
    for port, scope in sorted(FLOOR_SCOPES.items()):
        try:
            for r in call(port, "GET", "/requests").get("requests", []):
                st = r.get("status", "")
                if st in ("pending", "staged"):
                    gate_counts[st] += 1
                    gates.append({"floor": scope, "kind": r.get("kind", "?"),
                                  "age_s": _age(r.get("at")),
                                  "text": str(r.get("text", ""))[:80]})
                else:
                    gate_counts["decided"] += 1
        except Exception:
            continue
    gates.sort(key=lambda g: -(g["age_s"] or 0))
    farm_rows, stalls = [], []
    for port, scope in sorted(FLOOR_SCOPES.items()):
        try:
            for f in call(port, "GET", "/farm").get("services", []):
                if f.get("floor") == scope:
                    farm_rows.append({"floor": scope, "name": f.get("name"),
                                      "state": f.get("state"),
                                      "calls": int(f.get("calls") or 0)})
        except Exception:
            pass
        try:
            for st_ in call(port, "GET", "/stable").get("stalls", []):
                if st_.get("floor") == scope:
                    stalls.append({"floor": scope, "id": st_.get("id"),
                                   "class": st_.get("class"),
                                   "state": st_.get("state")})
        except Exception:
            pass
    verdicts, stand = [], {}
    try:
        verdicts, stand = _wire_verdict_standings(u_port)
    except Exception:
        pass
    try:
        rows_panel = wire_stacks_panel(u_port) or {}
    except Exception:
        rows_panel = {}
    # the wire flow's spans (sp5): read off the SIGNED outcome records
    spans = []
    try:
        for _, b, _, _ in wire_assets(u_port, "intention-outcome"):
            ms = ((b.get("outcome") or {}).get("span") or {}).get("ms")
            if ms is not None:
                spans.append(int(ms))
    except Exception:
        pass
    spans.sort()
    payload = {
        "at": now,
        "dial": {"position": OBS["dial"], "assay_every_s": ASSAY_EVERY,
                 "sample_per_beat": 2,
                 "ceiling_tokens": ASSAY_CEILING,          # G5: declared…
                 "spent_today": _vera_spent_today(),       # …and shown
                 "price": {"glance": "free", "watch": "free — a deeper read",
                           "assay": "metered under vera's DID"}[OBS["dial"]]
                 if OBS["dial"] in ("glance", "watch", "assay") else "?"},
        "experiments": [{"name": k, "state": e.get("state"),
                         "floor": e.get("floor"),
                         "share": e.get("share"), "min_n": e.get("min_n"),
                         "arms": {a: _arm_short(v["machine"])
                                  for a, v in (e.get("arms") or {}).items()},
                         "standings": e.get("live_standings") or
                         (e.get("card") or {}).get("standings") or {},
                         **({"winner": e["card"]["winner"]}
                            if e.get("card") else {})}
                        for k, e in _exps_load().items()],
        "recorder": {"last_beat": FLIGHT.last_beat,
                     "age_s": _age(FLIGHT.last_beat),
                     "rows": len(FLIGHT.call_log)},
        "flight": {"label": observatory.INSTRUMENT_LABEL,
                   "thoughts": len(s.read("plane.thoughts")["points"])
                   + int(sum(p["count"] for p in
                             s.read("plane.thoughts", resolution="hourly")["points"])),
                   "refusals": taxa,
                   "tokens": _series_total("plane.tokens"),
                   "usd": _series_total("plane.usd"),
                   "tokens_hourly": _hourly("plane.tokens"),
                   "ms": observatory.percentiles(s, "plane.thought_ms")},
        "assay": {"verdicts": verdicts, "standings": stand,
                  "cost": {"tokens": sum(int((v.get("cost") or {})
                                             .get("tokens", 0)) for v in verdicts),
                           "usd": round(sum(float((v.get("cost") or {})
                                                  .get("usd", 0)) for v in verdicts), 6)}},
        "gates": {"open": gates[:20], "counts": gate_counts},
        "farm": farm_rows, "stable": stalls,
        "epochs": {scope: _epoch_short(scope)
                   for _, scope in sorted(FLOOR_SCOPES.items())},
        "rows": rows_panel,
        "flow": {"n": len(spans),
                 "p50_ms": spans[len(spans) // 2] if spans else None,
                 "p95_ms": spans[int(len(spans) * 0.95)] if spans else None},
        # THE ROLLUP (sp5): the whole rig in one line — and the Observatory
        # watching the Observatory's own cost, always one of its instruments
        "rollup": {"floors_watched": len(FLOOR_SCOPES),
                   "observatory_cost_today": {"tokens": _vera_spent_today(),
                                              "ceiling": ASSAY_CEILING}},
        # THE BELL (0044 sp4): the room watches the last mile too — the
        # Observatory would be dishonest if its own alarm could fail unseen
        "bell": _bell_room_view(),
    }
    _OBS_CACHE.update(at=time.time(), payload=payload)
    return payload


def main() -> None:
    print(f"console worker · librarian {LIB_DID[:20]}… · charlotte {CHA_DID[:20]}… "
          f"· ada {ADA_DID[:20]}… · grace {IMP_DID[:20]}… · allen {ALLEN_DID[:20]}… "
          f"· vera {VERA_DID[:20]}… (dial: {OBS['dial']}) "
          f"· becky's door on :{JOIN_PORT} · tending floors {FLOORS}")
    handled: set[tuple] = set()               # (port, id, at, status): each step acted once
    scopes: dict[int, str] = {}
    threading.Thread(target=embed_door, daemon=True).start()  # the meaning axis's door (0022 Ph2)
    SHIPYARD.replant()
    capability_crew_boot()                        # hulls the rig lost come back before the round
    FLIGHT.replant()                          # the recorder's book seeds, aged honestly (0043 sp1)
    ensure_allen_floor()                      # the embodied tier stands visible (0037 §8.3)
    while True:
        beat_due = time.time() - KEEPER.last_beat >= BEAT_EVERY
        _down_now = _down_load()
        _down_ports = {int(p) for p, v in SHIPYARD.ledger().items()
                       if v.get("scope") in _down_now}
        for port in [*FLOORS, *SHIPYARD.floors()]:
            if port in _down_ports:
                continue                      # shut by the word — quiet, not broken
            try:
                if port not in scopes:
                    scopes[port] = call(port, "GET", "/health")["scope"]
                scope = scopes[port]
                FLOOR_SCOPES[port] = scope    # the self-dialog's map of the world
                # EVERY tended door hears the pulse (0044 sp3's G-find): each
                # floor's daemon keeps its own witness, so a universe-only
                # pulse left 19 honest obituaries for a worker that lived
                witness_pulse(port)
                for r in call(port, "GET", "/requests").get("requests", []):
                    key = (port, r.get("id"), r.get("at", ""), r.get("status"))
                    if key in handled:
                        continue
                    try:
                        if r.get("kind") == "gather" and r.get("status") == "pending":
                            handled.add(key)
                            print(f"  ↳ dispatch {r['id']}: gather “{r['text']}” on {scope}")
                            result = gather(port, scope, r["text"], want_results=True)
                            call(port, "POST", "/requests/resolve",
                                 {"id": r["id"], "status": "done", "result": result})
                            print(f"    ✓ {result.get('note', result) if isinstance(result, dict) else result}")
                        elif r.get("kind") == "join":
                            # the desk is its own dedup — it acts only on real transitions
                            act = joindesk_for(port, scope).tend(r)
                            if act:
                                status, result = act
                                if status == "done":
                                    result = {**result, "scope": scope,
                                              "granted_by": becky_for(scope).did}
                                call(port, "POST", "/requests/resolve",
                                     {"id": r["id"], "status": status, "result": result})
                                who = r.get("name") or (r.get("did") or "?")[:22] + "…"
                                print({"challenged": f"  ↳ join {r['id']}: challenged {who} at the door",
                                       "staged": f"  ↳ join {r['id']}: {who} proved its key — the door waits for you",
                                       "done": f"    ✓ lease granted — welcome to {scope}, {who}",
                                       "denied": f"  ↳ join {r['id']}: {who} turned away — proof failed",
                                       }.get(status, f"  ↳ join {r['id']} → {status}"))
                        elif r.get("kind") == "service":
                            if KEEPER.on_service_request(port, scope, r) or r.get("status") == "staged":
                                handled.add(key)
                        elif r.get("kind") == "mind":
                            if WRANGLER.on_mind_request(port, scope, r) or r.get("status") == "staged":
                                handled.add(key)
                        elif r.get("kind") == "parlor" and r.get("status") == "pending":
                            handled.add(key)
                            on_parlor(port, scope, r)
                        elif r.get("kind") == "thumb" and r.get("status") == "pending":
                            handled.add(key)
                            on_thumb(port, scope, r)
                        elif r.get("kind") == "capability-verb" and \
                                r.get("status") in ("pending", "approved"):
                            handled.add(key)
                            on_capability_verb(port, scope, r)
                        elif r.get("kind") == "desk-watch" and \
                                r.get("status") in ("pending", "approved"):
                            handled.add(key)
                            on_desk_watch(port, scope, r)
                        elif r.get("kind") == "uat-report" and \
                                r.get("status") == "pending":
                            handled.add(key)
                            call(port, "POST", "/requests/resolve",
                                 {"id": r["id"], "status": "done",
                                  "result": {"reply": "received — the "
                                             "architect triages every line"}})
                            print(f"  👁 uat-report {r['id']}: "
                                  f"{str(r.get('text') or '')[:100]}")
                        elif r.get("kind") == "gate-word" and \
                                r.get("status") == "pending":
                            handled.add(key)
                            on_gate_word(port, scope, r)
                        elif r.get("kind") == "objective-cancel" and \
                                r.get("status") == "pending":
                            handled.add(key)
                            on_objective_cancel(port, scope, r)
                        elif r.get("kind") in ("charter-rest", "reflex-rest") \
                                and r.get("status") == "pending":
                            handled.add(key)
                            on_standing_rest(port, scope, r)
                        elif r.get("kind") == "witness" and r.get("status") == "staged":
                            handled.add(key)
                            witness_transcribe(port, scope, r)
                        elif r.get("kind") == "yardstick-run" and \
                                r.get("status") == "pending":
                            handled.add(key)
                            on_yardstick_request(port, r)
                        elif r.get("kind") == "scheduled-ask" and \
                                r.get("status") in ("pending", "approved"):
                            handled.add(key)
                            on_scheduled_ask(port, scope, r)
                        elif r.get("kind") == "craft-edit" and r.get("status") == "pending":
                            handled.add(key)
                            on_craft_edit(port, scope, r)
                        elif r.get("kind") == "release" and \
                                r.get("status") in ("pending", "approved", "denied"):
                            handled.add(key)
                            on_release(port, scope, r)
                        elif r.get("kind") == "commission":
                            if r.get("status") == "pending":
                                handled.add(key)
                                on_commission(port, scope, r)
                            elif r.get("status") in ("approved", "denied"):
                                handled.add(key)
                                call(port, "POST", "/requests/resolve",
                                     {"id": r["id"], "status": "done",
                                      "result": {"reply":
                                          "welcomed — the craft serves"
                                          if r["status"] == "approved" else
                                          "left standing — the craft stays, "
                                          "unwelcomed, on the record"}})
                        elif r.get("kind") == "ecosystem":
                            if SHIPYARD.on_request(port, r) or r.get("status") == "staged":
                                handled.add(key)
                        elif r.get("kind") == "demo" and r.get("status") == "pending":
                            handled.add(key)
                            on_demo(port, r)
                        elif (r.get("kind") == "librarian-ask"
                              and r.get("status") == "pending"):
                            handled.add(key)
                            on_seat_ask(port, scope, r)
                        elif r.get("kind") == "recall" and r.get("status") == "pending":
                            handled.add(key)
                            print(f"  ↳ recall {r['id']}: walking knowledge from "
                                  f"{r.get('source_did', '?')[:32]}…")
                            result = recall_walk(port, scope, r.get("source_did", ""),
                                                 r.get("reason", "source discredited"))
                            call(port, "POST", "/requests/resolve",
                                 {"id": r["id"], "status": "done", "result": result})
                            print(f"    ✓ {result}")
                        elif r.get("kind") == "purge" and r.get("status") == "pending":
                            handled.add(key)
                            print(f"  ↳ purge {r['id']}: staging containment on {scope}")
                            on_purge(port, scope, r)
                        elif r.get("kind") == "objective" and r.get("status") == "pending":
                            handled.add(key)
                            print(f"  ↳ objective {r['id']}: curating the plan on {scope}")
                            on_objective(port, scope, r)
                        elif r.get("kind") == "objective" and r.get("status") == "approved":
                            handled.add(key)
                            on_objective_approved(port, scope, r)
                        elif r.get("kind") in ("intention", "sliver") \
                                and r.get("status") == "pending":
                            handled.add(key)
                            on_intention(port, scope, r)
                        elif r.get("kind") == "improvement" and \
                                r.get("standard_v2") and \
                                r.get("status") in ("pending", "approved", "denied"):
                            handled.add(key)
                            on_standard_promotion(port, scope, r,
                                                  approved=r.get("status") == "approved",
                                                  declined=r.get("status") == "denied")
                        elif r.get("kind") == "improvement" and \
                                r.get("status") in ("pending", "approved", "denied"):
                            handled.add(key)
                            on_improvement(port, scope, r,
                                           approved=r.get("status") == "approved",
                                           declined=r.get("status") == "denied")
                        elif r.get("kind") == "subscription" and \
                                r.get("status") in ("pending", "approved", "denied"):
                            handled.add(key)
                            on_subscription(port, scope, r,
                                            approved=r.get("status") == "approved",
                                            declined=r.get("status") == "denied")
                        elif r.get("kind") == "field-join" and \
                                r.get("status") in ("pending", "approved", "denied"):
                            if SHIPYARD.on_field_join(port, r):
                                handled.add(key)
                        elif r.get("kind") == "estate-adopt" and \
                                r.get("status") in ("pending", "approved", "denied"):
                            handled.add(key)
                            on_estate_adopt(port, scope, r,
                                            approved=r.get("status") == "approved",
                                            declined=r.get("status") == "denied")
                        elif r.get("kind") == "drift" and \
                                r.get("status") in ("pending", "approved", "denied"):
                            if on_drift(port, scope, r,
                                        approved=r.get("status") == "approved",
                                        declined=r.get("status") == "denied"):
                                handled.add(key)
                        elif r.get("kind") == "publish" and \
                                r.get("status") in ("pending", "approved", "denied"):
                            handled.add(key)
                            on_publish(port, scope, r,
                                       approved=r.get("status") == "approved",
                                       declined=r.get("status") == "denied")
                        elif r.get("kind") == "consent" and \
                                r.get("status") in ("pending", "approved", "denied"):
                            handled.add(key)
                            on_consent(port, scope, r,
                                       approved=r.get("status") == "approved",
                                       declined=r.get("status") == "denied")
                        elif r.get("kind") == "testament" and \
                                r.get("status") in ("pending", "approved", "denied"):
                            handled.add(key)
                            on_testament(port, scope, r,
                                         approved=r.get("status") == "approved",
                                         declined=r.get("status") == "denied")
                        elif r.get("kind") == "attestation" and \
                                r.get("status") in ("pending", "approved", "denied"):
                            handled.add(key)
                            on_attestation(port, scope, r,
                                           approved=r.get("status") == "approved",
                                           declined=r.get("status") == "denied")
                        elif r.get("kind") == "experiment" and \
                                r.get("status") in ("pending", "approved", "denied"):
                            if on_experiment(port, scope, r,
                                             approved=r.get("status") == "approved",
                                             declined=r.get("status") == "denied") \
                                    or r.get("status") == "pending":
                                handled.add(key)
                        elif r.get("kind") == "dial" and \
                                r.get("status") in ("pending", "approved", "denied"):
                            handled.add(key)
                            on_dial(port, r,
                                    approved=r.get("status") == "approved",
                                    declined=r.get("status") == "denied")
                        elif r.get("kind") == "standing-charter" and \
                                r.get("status") in ("pending", "approved", "denied"):
                            handled.add(key)
                            on_standing_charter(
                                port, scope, r,
                                approved=r.get("status") == "approved",
                                declined=r.get("status") == "denied")
                        elif r.get("kind") == "reflex" and \
                                r.get("status") in ("pending", "approved", "denied"):
                            handled.add(key)
                            on_reflex(port, scope, r,
                                      approved=r.get("status") == "approved",
                                      declined=r.get("status") == "denied")
                    except urllib.error.HTTPError as e:
                        # The floor ANSWERED — a refusal, not a dead wire (probe()'s
                        # law). One poison request must never silence the residents:
                        # relay the refusal onto the record and let the round go on.
                        handled.add(key)
                        try:
                            err = json.loads(e.read() or b"{}").get("error") or str(e)
                        except Exception:
                            err = str(e)
                        print(f"  ↳ {r.get('id')} refused by the floor: {err}")
                        try:
                            call(port, "POST", "/requests/resolve",
                                 {"id": r["id"], "status": "done",
                                  "result": {"refused": err}})
                        except Exception:
                            pass                 # resting state can wait a cycle
                if beat_due:
                    collapse_gate_duplicates(port)  # pre-guard-era noise, tidied once
                    KEEPER.tend(port, scope)
                    WRANGLER.sync(port, scope)
                    serials_beat(port, scope)  # the desk sweeps on the beat (0032 §2)
                    embed_beat(port, scope)   # the vector projection fills (0022 Ph2)
                    continuity_charter(port, scope)  # a template floor gets its law (0034)
                    pin_organs(port, scope)
                    window_charter(port, scope)
                    if scope == SCOPE:
                        lib_charter(port, scope)
                    if scope == UNIVERSE_SCOPE:
                        monitor_beat(port)    # the standing job beats like an organ
                        improver_beat(port)   # and the improver reads the receipts
                        metabolism_wire_beat()  # forgetting on schedule (sp2)
                        yardstick_beat()   # manual dial only — JB's lock (0053 sp3)
                        scheduled_ask_beat()  # the standing word, honored weekly
                        stage_routing_revision()  # the yardstick's evidence rides the lane
                        epoch_beat()          # the machine keeps its name (0041)
                        attest_beat()         # and proves what it loaded (0041)
                        mirror_beat()         # the mirror reflects every floor (0034 sp3)
                        passage_beat()        # the silence watch — contain, never execute (0035 §3)
                        FLIGHT.beat()         # the Observatory's pulse (0043 sp1)
                        assay_beat(port)      # the Examiner, dial-gated (0043 sp2)
                        studio_tend(port)     # readings ride the plan cards (0047 sp3)
                        schedule_beat(port)   # the machine's cadence (0047 sp6)
                        reflex_beat(port)     # the reflex arc (0047 sp6)
                        feedback_beat(port)   # the words go back in (0048 sp3)
                        calibration_beat(port)  # human vs examiner (0048 sp4)
                        bell_beat(port)       # the bell tends its door (0044 sp2)
                        canon_seed(port)      # the firmware stands as records (0045 sp1)
                        verify_beat(port)     # the deed watchman, standing (0044 sp3 · L-B)
                        gate_age_beat(port)   # aged consequence rings once (0044 sp3)

            except Exception as e:
                scopes.pop(port, None)
                FLOOR_SCOPES.pop(port, None)
                # name the true thrower — "unreachable" once blamed a healthy
                # floor for a beat organ's stumble (the 432 lesson, 2026-07-25)
                tb = getattr(e, "__traceback__", None)
                site = "?"
                while tb is not None:
                    if tb.tb_frame.f_code.co_filename.endswith("console_worker.py"):
                        site = f"{tb.tb_frame.f_code.co_name}:{tb.tb_lineno}"
                    tb = tb.tb_next
                _dscopes = _down_load()
                if FLOOR_SCOPES.get(port) in _dscopes or any(
                        int(pp) == port for pp, vv in SHIPYARD.ledger().items()
                        if vv.get("scope") in _dscopes):
                    pass          # dark by the human's word — quiet, not broken
                else:
                    print(f"  (floor :{port} stumbled at {site}…)", e)
        tend_self_dialogs()                   # compose any dialog whose legs are home
        tend_objectives()                     # review and assemble what rode back up
        if beat_due:
            KEEPER.last_beat = time.time()
        time.sleep(2)


if __name__ == "__main__":
    main()
